COLLDATA("tafsirnoor","ur",[[6099,"§اللہ کی تخلیق کے مختلف طریقے\nیعنی ایک بیج سے تناور درخت بنا کھڑا کرنے کی صورت اور ہے۔ بے جان غذاؤں سے نطفہ اور نطفہ سے حیوانات اور انسان کو پیدا کر دکھانے کی صورت اور ہے۔ اور کسی مردہ انسان کے گلے سڑے اجزاء کو ملا کر اکٹھا کرکے ان کو زندہ کھڑا کر دینے کی صورت اور ہے۔ غرضیکہ کائنات میں تخلیق کئی صورتوں سے ہو رہی ہے اور اللہ چونکہ خود ہر چیز کا خالق ہے۔ لہٰذا وہ ان سب طریقوں اور صورتوں کو پوری طرح جانتا ہے اور انسان جو ان صورتوں میں کوئی ایک صورت بھی نہیں جانتا نہ جان سکتا ہے وہ اپنے خیال اور اپنی محدود عقل کے مطابق ہم پر مثالیں چسپاں کرتا ہے۔"],[6100,"§اللہ نے ہر مردہ میں زندہ اور زندہ میں مردے کی خاصیت رکھ دی ہے\nیعنی درخت کو پانی سے پیدا کیا۔ پھر آخر میں اسے ایندھن بناکر اس سے آگ نکالی۔ درخت کاآغاز پانی سے ہوا اور انتہا آگ پر ہوئی اور یہ دونوں چیزیں ایک دوسرے کی ضد بلکہ ایک لحاظ سے ایک دوسرے کی دشمن ہیں۔ آگ تھوڑی مقدار میں ہو توپانی اس کا وجود ختم کر دیتاہے۔ اور پانی کم مقدار میں ہو تو آگ اسے آبی بخارات میں تبدیل کرکے اسے ختم کر دیتی ہے۔\nپھر جب اللہ تعالیٰ ایک ہی چیز کے آغاز اور انجام میں متضاد صفات پیدا کر سکتے ہیں تو پھر ایک ہی چیز کو زندہ سے مردہ اور مردہ سے زندہ کیوں نہیں بناسکتے۔ یہ تو عام درختوں اور پودوں کا حال ہے۔ پھر کچھ درخت ایسے بھی ہیں جن کی ٹہنیاں رگڑنے سے اس طرح آگ پیدا ہوجاتی ہے جس طرح چقماق پتھر سے پیدا ہوتی ہے۔ اور کچھ ایسے بھی ہیں جن کی ٹہنیاں موم بتی کی طرح جلتی ہیں۔ کیونکہ ان میں روغن خاصی مقدار میں موجود ہوتا ہے۔ غرضیکہ ہر درخت اورپودا جوپانی سے پیدا ہوا ہے اس کے اندر بھی آتش گیری کی صفات رکھ دی گئی ہیں۔ بالکل اسی طرح ہر مردہ میں زندہ ہونے اور زندہ میں مرنے کی صفت بھی فطری طور پر رکھ دی گئی ہے۔\nیعنی جو اللہ تعالیٰ انسان کو ایک حقیر نطفے سے پیدا کرتا ہے، وہ دوبارہ اس کو زندہ کرنے پر قادر نہیں ہے؟ اس کی قدرت احیائے موتیٰ کا ایک واقعہ حدیث میں بیان کیا گیا ہے کہ ایک شخص نے مرتے وقت وصیت کی کہ مرنے کے بعد اسے جلا کر اس کی آدھی راکھ سمندر میں اور آدھی راکھ تیز ہوا والے دن خشکی میں اڑا دی جائے۔ اللہ تعالیٰ نے ساری راکھ جمع کر کے اسے زندہ فرمایا اور اس سے پوچھا تو نے ایسا کیوں کیا؟ اس نے کہا، تیرے خوف سے۔ چنانچہ اللہ نے اسے معاف فرما دیا۔\n(صحیح البخاری)\nاَوَ لَمْ يَرَ الْاِنْسَانُ اَنَّا خَلَقْنٰهُ مِنْ نُّطْفَةٍ : جب کچھ لوگوں نے قیامت کے دن اٹھائے جانے کو بعیداز عقل قرار دیا اور اپنے آغاز کو بھول گئے کہ انھیں کس طرح پیدا کیا گیا اور برملا انھوں نے اعتراض کیا کہ ان بوسیدہ ہڈیوں میں کس طرح دوبارہ زندگی واپس آئے گی تو اللہ تعالیٰ نے ان کے اشتباہ کو دور کردیا اور آگاہ کیا کہ جس نے ان کو پہلے عدم سے وجود عطا کیا وہ ذات انھیں موت کے بعد زندہ کرنے پر بھی قادر ہے اور اس ذات کو اجزاء کی تفاصیل کا علم ہے جب وہ بوسیدہ ہو کر متفرق ہوگئے اور کئی حصوں میں منقسم ہوگئے جو شخص موت کے بعد اٹھائے جانے کا انکار کرتا ہے اسے غور کرنا چاہیے کہ جس ذات نے انسان کو اولاً پیدا کیا ہے پھرا سے سیدھا قد عطا کیا وہ اپنے پروردگار کے بارے میں جھگڑا کررہا ہے کہ وہ بوسیدہ ہڈیوں میں کس طرح زندگی ڈال دے گا وہ اللہ تعالیٰ کی قدرت کا انکار کررہا ہے ظاہر ہے کہ جس ذات نے اولاً انسان کو ذلیل پانی سے پیدا کیا ہے وہ اس کو موت کے بعد بھی زندہ کرنے پر قادر ہے زندہ کرنے کے بعد محاسبہ ہوگا اور اعمال پر جزا و سزا کا انحصار ہوگا۔\nوَ ضَرَبَ لَنَا مَثَلًا وَّ نَسِيَ خَلْقَهٗ١ؕ: انسان نے ایک اور عجیب بات کہی کہ وہ مخلوق کو دوبارہ زندگی عطا کرنے کی قدرت کا انکار کرتا ہے اور برملاکہتا ہے کہ ان بوسیدہ ہڈیوں میں کون زندگی ڈال سکتا ہے وہ شخص بھول گیا ہے کہ ہم نے اس کو کیسے پیدا کیا ہم نے اس کو نطفہ سے پیدا کیا اور انسان سیدھے قدکاوجود میں آیا اور جو ذات اس پر قادر ہے تو وہ فوت شدہ لوگوں کو دوبارہ زندگی عطا کرسکتا ہے۔\nقُلْ يُحْيِيْهَا الَّذِيْۤ اَنْشَاَهَاۤ اَوَّلَ مَرَّةٍ١ؕ: اے پیغمبر! صلی اللہ علیہ وسلم آپ اس مشرک شخص کو آگاہ کریں جو دوبارہ زندگی کو بعیدازعقل وفہم قرار دیتا ہے کہ کون بوسیدہ ہڈیوں میں زندگی کی لہر پیدا کرتا ہے جواب واضح ہے کہ جس ذات نے اس کو پہلی مرتبہ پیدا کیا ہے اور وہ کچھ نہ تھا اس ذات کو معلوم ہے کہ اس انسان کی ہڈیاں کہاں کہاں متفرق ہیں اللہ کی ذات پر اس کی مخلوق کی کوئی چیز ہرگز پوشیدہ نہیں ہے وہ اس کو دوبارہ اسی حالت پر لانے کی قدرت رکھتا ہے۔\nا۟لَّذِيْ جَعَلَ لَكُمْ مِّنَ الشَّجَرِ الْاَخْضَرِ نَارًا : ان کا موت کے بعد اٹھائے جانے کو بعید از عقل قرار دینے کے مغالطے کو دور کرتے ہوئے اور ان کے انکار کو باطل قرار دیتے ہوئے واضح کیا ہے کہ تمہیں بوسیدہ ہڈیوں سے دوبارہ پیدا کرنا آسمانوں اور زمین کی تخلیق سے زیادہ حیران کن نہیں ہے اور جب اللہ نے آسمان کو اور زمین کو پیدا کیا ہے تو اس پر کچھ مشکل نہیں ہے کہ وہ بوسیدہ ہڈیوں سے انسان کو دوبارہ زندگی عطا کرے اس کے بعد اللہ کی عظیم سلطنت اور وسیع قدرت کو ثابت کیا ہے کہ اللہ پاک کی شان بہت بلند ہے وہ جب کسی چیز کے ایجاد کرنے کا ارادہ کرتا ہے تو وہ کہتا ہے کہ یہ کام ہوجائے تو وہ فورا ہوجاتا ہے۔\nاور جب اللہ نے اپنی ذات کے لیے مکمل قدرت اور بالعموم بادشاہت کو ثابت کیا تو اس نے اپنی ذات کو ان اوصاف سے منزہ قرار دیا ہے جن کے ساتھ مشرکین نے اللہ کو موصوف قرار دیا تھا تو فرمایا ہمارا پروردگار منزہ ہے وہ ہمیشہ زندہ ہے قائم ہے اس کے ہاتھ میں آسمان زمین کی چابیاں ہیں وہ ہر عیب سے پاک ہے اور قیامت کے دن تم سب نے اس کی جانب لوٹنا ہے وہ ہر شخص کو اس کے عمل کے مطابق بدلہ دے گا وہ ذات عادل ہے انعامات کرنے والی ہے مہربان ہے۔\nاَوَ لَيْسَ الَّذِيْ خَلَقَ السَّمٰوٰتِ وَ الْاَرْضَ بِقٰدِرٍ عَلٰۤى اَنْ يَّخْلُقَ مِثْلَهُمْ١ؐؕ بَلٰى ١ۗ\nوَهُوَ الْخَلّٰقُ الْعَلِيْمُ۰۰۸۱ اِنَّمَاۤ اَمْرُهٗۤ اِذَاۤ اَرَادَ شَيْـًٔا اَنْ يَّقُوْلَ لَهٗ كُنْ فَيَكُوْنُ۰۰۸۲\nفَسُبْحٰنَ الَّذِيْ بِيَدِهٖ مَلَكُوْتُ كُلِّ شَيْءٍ وَّ اِلَيْهِ تُرْجَعُوْنَؒ۰۰۸۳\nکیا وہ (اللہ) جس نے آسمانوں اور زمین کو پیدا کیا اس بات پر قادر نہیں کہ وہ ان جیسے (انسان) پیدا کردے؟ کیوں نہیں! وہی تو (سب کچھ) پیدا کرنے والا، خوب جاننے والا ہے جب وہ کسی چیز کا ارادہ کرتا ہے تو اس کا حکم صرف یہ ہوتا ہے کہ وہ اس سے کہتا ہے : ہو جا تو وہ ہوجاتی ہے, چنانچہ پاک ہے وہ (اللہ) جس کے ہاتھ میں ہر چیز کی بادشاہی ہے اور اسی کی طرف تم\nلوٹائے جائو گے.\nاللہ تعالیٰ نے اپنی عظیم الشان قدرت کو بیان کرتے ہوئے فرمایا ہے کہ اس نے ساتوں آسمانوں کو ثوابت اور سیاروں کے ساتھ پیدا فرمایا اور ساتوں زمینوں کو ان کے پہاڑوں، صحرائوں، دریائوں اور جنگلوں کے ساتھ وجود بخشا ہے اور اپنی اس عظیم الشان قدرت کے حوالے سے اس استدلال کی طرف اس نے ہماری رہنمائی فرمائی ہے کہ جس ذات پاک نے ان عظیم الشان اشیا کو تخلیق فرمایا ہے وہ مرنے کے بعد ان جسموں کو دوبارہ زندہ کرنے پر بھی قادر ہے جیسا کہ فرمایا:﴿لَخَلْقُ السَّمٰوٰتِ وَ الْاَرْضِ اَكْبَرُ مِنْ خَلْقِ النَّاسِ ﴾ (المؤمن:57) ’’آسمانوں اور زمین کا پیدا کرنا لوگوں کے پیدا کرنے کی نسبت زیادہ بڑا (کام) ہے۔‘‘\nاور یہاں اللہ تعالیٰ نے فرمایا ہے: ﴿اَوَ لَيْسَ الَّذِيْ خَلَقَ السَّمٰوٰتِ وَ الْاَرْضَ بِقٰدِرٍ عَلٰۤى اَنْ يَّخْلُقَ مِثْلَهُمْ١ؐؕ ﴾ ’’بھلا جس نے آسمانوں اور زمین کو پیدا کیا، کیا وہ اس بات پر قادر نہیں کہ (ان کو پھر) ویسے ہی پیدا کر دے۔‘‘ یعنی انسانوں کو جس طرح اس نے پہلے پیدا کیا تھا، کیا وہ اس طرح ان کو دوبارہ پیدا کرنے پر قادر نہیں ہے؟\nامام ابن جریر رحمہ اللہ فرماتے ہیں کہ یہ آیت اس آیت کریمہ کی طرح ہے: ﴿اَوَ لَمْ يَرَوْا اَنَّ اللّٰهَ الَّذِيْ خَلَقَ السَّمٰوٰتِ وَ الْاَرْضَ وَ لَمْ يَعْيَ بِخَلْقِهِنَّ بِقٰدِرٍ عَلٰۤى اَنْ يُّحْيِۧ الْمَوْتٰى ١ؕ بَلٰۤى اِنَّهٗ عَلٰى كُلِّ شَيْءٍ قَدِيْرٌ۰۰۳۳﴾ (الأحقاف:33) ’’کیا انہوں نے نہیں دیکھا کہ جس اللہ نے آسمانوں اور زمین کو پیدا کیا اور ان کے پیدا کرنے سے اکتایا نہیں وہ اس (بات) پر بھی قادر ہے کہ مردوں کو زندہ کر دے۔ ہاں، بلاشبہ وہ ہر چیز پر خوب قادر ہے۔‘‘ اور اللہ تبارک وتعالیٰ نے یہاں فرمایا ہے:﴿بَلٰى ١ۗ وَ هُوَ الْخَلّٰقُ الْعَلِيْمُ۰۰۸۱اِنَّمَاۤاَمْرُهٗۤ اِذَاۤ اَرَادَ شَيْـًٔا اَنْ يَّقُوْلَ لَهٗ كُنْ فَيَكُوْنُ۰۰۸۲﴾ ’’کیوں نہیں! اور وہ تو بڑا پیدا کرنے والا، خوب جاننے والا ہے، اس کا معاملہ تو بس یہ ہے کہ وہ جب کسی چیز کا ارادہ کرتا ہے تو اس سے فرما دیتا ہے کہ ہو جا، تو وہ ہو جاتی ہے۔‘‘ یعنی وہ کسی چیز کو صرف ایک ہی بار حکم دیتا ہے، اسے تکرار یا تاکید کی ضرورت نہیں ہے۔\nجیسا کہ کسی شاعر نے بھی کہا ہے:\nإِذَا مَا أَرَادَ اللہُ أَمْرًا فَإِنَّمَا\nیَقُوْلُ لَہٗ کُنْ قَوْلَۃً فَیَکُوْنُ\n’’اللہ جب کسی چیز کا ارادہ فرماتا ہے تو اسے ایک ہی بار فرماتا ہے کہ ہو جا تو وہ ہو جاتی ہے۔‘‘\nاور امام احمد رحمہ اللہ نے ابو ذر رضی اللہ عنہ سے روایت کیا ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’یقیناً اللہ تعالیٰ ارشاد فرماتا ہے کہ اے میرے بندو! تم میں سے ہر شخص گناہگار ہے سوائے اس کے جسے میں بچا لوں تو تم مجھ سے گناہوں کی بخشش مانگو، میں تمہیں معاف فرما دوں گا .... اور تم میں سے ہر ایک فقیر ہے، سوائے اس کے جس کو میں غنی کر دوں ....، بے شک میں جواد، ماجد اور واجد ہوں، میں وہ کرتا ہوں جو میں چاہتا ہوں، میں نے عطا کرنا ہو تو فرما دیتا ہوں اور عذاب دینا ہو تو پھر بھی فرما دیتا ہوں اور جب کسی بھی چیز کا ارادہ کرتا ہوں، تو بس اسے فرما دیتا ہوں کہ ہو جا تو وہ ہو جاتی ہے۔‘‘ (مسند أحمد)\nاور ارشاد باری تعالیٰ ہے: ﴿فَسُبْحٰنَ الَّذِيْ بِيَدِهٖ مَلَكُوْتُ كُلِّ شَيْءٍ وَّ اِلَيْهِ تُرْجَعُوْنَؒ۰۰۸۳﴾ ’’تو وہ ذات پاک ہے جس کے ہاتھ میں ہر چیز کی بادشاہت ہے اور اسی کی طرف تمہیں لوٹ کر جانا ہے۔‘‘ یعنی ہر قسم کی برائی سے منزہ، مقدس اور پاک ہے، وہ زندہ اور قائم ہے جس کے ہاتھوں میں آسمانوں اور زمین کی کنجیاں ہیں اور اس کی طرف سارا معاملہ لوٹتا ہے، سب مخلوق بھی اس کی ہے اور سب حکم بھی اس کا ہے، روز قیامت تمام بندے بھی اس کے پاس لوٹ کر جائیں گے، وہ ہر کام کرنے والے کو اس کے اعمال کے مطابق بدلہ دے گا، وہ عدل فرمانے والا، انعام سے نوازنے والا اور اپنے فضل وکرم سے سرفراز فرمانے والا ہے۔ ﴿فَسُبْحٰنَ الَّذِيْ بِيَدِهٖ مَلَكُوْتُ كُلِّ شَيْءٍ ﴾ کے معنی اس آیت کریمہ کی طرح ہیں: ﴿قُلْ مَنْۢ بِيَدِهٖ مَلَكُوْتُ كُلِّ شَيْءٍ ﴾ (المؤمنون:88) ’’کہہ دیں کہ کون ہے جس کے ہاتھ میں ہر چیز کی بادشاہی ہے۔‘‘ یا اس آیت کریمہ کی طرح ہیں: ﴿تَبٰرَكَ الَّذِيْ بِيَدِهِ الْمُلْكُ١ٞ﴾ (الملک:1) ’’وہ (اللہ) جس کے ہاتھ میں بادشاہی ہے، بابرکت ہے۔‘‘ ملک اور ملکوت کے ایک ہی معنی ہیں جس طرح رحمت اور رحموت، رھبة اور رھبوت، جبر اور جبروت کے ایک ہی معنی ہیں۔ بعض لوگوں کا خیال ہے کہ ’’ملک‘‘ سے مراد عالم اجسام اور ’’ملکوت‘‘ سے مراد عالم ارواح ہے لیکن صحیح پہلی بات ہے اور جمہور مفسرین وغیرہ کا بھی یہی قول ہے۔\nامام احمد رحمہ اللہ نے حذیفہ بن یمان رضی اللہ عنہما سے روایت کیا ہے کہ میں نے ایک رات رسول اللہ صلی اللہ علیہ وسلم کے ساتھ قیام کیا تو آپ صلی اللہ علیہ وسلم نے سات رکعتوں میں سات طویل سورتوں کی تلاوت فرمائی، آپ صلی اللہ علیہ وسلم جب رکوع سے سر اٹھاتے تو یہ پڑھتے:(سَمِعَ اللہُ لِمَنْ حَمِدَہٗ) پھر یہ کلمات پڑھتے: ’’سب تعریفیں اس اللہ ہی کے لیے ہیں جو وسیع سلطنت، عظیم اقتدار اور بڑائی وبزرگی کا مالک ہے۔‘‘ آپ صلی اللہ علیہ وسلم کا رکوع بھی قیام کی طرح طویل اور سجدہ بھی رکوع کی طرح طویل تھا، آپ صلی اللہ علیہ وسلم جب نماز سے فارغ ہوئے تو میرے پائوں پوٹنے کے قریب تھے۔ (مسند أحمد) اور امام ابو دائود رحمہ اللہ نے عوف بن مالک اشجعی رضی اللہ عنہ سے روایت کیا ہے کہ میں نے ایک رات رسول اللہ صلی اللہ علیہ وسلم کے ساتھ قیام کیا، آپ صلی اللہ علیہ وسلم نے کھڑے ہو کر سورۂ بقرہ کی تلاوت شروع فرما دی، جب کسی ایسی آیت کے پاس سے گزرتے جس میں اللہ تعالیٰ کی رحمت کا ذکر ہوتا تو آپ صلی اللہ علیہ وسلم ٹھہر جاتے اور اللہ تعالیٰ سے رحمت کا سوال کرتے اور جب کسی ایسی آیت کے پاس سے گزرتے جس میں اللہ تعالیٰ کے عذاب کا ذکر ہوتا تو آپ صلی اللہ علیہ وسلم ٹھہر جاتے اور اللہ تعالیٰ کے عذاب سے پناہ مانگتے، پھر آپ نے قیام کے بقدر رکوع کیا اور رکوع میں یہ کلمات پڑھتے تھے: ’’پاک ہے وہ ذات جو عظیم اقتدار، وسیع سلطنت اور بڑائی و بزرگی کی مالک ہے۔‘‘ پھر آپ صلی اللہ علیہ وسلم نے قیام کے برابر سجدہ کیا اور سجدے میں بھی یہی کلمات پڑھے، پھر آپ صلی اللہ علیہ وسلم نے (دوسری رکعت کے لیے) کھڑے ہو کر آل عمران کو پڑھا، پھر ایک ایک سورت پڑھی۔ (سنن أبی داؤد، حدیث: 873) اور اسے امام ترمذی رحمہ اللہ نے شمائل میں اور امام نسائی رحمہ اللہ نے بھی روایت کیا ہے۔ (الشمائل المحمدیة، حدیث:313)"],[6101,"§درختوں کے فائدے اور آگ کا حصول\nآسمانوں اور زمین جیسی عظیم مخلوق کو بھی دیکھ لو اور اپنے آپ پر بھی نظر ڈال کر دیکھ لو کہ ان کے مقابلہ میں تمہاری یا تم جیسوں کی کیاحیثیت اور حقیقت ہے ؟ پھر جب اللہ تعالیٰ نے آسمانوں اور زمین کو پیدا کیا ہے تو کیا تمہیں بھی وہ دوبارہ پیدا نہ کر سکے گا حالانکہ وہ تخلیق کے تمام طریقوں کو خوب جانتا ہے۔"],[6102,"§اللہ کے کلمہ کن کہنے کا مفہوم\nکن یا’’ہوجا‘‘ کا ایک مفہوم تویہ ہے کہ کوئی چیز عدم سے وجود میں آجائے۔ ایسے اُمور میں بالعموم اللہ کا قانونِ تدریج کام کرتا ہےجیساکہ اس نے آسمانوں اور زمین کو چھ ایام (یا چھ ادوار) میں بنایا۔ اگرچہ اس کی قدرت سے یہ بھی مستبعد نہیں کہ فوراً کسی چیز کو عدم سے وجود میں لے آئے۔ اور اس کا دوسرا مفہوم یہ ہے کہ جس چیز کو اللہ نے کسی کام اور جس مقصد کے لیے بنایا ہے وہ چیز فوراً وہ کام شروع کر دے۔ اس کے لیے صرف اللہ کے امر کی ضرورت ہے اور وہ کام اسی وقت ہونا شروع ہوجاتا ہے اور اللہ کے اس امر کو ہم روح بھی کہہ سکتے ہیں۔ اور اس کی مثال یوں سمجھو کہ جیسے کسی کارخانے میں بڑی بڑی دیوہیکل برقی مشینیں نصب ہوتی ہیں۔ مگر وہ اس وقت تک بے حس و حرکت کھڑی رہتی ہیں جب تک ان میں برقی رو نہ گزاری جائے یا سوئچ آن نہ کیاجائے۔ سوئچ آن کرنے کی دیر ہوتی ہے کہ وہ فوراً متحرک ہو کر اپنا وہ کام کرنا شروع کر دیتی ہیں جس کا م کے لیے بنائی گئی تھیں۔ بالکل یہی صورت اللہ تعالیٰ کے امر ’’کن‘‘ کی ہے اور ادھر اللہ نے ارادہ کیا ادھر وہ چیز بن گئی جو مطلوب تھی۔ مقصد یہ ہے کہ تمام انسانوں کی دوبارہ پیدائش بھی فقط اللہ کے ایک اشارے یا ارادے یا امرکن کی محتاج ہے۔ ادھر اللہ تعالیٰ ارادہ کرے گا تو فوراً تما م انسان زندہ ہو کر اللہ کے سامنے حاضر ہو جائیں گے اور انسانوں کے لیے یہ اضطراری امر ہوگا جس کے بغیر انہیں کوئی چارہ نہ ہوگا۔\nیعنی انسانوں جیسے۔ مطلب، انسانوں کا دوبارہ پیدا کرنا ہے جس طرح انہیں پہلی مرتبہ پیدا کیا۔ آسمان و زمین کی پیدائش سے انسانوں کو دوبارہ پیدا کرنے پر استدلال کیا ہے۔ جس طرح دوسرے مقام پر فرمایا: ﴿لَخَلْقُ السَّمٰوٰتِ وَ الْاَرْضِ اَكْبَرُ مِنْ خَلْقِ النَّاسِ ﴾ (المؤمن:75) ’’آسمان و زمین کی پیدائش (لوگوں کے نزدیک) انسانوں کی پیدائش سے زیادہ مشکل کام ہے۔‘‘\nنام : سور ت کی پہلی آیت میں ہی لفظ ’’الصافات‘‘آیا ہے، یہی اس کا نام رکھ دیا گیا ہے۔ صاحب محاسن التنزیل نے مفسر مہایمی سے نقل کیا ہے کہ اس آیت ِ کریمہ میں فرشتوں کی ایسی صفات بیان کی گئی ہیںجواُن سے الوہیت کی نفی کرتی ہیں، انہی صفات میں سے صفت ’’صافات‘‘ بھی ہے۔ اور فرشتوں سے الوہیت کی نفی ہو گئی تو دوسری مخلوقات سے بدرجہ اولیٰ اس کی نفی ہو گئی اور اللہ تعالیٰ کی وحدانیت ثابت ہو گئی۔ اسی مناسبت سے اس سورت کا نام ’’الصافات‘‘ رکھ دیا گیا ہے۔"],[6103,"§زمانۂ نزول\nقرطبی رحمہ اللہ نے لکھا ہے کہ یہ سورت سب کے نزدیک مکی ہے۔ ابن عباس رضی اللہ عنہما کا یہی قول ہے۔\nآخر ی مکی دور کی سورتوں کی طرح اس میں بھی کفارِ مکہ کو دھمکی دی جا رہی ہے اور ان سے کہاجا رہا ہے کہ ایک دن آئے گا کہ نبی صلی اللہ علیہ وسلم اور ان کے صحابہ رضی اللہ عنہم غالب ہوں گے اور انہیں ذلت و رسوائی کا سامنا کرنا پڑے گا۔ دھمکی کے ساتھ قرآنِ کریم نے اپنے خاص اسلوب میں توحید و آخرت کا عقیدہ بھی بیان کیا ہے اور مختلف پیرائے میں انہیں ایمان کی ترغیب بھی دلائی ہے۔\nاس سورت کا شمار مکی سورتوں میں سے ہوتا ہے کہ یہ سورت قبل از ہجرت مکہ مکرمہ میں نازل ہوئی اس سورت میں اسلامی عقائد کے بیان کرنے کا اہتمام کیا گیا ہے مقصود مسئلہ توحید اور وحی اور قیامت کے دن اٹھائے جانے اور مکافات عمل کی وضاحت ہے اور واضح کیا گیا ہے کہ ایمان کے بنیادی ستون کیا کیا ہیں اس سورت کے آغاز میں فرشتوں کا تذکرہ ہے اور ان میں کچھ فرشتے ایسے ہیں جو نماز کی ادائیگی میں صف باندھے ہوئے ہیں یا وہ احکام الٰہیہ کے منتظر رہتے ہیں کہ کب انھیں ان کی ادائیگی کا حکم دیاجاتا ہے کچھ فرشتے اللہ کی مشیت کے مطابق بادلوں کو چلاتے ہیں۔\nمزید اس سورت میں جنوں کا تذکرہ ہے جن پر شہاب ثاقب گرتے ہیں وہ انھیں ملیامیٹ کردیتے ہیں ان کے بیان کے دوران دور جاہلیت کے اس نظریہ کا رد کیا گیا ہے کہ ان کا تعلق اللہ کے ساتھ ہے اور ہمارے اللہ اور ان کے درمیان وساطت کا فریضہ جن سرانجام دیتے ہیں مزید برآں قبروں سے اٹھائے جانے جزاو سزا کا مسئلہ لیکن مشرکین کا اس کو تسلیم نہ کرنا اور ان کا یہ کہنا کہ جب ہماری ہڈیاں بوسیدہ ہوجائیں گی تو ہمیں کیسے دوبارہ اٹھایا جائے گا اور آخرت کے عقیدہ کے اثبات کے لیے اس میں ایک مومن اور ایک کافر کا واقعہ بیان کیا گیا ہے اور دنیوی زندگی میں ان کے درمیان ہونے والی گفتگو کا ذکر کیا گیا ہے اور بعدازاں اس نتیجہ کو پیش کیا گیا کہ مومن شخص ہمیشہ جنت میں جب کہ کافر شخص ہمیشہ دوزخ میں رہے گا۔\nمزید برآں اس سورت میں بعض انبیاء علیہم السلام کے واقعات ذکر کیے گئے ہیں نوح، ابراہم، اسماعیل، موسیٰ، ہارون الیاس، لوط علیہم السلام اور پیغمبروں کے واقعات کو بیان کیا گیا ہے، چنانچہ پیغمبر اسماعیل علیہ السلام ذبیح اللہ کے واقعہ کا بیان ہے اس سلسلہ میں اس خواب کا بیان ہے جو ابراہیم علیہ السلام کو دکھایا گیا پھر اسماعیل علیہ السلام کو فدیہ مینڈھا عطا کیا جانا۔\nوَ الصّٰٓفّٰتِ صَفًّاۙ۰۰۱ فَالزّٰجِرٰتِ زَجْرًاۙ۰۰۲ فَالتّٰلِيٰتِ ذِكْرًاۙ۰۰۳ اِنَّ اِلٰهَكُمْ لَوَاحِدٌؕ۰۰۴\nرَبُّ السَّمٰوٰتِ وَ الْاَرْضِ وَ مَا بَيْنَهُمَا وَ رَبُّ الْمَشَارِقِؕ۰۰۵\nاللہ کے نام سے (شروع) جونہایت مہربان، بہت رحم کرنے والا ہے۔\nقسم ہے قطار در قطار صفیں باندھنے والوں (فرشتوں) کی1 پھر جھڑک کر ڈانٹنے والوں کی2 پھر قرآن کی تلاوت کرنے والوں کی3 بلاشبہ تمھارا معبود ایک ہی ہے4 (وہی) رب ہے آسمانوں اور زمین کا اور(اس کا بھی) جوکچھ ان دونوں کے درمیان\nہے اور (تمام)مشرقوں کا رب ہے5"],[6104,"§فضیلت\nامام نسائی رحمہ اللہ نے عبداللہ بن عمر رضی اللہ عنہما سے روایت کیا ہے کہ رسول اللہ صلی اللہ علیہ وسلم ہمیں تخفیف کا حکم دیا کرتے تھے اور ہمیں نماز پڑھاتے ہوئے آپ صلی اللہ علیہ وسلم صافات کی تلاوت فرمایا کرتے تھے۔ اس روایت کو صرف امام نسائی رحمہ اللہ نے روایت کیا ہے۔ (السنن الکبریٰ حدیث:11432)"],[6105,"§فرشتے اللہ تعالیٰ کی توحید کے گواہ ہیں\nعبداللہ بن مسعود رضی اللہ عنہ سے روایت ہے کہ ﴿وَ الصّٰٓفّٰتِ صَفًّاۙ۰۰۱﴾ سے مراد فرشتے ہیں۔ ﴿فَالزّٰجِرٰتِ زَجْرًاۙ۰۰۲﴾ اور ﴿فَالتّٰلِيٰتِ ذِكْرًاۙ۰۰۳﴾ سے مراد بھی فرشتے ہیں۔ (تفسیر ابن أبی حاتم:3204/10) اور اسی طرح ابن عباس رضی اللہ عنہما، مسروق، سعید بن جبیر، عکرمہ، مجاہد، سدی، قتادہ اور ربیع بن انس رحمہ اللہ کا بھی یہی قول ہے۔ (تفسیر القرطبی:61/15،62) قتادہ رحمہ اللہ کہتے ہیں کہ فرشتے آسمانوں میں صفیں باندھے ہوئے ہیں۔ (تفسیر الطبری:41/23) اور امام مسلم رحمہ اللہ نے حذیفہ رضی اللہ عنہ سے روایت کیا ہے، انہوں نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ہمیں لوگوں پر تین چیزوں میں فضیلت دی گئی ہے: (1) ہماری صفوں کو فرشتوں کی صفوں کی طرح بنا دیا گیا ہے۔ (2) اور ساری زمین کو ہمارے لیے مسجد بنا دیا گیا ہے۔ (3) اور اگر ہم پانی نہ پائیں تو اس کی مٹی کو ہمارے لیے ذریعہ طہارت بنا دیا گیا ہے۔‘‘ (صحیح مسلم، حدیث: 522)\nاور امام مسلم رحمہ اللہ ہی نے، نیز ابو دائود، نسائی اور ابن ماجہ رحمہ اللہ نے جابر بن سمرہ رضی اللہ عنہ سے روایت کیا ہے، انہوں نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’تم اس طرح صفیں کیوں نہیں بناتے جس طرح فرشتے اپنے رب کے پاس صفیں بناتے ہیں؟ ہم نے عرض کی: فرشتے اپنے رب کے پاس کس طرح صفیں بناتے ہیں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: وہ پہلے اگلی صفوں کو پورا کرتے ہیں اور وہ صف کو سیسہ پلائی ہوئی دیوار کی طرح بناتے ہیں۔‘‘ (صحیح مسلم، حدیث:430)\nسدّی رحمہ اللہ وغیرہ نے کہا ہے کہ ﴿فَالزّٰجِرٰتِ زَجْرًاۙ۰۰۲﴾ کے معنی یہ ہیں کہ فرشتے بادلوں کو ڈانٹتے اور جھڑکتے ہیں اور انہوں نے ﴿فَالتّٰلِيٰتِ ذِكْرًاۙ۰۰۳﴾ کے معنی یہ بیان کیے ہیں کہ وہ کتابوں اور قرآن مجید کو اللہ تعالیٰ کی طرف سے لوگوں کے پاس لاتے ہیں۔ (تفسیر الطبری: 41/23،42)"],[6106,"§اللہ تعالیٰ ہی معبود حقیقی ہے\nارشاد باری تعالیٰ ہے: ﴿اِنَّ اِلٰهَكُمْ لَوَاحِدٌؕ۰۰۴رَبُّ السَّمٰوٰتِ وَ الْاَرْضِ ﴾ ’’بے شک تمہارا ایک ہی الٰہ ہے، جو آسمانوں اور زمین کا مالک ہے۔‘‘ اس پر قسم کھائی گئی ہے کہ اللہ تعالیٰ کے سوا کوئی معبود نہیں اور وہی آسمانوں اور زمین کا مالک ہے، ﴿وَ مَا بَيْنَهُمَا ﴾ ’’اور جو کچھ ان دونوں میں ہے۔‘‘ یعنی مخلوقات، ﴿وَ رَبُّ الْمَشَارِقِؕ۰۰۵﴾ ’’اور سورج کے طلوع ہونے کے مقامات کا بھی مالک ہے۔‘‘ وہ مالک ومتصرف ہے۔ کواکب، ثوابت اور سیاروں کو اس نے مسخر فرما رکھا ہے جو مشرق سے طلوع ہوتے اور مغرب میں غروب ہو جاتے ہیں لیکن صرف مشارق کا ذکر اس لیے کیا گیا ہے کہ یہ مغارب پر خود بخود دلالت کر رہا ہے، اس کی صراحت اس ارشاد باری تعالیٰ میں ہے:﴿فَلَاۤ اُقْسِمُ بِرَبِّ الْمَشٰرِقِ وَ الْمَغٰرِبِ اِنَّا لَقٰدِرُوْنَۙ۰۰۴۰﴾ (المعارج:40) ’’ہمیں مشرقوں اور مغربوں کے مالک کی قسم کہ بلاشبہ ہم البتہ طاقت رکھتے ہیں۔‘‘ اور دوسرے مقام پر فرمایا: ﴿رَبُّ الْمَشْرِقَيْنِ وَ رَبُّ الْمَغْرِبَيْنِۚ۰۰۱۷﴾ (الرحمٰن:17) ’’وہی دونوں مشرقوں اور دونوں مغربوں کا مالک ہے۔‘‘ یعنی سورج اور چاند کے موسم گرما وسرما میں الگ الگ مشرق ومغرب ہیں۔\nاللہ تعالیٰ نے اس سورت ِکریمہ کی ابتداء فرشتوں کی قسم کھا کر اپنی ذات کے لیے اثبات وحدانیت کے ذریعہ کی ہے۔ عبداللہ بن مسعود، عبداللہ بن عباس رضی اللہ عنہم، عکرمہ،سعید بن جبیر، مجاہد اور قتادہ رحمہ اللہ وغیرہم کا خیال ہے کہ ’’الصافات‘‘ سے مراد وہ فرشتے ہیں جو آسمان میں اپنے رب کے سامنے صفیں باندھ کر کھڑے ہوتے ہیں۔ مسلم رحمہ اللہ کی روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا:’’کیا تم لوگ اسی طرح صفیں نہیں باندھو گے جس طرح فرشتے اپنے رب کے حضور صفیں باندھتے ہیں؟ لوگوں نے پوچھا: فرشتے اپنے رب کے سامنے کس طرح صفیں باندھتے ہیں ؟ تو آپ صلی اللہ علیہ وسلم نے فرمایا:اگلی صفوں کوپورا(مکمل) کرتے ہیں اور صف میں ایک دوسرے سے ملے رہتے ہیں۔ ‘‘ ’’الزجِرَات‘‘ سے مراد یا تو وہ فرشتے ہیں جو بادلوں کو ہانکتے ہیں، یا وہ جولوگوں کے دلوں میں نیکی اور بھلائی کا الہام کرکے گناہوں سے روکتے ہیں۔ (التَالِیَاتِ ذِکْرا)سے مراد وہ فرشتے ہیں جو انبیاء علیہم السلام کو اللہ تعالیٰ کی آیتیں پڑھ کر سناتے ہیں۔"],[6107,"§صفیں باندھے ہوئے فرشتے\nتمام مفسرین کا اس بات پر اتفاق ہے کہ اس سورہ کی ابتدائی تین آیات میں جن کی قسم اٹھائی گئی ہے ان سے مراد فرشتے ہیں اور اس بات کی تائید اس حدیث سے بھی ہوتی ہے جو سیدنا جابر رضی اللہ عنہ سے مروی ہے۔ وہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:’’تم لوگ اس طرح صف باندھا کرو جس طرح فرشتے بارگاہ الٰہی میں صف بستہ رہتے ہیں۔ تم لوگ سب سے پہلے اگلی صف پوری کیا کرو اور صف میں خوب مل کر کھڑے ہوا کرو ‘‘ (صحیح مسلم)\nپہلی آیت میں ان فرشتوں کا ذکر ہے جو اللہ کے احکام کے منتظر اور ا س کے دربار میں ہر وقت صف بستہ کھڑے رہتے ہیں اور یہی ان کی عبادت ہے کہ ادھر اللہ کا حکم ہو تو ادھر فوراً اسے بجالائیں۔ دوسری آیت میں ان فرشتوں کا ذکر ہے جو تدبیر اُمور کائنات پرمامور ہیں اور ڈانٹ ڈپٹ اس لیے کرتے ہیں کہ جلد سے جلد اللہ کا حکم بجالائیں۔ ڈانٹنے ڈپٹنے سے مراد یہ بھی ہو سکتی ہے کہ اسی دوسری قسم کے فرشتوں میں وہ گروہ بھی شامل ہے جو مجرموں اور نافرمانوں پر لعنت اور پھٹکار کرتے ہیں۔ اور انسانوں پر جو حوادث یا عذاب آتے ہیں انہی کے واسطہ سے آتے ہیں۔ اور تیسرے گروہ سے مراد وہ فرشتے ہیں جو خود بھی اللہ کے ذکر میں مشغول رہتے ہیں اور انسان کی روحانی غذا یا ہدایت کا واسطہ بھی بنتے ہیں۔ پیغمبروں پر اللہ کا حکم لاتے ہیں اور نیک لوگوں کے دلوں میں القاء والہام کرتے ہیں۔"],[6108,"§قرآن اللہ کا کلام اور کائنات ا س کا فعل ہے ان دونوں میں تضاد ناممکن ہے\nان تینوں قسم کے فرشتوں کی قسم اُٹھا کر اللہ تعالیٰ نے فرمایا:’’کہ تمہارا معبود حقیقی ایک ہی ہے ‘‘ یہاں یہ بات سمجھ لینی چاہیے کہ یہ کائنات اللہ تعالیٰ کا فعل اور ذکر یا قرآن اللہ تعالیٰ کا قول یا کلام ہے۔ اور اللہ تعالیٰ کے قول اور فعل میں نہ اختلاف ہو سکتا ہے اور نہ تضاد۔ اگر ہم اللہ تعالیٰ کا کلام پڑھ کر اس نتیجہ پر پہنچتے ہیں کہ معبود حقیقی صرف ایک ہی ہو سکتا ہے تو لامحالہ اس کائنات کے مربوط اور منظم نظام پر غور کرنے کے بعد بھی ہم اسی نتیجہ پر پہنچتے ہیں اور یہ دونوں چیزیں ایک دوسرے کی تائید و توثیق کرتی ہیں اور ان میں پوری ہم آہنگی پائی جاتی ہے۔ نظامِ کائنات میں وہ کیا کیا قابل غور باتیں ہیں جو اس بات پر دلالت کرتی ہیں کہ معبودِ حقیقی یا پروردگار صرف ایک ہی ہو سکتا ہے، قرآن میں بے شمار مقامات پر مذکور ہیں جن میں سے چند باتوں کا ذکر آگے بھی آرہا ہے۔"],[6109,"§مشارق و مغارب کتنے ہیں؟\nمشارق سے مراد بے شمار مشرق ہیں۔ سورج ہمیشہ عین مشرقی سمت سے ہی طلوع نہیں ہوتابلکہ گرمیوں میں اس کا مشرق شمال کی طرف سرکتا جاتا ہے اور سردیوں میں جنوب کی طرف۔ سورج کے مشرق کا زاویہ ہرروز جداگانہ ہوتا ہے اس لحاظ سے سورج کے سال بھر میں365 مشرق ہوئے۔پھر اس کائنات میں صرف سورج ہی گردش نہیں کر رہا اوربھی ہزاروں سیارے محو گردش ہیں۔ اوران کے اپنے اپنے مشرق یا طلوع ہونے کے مقامات ہیں۔ علاوہ ازیں ان کے مشرقوں میں بھی سورج کے مشرقوں کی طرح تبدیلی ہوتی رہتی ہے۔ اس لحاظ سے مشرقوں کی تعداد ہمارے حساب سے باہر ہوجاتی ہے اور اللہ تعالیٰ کے رب المشارق ہونے کا مطلب یہ ہے کہ ان تمام سیاروں کی نقل و حرکت کا وہی مالک ہے اور ان پر اسی کا کنٹرول ہے جس کا مطلب یہ ہوا کہ جس طرح اللہ تعالیٰ مشارق کا مالک ہے مغارب کا بھی ہے۔ مغارب کا یہاں تو ذکر نہیں تاہم سورہ معارج کی آیت نمبر 40میں مغارب کا بھی ذکر آگیا ہے۔\nصَافَّاتٌ، زَاجِرَاتٌ، تَالِـیَـاتٌ فرشتوں کی صفات ہیں۔ آسمانوں پر اللہ کی عبادت کے لیے صف باندھنے والے، یا اللہ کے حکم کے انتظار میں صف بستہ، وعظ و نصیحت کے ذریعہ سے لوگوں کو ڈانٹنے والے یا بادلوں کو، جہاں اللہ کا حکم ہو، وہاں ہانک کر لے جانے والے۔ اللہ کے ذکر یا قرآن کی تلاوت کرنے والے۔ ان فرشتوں کی قسم کھا کر اللہ تعالیٰ نے مضمون یہ بیان فرمایا کہ تمام انسانوں کا معبود ایک ہی ہے۔ متعدد نہیں، جیسا کہ مشرکین نے بنائے ہوئے ہیں۔ عرف عام میں قسم تاکید اور شک دور کرنے کے لیے کھائی جاتی ہے، اللہ تعالیٰ نے یہاں قسم اسی شک کو دور کرنے کے لیے کھائی ہے جو مشرکین اس کی وحدانیت و الوہیت کے بارے میں پھیلاتے ہیں۔ علاوہ ازیں ہر چیز اللہ کی مخلوق اور مملوک ہے، اس لیے وہ جس چیز کو بھی گواہ بنا کر اس کی قسم کھائے، اس کے لیے جائز ہے۔ لیکن انسانوں کے لیے اللہ کے سوا کسی اور کی قسم کھانا بالکل ناجائز اور حرام ہے، کیونکہ قسم میں، جس کی قسم کھائی جاتی ہے، اسے گواہ بنانا مقصود ہوتا ہے۔ اور گواہ اللہ کے سوا کوئی نہیں بن سکتا، کہ عالم بالغیب صرف وہی ہے، اس کے سوا کوئی عالم الغیب نہیں۔\nمطلب ہے مشارق و مغارب کا رب۔ جمع کا لفظ اس لیے استعمال کیا گیا ہے، بعض کہتے ہیں کہ سال کے دنوں کی تعداد کے برابر مشرق و مغرب ہیں۔ سورج ہر روز ایک مشرق سے نکلتا اور ایک مغرب میں غروب ہوتا ہے اور سورئہ رحمٰن میں ﴿مَشْرِقَیْنِ﴾ اور ﴿مَغْرِبَیْنِ﴾ تثنیہ کے ساتھ ہیں یعنی دو مشرق اور دو مغرب۔ اس سے مراد وہ مشرقین اور مغربین ہیں جن سے سورج گرمی اور سردی میں طلوع و غروب ہوتا ہے یعنی ایک انتہائی آخری مشرق و مغرب اور دوسرے مختصر یا قریب ترین مشرق و مغرب اور جہاں مشرق و مغرب کو مفرد ذکر کیا گیا ہے اس سے مراد وہ جہت ہے جس سے سورج طلوع ہوتا یا اس میں غروب ہوتا ہے۔ (فتح القدیر)\nاللہ پاک نے فرشتوں کی قسم اٹھائی ہے جو مقام عبودیت میں صف بندی کرتے ہیں اور لوگوں کے دلوں میں القاء کرتے رہتے ہیں وہ خود کو برائی سے تحفظ عطا کریں جو آسمانوں میں نمازوں کی ادائیگی کے لیے صف بندی کرتے ہیں حدیث میں وارد ہے کہ تم عبادت کے لیے اس طرح صف بندی کروجس طرح فرشتے اپنے پروردگار کی عبادت کے لیے صف بندی کرتے ہیں صحابہ کرام رضی اللہ عنہم نے عرض کیا ان کی صف بندی کس طرح ہے ؟ آپ صلی اللہ علیہ وسلم نے فرمایا وہ اولاً پہلی صف پوری کرتے ہیں ان کی صف بندی چوناگچ ہوتی ہے اور ان فرشتوں کی قسم جو بادلوں کو اللہ کی مشیت کے مطابق چلاتے ہیں۔\nانبیاء علیہم السلام پر اللہ تعالیٰ کی آیات کی تلاوت کرتے رہتے ہیں انھیں آگاہ کرتے ہیں کہ تم اپنے معبود کی اخلاص کے ساتھ عبادت کرو اور صرف اسی کی اطاعت کرو، وہ ذات آسمانوں، زمین اور ان دونوں کے درمیان سب مخلوق کا خالق ہے اور سب کا مالک اور نگران ہے اور انھیں شیطانی وسوسے سے دور رہنے کا القاء کرتے ہیں اور آگاہ کرتے ہیں کہ تمہارا پروردگار ایک ہے وہی ذات آسمانوں اور زمین اور ان دونوں کے درمیان اور مشر ق، مغرب کا پروردگار ہے مشارق، ذکر کیا گیا ہے اسی پر اکتفاء کرتے ہوئے مغارب کا ذکر نہیں کیا گیا ہے اس لیے کہ ذکر کردہ کلام اس پر دال ہے چونکہ مشرق مغرب موسم سرما اور موسم گرما میں تبدیل ہوتا رہتا ہے کہ اس لیے بجائے مشرق، مغرب دونوں کو جمع کے صیغہ کے ساتھ ذکر کیا ہے۔\nبعدازاں اللہ کی قدرت کاملہ کا ذکر کرتے ہوئے اس نے آسمان کو ستاروں کے ساتھ زینت عطا کی ہے جو روشن ہیں چمکدار ہیں یوں دکھائی دیتے ہیں جیسے چمکدار تابناک موتی ہوتے ہیں ان کے باعث سرکش فساد انگیزی کرنے والے شیاطین سے تحفظ رہتا ہے چنانچہ قتادہ رحمہ اللہ کا قول ہے کہ ستاروں کو تین مقاصد کے پیش نظر پیدا کیا گیا ہے جو شیاطین آسمان میں فیصلوں سے خود کو آگاہ رکھنے کے لیے آسمان دنیا کے قریب جاتے ہیں توستارہ ٹوٹ کر ان کو راکھ کا ڈھیر بنادیتا ہے دوسرامقصد یہ کہ ان سے فضا میں روشنی پھیلی جاتی ہے جبکہ تیسرا فائدہ یہ کہ ستارے پہلے آسمان کی زیب و زینت کا باعث بنتے ہیں۔\nابوحیان رحمہ اللہ بیان کرتے ہیں کہ آیت مبارکہ میں پہلے آسمان کا ذکر ہے اس لیے کہ آنکھیں پہلے آسمان کا ہی مشاہدہ کرپاتی ہیں دیگر آسمانوں کا مشاہدہ ممکن نہیں ہے صرف پہلے آسمان کے قریب جانے سے شیاطین کو روکنامقصود ہے جبکہ وہ فرشتے جو ملااعلیٰ میں ان کی باتوں کو سنے ان میں قدرت نہیں ہے ان پر ہر طرف سے شہاب ثاقب گرائے جاتے ہیں جو آسمان دنیا کے قریب جانے کا ارادہ کرتے ہیں انھیں خبروں کے سننے سے روکتے ہیں جبکہ ان کی اخروی زندگی میں مسلسل عذاب میں مبتلا رکھاجائے گا۔\nاِنَّا زَيَّنَّا السَّمَآءَ الدُّنْيَا بِزِيْنَةِ ا۟لْكَوَاكِبِۙ۰۰۶ وَ حِفْظًا مِّنْ كُلِّ شَيْطٰنٍ مَّارِدٍۚ۰۰۷ لَا\nيَسَّمَّعُوْنَ اِلَى الْمَلَاِ الْاَعْلٰى وَ يُقْذَفُوْنَ مِنْ كُلِّ جَانِبٍۗۖ۰۰۸ دُحُوْرًا وَّ لَهُمْ عَذَابٌ\nوَّاصِبٌۙ۰۰۹ اِلَّا مَنْ خَطِفَ الْخَطْفَةَ فَاَتْبَعَهٗ شِهَابٌ ثَاقِبٌ۰۰۱۰\nبے شک ہم ہی نے آسمان دنیا کو ستاروں سے زینت دے کر سجایا ہے6 اور ہر سرکش شیطان سے (اس کی) حفاظت کے لیے7 (تاکہ) وہ عالم بالا کی (باتیں) سن نہ پائیں اور (ان پر) ہر طرف سے (شہاب) پھینکے جاتے ہیں 8 (انھیں) بھگانے کے لیے اور ان کے لیے دائمی عذا ب ہے 9 مگر جو کوئی (ایک آدھ بات) اچانک اچک کر لے جائے تو نہایت چمکتا\nہوا ستارہ اس کے پیچھے لگ جاتا ہے 0"],[6110,"§آسمان کی تزئین وحفاظت اللہ تعالیٰ کی طرف سے ہے\nاللہ تعالیٰ نے ارشاد فرمایا ہے کہ اس نے آسمان دنیا کو دیکھنے والوں کے لیے جو باشندگان زمین ہیں مزین فرما دیا ہے ﴿بِزِيْنَةِ ا۟لْكَوَاكِبِۙ۰۰۶﴾ ’’ستاروں کی زینت سے۔‘‘ اسے اضافت وبدل کے ساتھ پڑھا گیا ہے اور دونوں کے معنی ایک ہیں، (یعنی زِینَةُ مضاف اور الْکَواکِبِ مضاف الیہ ہے بِزِینَةِ الْکَوَاکِبِ اور بدل کی صورت میں بِزِینَةٍ یعنی تنوین کے ساتھ پڑھیں گے اور آپس میں یہ بدل مبدل منہ ہوں گے) آسمان کے ثوابت، کواکب اور سیارے اہل زمین کے لیے روشنی فراہم کرتے ہیں جیسا کہ اللہ تبارک وتعالیٰ نے فرمایا ہے: ﴿وَ لَقَدْ زَيَّنَّا السَّمَآءَ الدُّنْيَا بِمَصَابِيْحَ وَ جَعَلْنٰهَا رُجُوْمًا لِّلشَّيٰطِيْنِ وَ اَعْتَدْنَا لَهُمْ عَذَابَ السَّعِيْرِ۰۰۵﴾ (الملک:5) ’’اور البتہ تحقیق ہم نے قریب کے آسمان کو (تاروں کے) چراغوں سے زینت دی اور ان کو شیطانوں کے مارنے کا آلہ بنایا اور ان کے لیے دہکتے جہنم کا عذاب تیار کر رکھا ہے۔‘‘ اور فرمایا: ﴿وَ لَقَدْ جَعَلْنَا فِي السَّمَآءِ بُرُوْجًا وَّ زَيَّنّٰهَا لِلنّٰظِرِيْنَۙ۰۰۱۶وَ حَفِظْنٰهَا مِنْ كُلِّ شَيْطٰنٍ رَّجِيْمٍۙ۰۰۱۷ اِلَّا مَنِ اسْتَرَقَ السَّمْعَ فَاَتْبَعَهٗ شِهَابٌ مُّبِيْنٌ۰۰۱۸﴾ (الحجر:16-18) ’’اور البتہ تحقیق ہم ہی نے آسمان میں برج بنائے اور دیکھنے والوں کے لیے اس کو سجایا اور ہر شیطان راندۂ درگاہ سے اسے محفوظ کر دیا۔ ہاں، اگر کوئی چوری سے سننا چاہے تو روشن شعلہ اس کے پیچھے لپکتا ہے۔‘‘ اور یہاں فرمایا: ﴿وَ حِفْظًا مِّنْ كُلِّ شَيْطٰنٍ مَّارِدٍۚ۰۰۷﴾ ’’اور ہر شیطان سرکش سے اس کی حفاظت کی۔‘‘ ﴿مَّارِدٍ﴾ کے معنی متمرد اور سرکش کے ہیں کہ جب وہ چوری چھپے سننے کا ارادہ کرتا ہے تو اس کے پیچھے ایک روشن شعلہ آ جاتا ہے جو اسے جلا ڈالتا ہے، اسی لیے اللہ جل جلالہ نے فرمایا ہے: ﴿لَا يَسَّمَّعُوْنَ اِلَى الْمَلَاِ الْاَعْلٰى ﴾ ’’وہ (شیطان) ملاء اعلیٰ کی باتیں نہ سن سکیں۔‘‘ یعنی ملاء اعلیٰ تک نہ پہنچ سکیں اور ملاء اعلیٰ سے مراد آسمان اور ان میں رہنے والے فرشتے ہیں جب وہ فرشتے اللہ تعالیٰ کی وحی کردہ شرع ومقدرات کے بارے میں گفتگو کرتے ہیں جیسا کہ اس کا ان احادیث میں ذکر ہے جو ہم قبل ازیں آیت کریمہ ﴿حَتّٰۤى اِذَا فُزِّعَ عَنْ قُلُوْبِهِمْ قَالُوْا مَا ذَا١ۙ قَالَ رَبُّكُمْ١ؕ قَالُوا الْحَقَّ١ۚ وَ هُوَ الْعَلِيُّ الْكَبِيْرُ۰۰۲۳﴾ (سبا:23) ’’یہاں تک کہ جب ان کے دلوں سے گھبراہٹ دور کر دی جاتی ہے تو (باہم) کہتے ہیں: تمہارے پروردگار نے کیا فرمایا؟ وہ جواب دیتے ہیں کہ (بالکل) حق (فرمایا) اور وہ نہایت عالی مقام، بہت بڑا ہے۔‘‘ کی تفسیر میں بیان کر آئے ہیں۔ ﴿وَ يُقْذَفُوْنَ مِنْ كُلِّ جَانِبٍۗۖ۰۰۸﴾ ’’اور ہر طرف سے (ان پر انگارے) پھینکے جاتے ہیں۔‘‘ یعنی ہر اس طرف سے جہاں سے وہ آسمان کا قصد کرتے ہیں، ﴿دُحُوْرًا﴾ ’’وہاں سے نکال دینے کو۔‘‘ انہیں مارا جاتا، ڈانٹ ڈپٹ پلائی جاتی اور آسمان تک پہنچنے سے روکا جاتا ہے، ﴿وَّ لَهُمْ عَذَابٌ وَّاصِبٌۙ۰۰۹﴾ ’’اور ان کے لیے دائمی عذاب ہے۔‘‘ یعنی آخرت میں انہیں دائمی، ہمیشہ رہنے والا اور بہت درد ناک عذاب ہو گا، جیسا کہ اللہ جل جلالہ نے فرمایا ہے: ﴿وَ اَعْتَدْنَا لَهُمْ عَذَابَ السَّعِيْرِ۰۰۵﴾ (الملک:5) ’’اور ہم نے ان کے لیے دہکتے جہنم کا عذاب تیار کر رکھا ہے۔‘‘\nارشاد باری تعالیٰ ہے:﴿اِلَّا مَنْ خَطِفَ الْخَطْفَةَ ﴾ ’’ہاں، جو کوئی (فرشتوں کی بات کو) جھپٹ لینا چاہتا ہے۔‘‘ یعنی ان شیطانوں میں سے جو چوری سے جھپٹ لینا چاہتا ہے اور وہ کوئی ایسی بات ہوتی ہے جسے وہ آسمان سے سن کر اپنے سے نیچے والے شیطان کو بتا دیتا ہے، بسا اوقات اسے بتانے سے پہلے ہی جلتا ہوا انگار اس کے پیچھے لگ جاتا ہے اور کبھی یوں ہوتا ہے کہ وہ جلتے ہوئے انگارے کے آنے اور اسے جلانے سے پہلے ہی اللہ تعالیٰ کی تقدیر کے مطابق نیچے والے شیطان کو بتانے میں کامیاب ہو جاتا ہے اور یہ دوسرا شیطان وہ بات کاہن کو بتا دیتا ہے، جیسا کہ حدیث کے حوالے سے قبل ازیں بیان کیا جا چکا ہے۔ (صحیح البخاری، حدیث: 4800) اسی لیے فرمایا: ﴿اِلَّا مَنْ خَطِفَ الْخَطْفَةَ فَاَتْبَعَهٗ شِهَابٌ ثَاقِبٌ۰۰۱۰﴾ ’’ہاں، جو کوئی فرشتوں کی کسی بات کو)چوری سے جھپٹ لینا چاہتا ہے تو روشن انگار اس کے پیچھے لگتا ہے۔‘‘ ﴿ثَاقِبٌ۰۰۱۰﴾ کے معنی روشن اور منور کے ہیں۔\nابن جریر رحمہ اللہ نے ابن عباس رضی اللہ عنہما سے روایت کیا ہے کہ شیطانوں کے لیے آسمانوں میں بیٹھنے کے لیے مقامات تھے جہاں سے وہ وحی سنتے تھے، اس وقت ستارے چلتے نہیں تھے اور شیطانوں کو مارا نہیں جاتا تھا اور جب وہ وحی سن لیتے تو زمین کی طرف اتر آتے اور سنی ہوئی ایک بات میں نو (9) اور باتیں ملا دیتے۔ ابن عباس رضی اللہ عنہما نے بیان کیا کہ جب رسول اللہ صلی اللہ علیہ وسلم کو مبعوث فرمایا گیا تو شیطان جب اپنی جگہ پر جانے کا قصد کرتا تو اس کے پاس انگار آ کر اسے بھسم کر دیتا، شیطانوں نے اس کا ابلیس ملعون کے پاس ذکر کیا تو اس نے کہا کہ معلوم ہوتا ہے کہ کوئی واقعہ رونما ہوا ہے، واقعہ معلوم کرنے کے لیے اس نے اپنے لشکروں کو روانہ کر دیا تو انہوں نے جب رسول اللہ صلی اللہ علیہ وسلم کو نخلہ کے دونوں پہاڑوں کے درمیان۔ وکیع نے کہا۔ یعنی بطن نخلہ میں رسول اللہ صلی اللہ علیہ وسلم کو کھڑے نماز پڑھتے ہوئے دیکھا تو انہوں نے واپس جا کر ابلیس کو بتایا تو ابلیس نے کہا ہاں یہ واقعہ رونما ہوا ہے۔(تفسیر الطبری:45/23)\nاللہ تعالیٰ کی قدرت اور اس کے علم و حکمت کے مظاہر میں سے یہ بھی ہے کہ اس نے آسمان دنیا کو ستاروں سے مزین کر دیا ہے۔ یہ ستارے مختلف الانواع ہیں، ان میں سے کچھ ایک جگہ ثابت ہیں اور کچھ متحرک،کچھ چھوٹے ہیں اور کچھ بڑے۔ یہ ستارے رات کے وقت دیکھنے میں روشن اور چمکدار نظر آتے ہیں اور آسمانِ دنیا کو زینت بخشتے ہیں اور تاریک راتوں میں دیکھنے میں بھلے نظر آتے ہیں۔ ان ستاروں کا ایک دوسرا مقصد یہ ہے کہ ان کے ذریعے شیاطین کو مار کر آسمان کی باتیں سننے سے انہیں دور رکھا جاتاہے، تاکہ غیب کی باتیں سن کر زمین پر رہنے والے کاہنوں کو نہ بتائیں۔ شیاطین جب بھی اس کی کوشش کرتے ہیں، فرشتے انہیں آسمان کی ہر جہت سے انگاروں کے ذریعے مارتے ہیںتاکہ انہیں آسمان کی باتیں سننے سے دور رکھیں، اللہ تعالیٰ نے فرمایا کہ قیامت کے دن ان شیاطین کو شدید دائمی عذاب دیا جائے گا۔\nمفسرین نے لکھا ہے کہ شیاطین آسمان کے قریب پہنچ جاتے اور فرشتے جو باتیں آپس میں کرتے، انہیں سننے کی کوشش کرتے اور ان کی بعض باتیں سن کر جان جاتے کہ دنیا میں کیا ہونے والا ہے، پھر کاہنوں کو آکر وہی باتیں بتا دیتے اور انہیں باور کراتے کہ وہ غیب کی باتیں جانتے ہیں۔ چنانچہ اللہ تعالیٰ نے انہیں آسمان کے قریب تک پہنچنے سے انگاروں کے ذریعے روک دیا، یعنی وہ جب بھی ایسی کوشش کرتے ہیں انہیں انگاروں کے ذریعہ مارا جاتا ہے، جن کی زد میں آکر کبھی توجل جاتے ہیں اور کبھی جلتے نہیں تو بعض باتیں کاہنوں کو بتا دیتے ہیں۔\nامام شوکانی رحمہ اللہ نے بعض مفسرین کی رائے نقل کی ہے کہ شیاطین وحی الٰہی کو ہرگز نہیں سن پاتے، بلکہ کبھی فرشتوں کی بعض دوسری باتیں سن لیتے ہیں، اس لیے کہ اللہ تعالیٰ نے سورۃ الشعراء آیت (212)میں فرمایا ہے:﴿اِنَّهُمْ عَنِ السَّمْعِ لَمَعْزُوْلُوْنَ۠ؕ۰۰۲۱۲﴾ ’’شیاطین وحی الٰہی کو سننے سے قطعی طور پر ردک دیئے گئے ہیں۔‘‘ اور سورۃ الملک آیت (5)میں فرمایاہے: ﴿وَ جَعَلْنٰهَا رُجُوْمًا لِّلشَّيٰطِيْنِ﴾ ’’ہم نے ستاروں کو شیاطین کے مارنے کا ذریعہ بنایا ہے ‘‘ اور سورۃ الحجر آیات (17، 18) میں فرمایاہے : ﴿وَ حَفِظْنٰهَا مِنْ كُلِّ شَيْطٰنٍ رَّجِيْمٍۙ۰۰۱۷اِلَّا مَنِ اسْتَرَقَ السَّمْعَ فَاَتْبَعَهٗ شِهَابٌ مُّبِيْنٌ۰۰۱۸﴾ ’’ہم نے اسے ہرمردود شیطان سے محفوظ رکھا ہے، ہاں مگر جو چوری چھپے سننے کی کوشش کرے تو ا س کے پیچھے دہکتا ہوا (کھلا) شعلہ لگتاہے۔‘‘"],[6111,"§آسمانوں کاوجود ایک ٹھو س حقیقت ہے\nنیلے آسمان پر چمکتے ہوئے ستارے یوں دکھائی دیتے ہیں جیسے اس میں ہیرے اور زمرد جڑے ہوئے ہیں۔ اور اس خوشنما منظر کو دیکھنے سے ہی انسان راحت محسوس کرتا ہے۔ موجودہ دور کے ہیئت دان کسی آسمان کے قائل نہیں۔ ان کے خیال کے مطابق آسمان صرف حد نگاہ کا نام ہے۔ جبکہ کتاب و سنت میں صراحت سے مذکور ہے کہ آسمان ایک ٹھوس حقیقت ہے اور ان کی تعداد سات ہے۔ آج کے ماہرین ِ فلکیات کئی ستاروں کا زمین سے لاکھوں اور کروڑوں میل کا فاصلہ بتاتے ہیں اور یہ بھی بتاتے ہیں کہ ان ستارو ں کی روشنی ذاتی نہیں ہوتی بلکہ انعکاس روشنی کے اُصول کے تحت سورج کی روشنی سے ہی یہ منور اور روشن اور چمکتے ہوئے نظر آتے ہیں۔بلکہ ہمارے چاند کی روشنی بھی سورج کی روشنی ہی کی مرہونِ منت ہے۔ اب قرآن یہ کہتا ہے کہ ہم نے آسمان دنیا کو ستاروں سے مزین کیا ہے۔ جس کا مطلب یہ ہوا کہ ان ماہرین کی تمام تر تحقیقات تاحال آسمان دنیا کے بھی نیچے ہیں۔ اور باقی آسمانوں کی تو اس کے بعد ہی باری آسکتی ہے۔ جو شاید انسان کی بساط سے باہر ہے۔"],[6112,"§دورِنبوی صلی اللہ علیہ وسلم میں کہانت کا چرچا\nدورِ نبوی صلی اللہ علیہ وسلم میں عرب میں کہانت کا بڑا چرچا تھا اور کاہنوں کو معاشرہ میں ایک معزز مقام حاصل تھا۔ ان کے متعلق مشہوریہ تھا کہ جن اور شیطان کاہنوں کے قبضہ میں ہوتے ہیںجوانہیں غیب کی خبریں مہیا کرتے ہیں۔ اچھے بھلے لوگ ان کے ہاں آتے اور ان کی خدمات حاصل کرتے تھے حتیٰ کہ بعض دفعہ اپنے مقدمات کے فیصلے کے لیے ان کے ہاں آتے تھے۔ ایسے ہی ایک کاہن کاواقعہ احادیث میں بھی مذکور ہے۔ قرآن جب نازل ہوا تو اس میں کچھ سابقہ انبیاء واقوام کے حالات تھے اور کچھ آئندہ کی خبریں بھی تھیں۔ پھر آپ صلی اللہ علیہ وسلم نے لوگوں کو یہ بھی بتایا تھا کہ آپ صلی اللہ علیہ وسلم کے پاس فرشتہ آتا ہے جو آپ صلی اللہ علیہ وسلم پر یہ کلام نازل کرتا ہے۔ ان ساری باتوں سے ان لوگوں نے یہ سمجھ لیا کہ شاید وہ دوسرے کاہنوں کی طرح آپ صلی اللہ علیہ وسلم کے پاس بھی کوئی جن یا شیطان آتا ہے۔ چنانچہ ایک دفعہ آپ صلی اللہ علیہ وسلم بیمار ہوئے تو دو تین راتیں تہجد کی نماز کے لیے اُٹھ نہ سکے تو ابولہب کی بیوی آپ صلی اللہ علیہ وسلم کے پاس آکر کہنے لگی۔ میں سمجھتی ہوں کہ تیرے شیطان نے تجھے چھوڑ دیا ہے۔ (صحیح بخاری) اور اسی وجہ سے وہ لوگ آپ صلی اللہ علیہ وسلم کو کاہن ہی سمجھتے تھے۔ اگلی دو آیات میں ان کے اسی غلط نظریہ کی تردید کی گئی ہے۔"],[6113,"§شہابِ ثاقب\nاس آیت کی تفسیر کے لیے درج ذیل حدیث ملاحظہ فرمائیے : سیدنا عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ : ’’ایک دفعہ آپ صلی اللہ علیہ وسلم صحابہ رضی اللہ عنہم کے ساتھ بیٹھے ہوئے تھے کہ دفعتاً ایک ستارہ ٹوٹا اور روشنی ہو گئی۔ آپ صلی اللہ علیہ وسلم نے صحابہ رضی اللہ عنہم سے پوچھا :’’ دورِ جاہلیت میں جب ایسا واقعہ ہوتا تو تم کیا کہتے تھے ؟‘‘صحابہ رضی اللہ عنہم کہنے لگے : ’’ہم تو یہی کہتے تھے کہ کوئی بڑا آدمی مر گیا یا پیدا ہوا ہے۔‘‘ آپ صلی اللہ علیہ وسلم نے فرمایا:’’یہ کسی کی زندگی یا موت کے سبب سے نہیں ٹوٹتا بلکہ ہمارا پروردگار کسی کام کا فیصلہ کر لیتا ہے تو حاملانِ عرش تسبیح کرتے ہیں پھر آسمان والے فرشتے جو ان سے قریب ہوتے ہیں پھر ان سے قریب والے تسبیح کرتے ہیں۔ حتی کہ سبحان اللہ کی آواز ساتویں آسمان تک پہنچتی ہے پھر چھٹے آسمان والے ساتویں والوں سے پوچھتے ہیں کہ تمہارے پروردگار نے کیا فرمایا۔ وہ انہیں خبر دیتے ہیں۔ اسی طرح نیچے آسمان والے اوپر کے آسمان والوں سے پوچھتے جاتے ہیں یہاں تک کہ یہ خبر دنیا کے آسمان تک پہنچتی ہے او ر شیطان اچک کرسننا چاہتے ہیں تو ان کو مار پڑتی ہے اور وہ کچھ بات لا کر اپنے یاروں (کاہنوں وغیرہ) پر ڈال دیتے ہیں۔ وہ خبر تو سچ ہوتی ہے مگر وہ اسے بدلتے اور گھٹا بڑھا دیتے ہیں۔ (صحیح ترمذی)\nاِلَّا مَنْ خَطِفَ الْخَطْفَةَ: البتہ وہ شیطان جو چوری چھپے کسی بات کو اچک لیتا ہے تو اس کو نہایت روشن ستارہ اپنی لپیٹ میں لے لیتا ہے اور اس کو جلا دیتا ہے، علامہ قرطبی رحمہ اللہ وضاحت فرماتے ہیں کہ ذہن نشین کریں شیاطین کو جن ستاروں سے رجم کیا جاتا ہے ان کا شمار ان ستاروں سے نہیں ہے جو اپنے مقام پر قائم رہتے ہیں اگرچہ ان میں کچھ حرکت تو ہوتی ہے لیکن ان کی حرکات کو معلوم نہیں کیا جاسکتا۔\nفَاسْتَفْتِهِمْ اَهُمْ اَشَدُّ خَلْقًا اَمْ مَّنْ خَلَقْنَا١ؕ اِنَّا خَلَقْنٰهُمْ مِّنْ طِيْنٍ لَّازِبٍ۰۰۱۱\nبَلْ عَجِبْتَ وَ يَسْخَرُوْنَ۪۰۰۱۲ وَ اِذَا ذُكِّرُوْا لَا يَذْكُرُوْنَ۪۰۰۱۳ وَ اِذَا رَاَوْا اٰيَةً\nيَّسْتَسْخِرُوْنَ۪۰۰۱۴ وَ قَالُوْۤا اِنْ هٰذَاۤ اِلَّا سِحْرٌ مُّبِيْنٌۚۖ۰۰۱۵ ءَاِذَا مِتْنَا وَ كُنَّا تُرَابًا\nوَّعِظَامًا ءَاِنَّا لَمَبْعُوْثُوْنَ۠ۙ۰۰۱۶ اَوَ اٰبَآؤُنَا الْاَوَّلُوْنَؕ۰۰۱۷ قُلْ نَعَمْ وَ اَنْتُمْ\nدَاخِرُوْنَۚ۰۰۱۸ فَاِنَّمَا هِيَ زَجْرَةٌ وَّاحِدَةٌ فَاِذَا هُمْ يَنْظُرُوْنَ۰۰۱۹\nپھر آپ ان سے پوچھیے: کیا انھیں پیدا کرنا زیادہ مشکل ہے یا جو کچھ ہم نے پیدا کیا ؟ بے شک ہم نے ان (انسانوں) کو لیس دار مٹی سے پید اکیا ! بلکہ آپ نے (کفار کے انکار آخرت پر) تعجب کیا جب کہ وہ ٹھٹھا کر تے ہیں@ اور جب انھیں نصیحت کی جاتی ہے تو وہ نصیحت قبول نہیں کرتے # اور جب وہ کوئی نشانی دیکھتے ہیں تو خوب مذاق اُڑاتے ہیں$ اور وہ کہتے ہیں : یہ تو بالکل کھلاجادو ہے% کیا جب ہم مر جائیں گے او رمٹی اور ہڈیاں ہوجائیں گے تو کیا ہمیں سچ مچ (دوبارہ) اُٹھایا جائے گا ؟^ کیا ہمارے پہلے باپ دادوں کو بھی؟ & آپ کہہ دیجئے : ہاں ! اور تم ذلیل و خوار ہو گے * سو بس وہ (اُٹھانا) تو ایک جھڑکی ہی\nہوگی، تو وہ یکایک (زندہ ہو کر) دیکھتے ہوں گے ("],[6114,"§حیات بعد الممات کا ثبوت\nاللہ تعالیٰ نے فرمایا ہے کہ ان منکرین بعثت سے پوچھو کہ کن کا بنانا مشکل ہے، ان کا یا آسمانوں، زمین اور ان کے درمیان فرشتوں، شیطانوں اور دیگر بڑی بڑی مخلوقات کا؟ ابن مسعود رضی اللہ عنہ کی قراءت میں ہے، وہ اقرار کرتے تھے کہ ان کی نسبت ان مخلوقات کا بنانا زیادہ مشکل ہے۔ (تفسیر الطبری:51/23)\nاور جب حقیقت حال یہی ہے تو پھر بعثت کا انکار کیوں کرتے ہیں؟ حالانکہ وہ جس چیز کا انکار کر رہے ہیں اس سے بڑی چیز خود دیکھ رہے ہیں، جیسا کہ فرمایا: ﴿لَخَلْقُ السَّمٰوٰتِ وَ الْاَرْضِ اَكْبَرُ مِنْ خَلْقِ النَّاسِ وَ لٰكِنَّ اَكْثَرَ النَّاسِ لَا يَعْلَمُوْنَ۰۰۵۷﴾ (المؤمن:57) ’’آسمانوں اور زمین کا پیدا کرنا یقیناً لوگوں کے پیدا کرنے کی نسبت بڑا (کام) ہے اور لیکن اکثر لوگ نہیں جانتے۔‘‘ پھر اللہ سبحانہ وتعالیٰ نے بیان فرمایا ہے کہ یہ بہت ہی کمزور چیز سے پیدا کیے گئے ہیں ﴿اِنَّا خَلَقْنٰهُمْ مِّنْ طِيْنٍ لَّازِبٍ۰۰۱۱﴾ ’’بے شک ہم نے انہیں چپکتے گارے سے بنایا ہے۔‘‘ مجاہد، سعید بن جبیر اور ضحاک رحمہ اللہ فرماتے ہیں کہ ﴿طِيْنٍ لَّازِبٍ۰۰۱۱﴾ کے معنی اس گارے کے ہیں جو آپس میں چپک رہا ہو۔ (تفسیر الطبری:53/23) اور ابن عباس رضی اللہ عنہما اور عکرمہ رحمہ اللہ کا قول ہے کہ اس کے معنی لیس دار گارے کے ہیں۔ (تفسیر الطبری:52/23) اور قتادہ رحمہ اللہ کہتے ہیں کہ جو ہاتھ کے ساتھ چپک جائے۔ (تفسیر الطبری:53/23)\nارشاد باری ہے:﴿بَلْ عَجِبْتَ وَ يَسْخَرُوْنَ۪۰۰۱۲﴾ ’’ہاں، آپ نے (کفار کے انکار پر) تعجب کیا جبکہ وہ تمسخر کرتے ہیں۔‘‘ یعنی اے محمد صلی اللہ علیہ وسلم! آپ تو ان منکرین بعثت کی تکذیب سے تعجب کر رہے ہیں کیونکہ آپ تو یقین رکھتے اور اس کی تصدیق کرتے ہیں جس عجیب معاملے کی اللہ تعالیٰ نے خبر دی ہے کہ جسموں کے فنا ہو جانے کے بعد انہیں دوبارہ اٹھایا جاتا ہے تو اس کے بر خلاف یہ لوگ شدید تکذیب کرتے ہوئے آپ صلی اللہ علیہ وسلم کی ان باتوں کا مذاق اڑاتے ہیں۔\nقتادہ رحمہ اللہ کہتے ہیں کہ تعجب سیّدنا محمد رسول اللہ صلی اللہ علیہ وسلم نے کیا اور تمسخر گمراہ لوگوں نے۔ (تفسیر الطبری:54/23) ﴿وَاِذَا رَاَوْا اٰيَةً ﴾ ’’اور وہ جب کوئی نشانی دیکھتے ہیں۔‘‘ یعنی اس کی واضح دلیل، تو ﴿يَّسْتَسْخِرُوْنَ۪۰۰۱۴﴾ ’’ٹھٹھا کرتے ہیں۔‘‘ مجاہد وقتادہ رحمہم اللہ کہتے ہیں کہ اس کے معنی یہ ہیں کہ وہ مذاق اڑاتے ہیں۔ (تفسیر الطبری:54/23)\n﴿وَ قَالُوْۤا اِنْ هٰذَاۤ اِلَّا سِحْرٌ مُّبِيْنٌۚۖ۰۰۱۵﴾ ’’اور کہتے ہیں کہ یہ تو صریح جادو ہے۔‘‘ یعنی تم جو لائے ہو یہ تو صریح جادو ہے۔ ﴿ءَاِذَا مِتْنَا وَ كُنَّا تُرَابًا وَّ عِظَامًا ءَاِنَّا لَمَبْعُوْثُوْنَ۠ۙ۰۰۱۶﴾ ’’بھلا جب ہم مر گئے اور مٹی اور ہڈیاں ہو گئے تو کیا ہم پھر اٹھائے جائیں گے، کیا ہمارے باپ دادا بھی (جو) پہلے (ہوگزرے ہیں؟)‘‘ یعنی وہ اسے بعید سمجھتے ہوئے اس کی تکذیب کرتے ہیں۔ ﴿قُلْ نَعَمْ وَ اَنْتُمْ دَاخِرُوْنَۚ۰۰۱۸﴾ ’’کہہ دیں: ہاں اور تم ذلیل ہو گے۔‘‘ یعنی اے محمد صلی اللہ علیہ وسلم! ان سے کہہ دیں کہ تم مٹی اور ہڈیاں بننے کے بعد قیامت کے دن دوبارہ اٹھائے جائو گے اور تم اللہ تعالیٰ کی عظیم قدرت کے مقابلے میں بہت ہی حقیر ہو جیسا کہ اللہ تبارک وتعالیٰ نے فرمایا ہے:﴿وَ كُلٌّ اَتَوْهُ دٰخِرِيْنَ۰۰۸۷﴾ (النمل:87) ’’اور سب اس سے عاجز ہو کر چلے آئیں گے۔‘‘ ﴿اِنَّ الَّذِيْنَ يَسْتَكْبِرُوْنَ۠ عَنْ عِبَادَتِيْ سَيَدْخُلُوْنَ جَهَنَّمَ دٰخِرِيْنَؒ۰۰۶۰﴾ (المؤمن:60) ’’بے شک جو لوگ میری عبادت سے ازراہ تکبر کتراتے ہیں، عنقریب جہنم میں ذلیل ہو کر داخل ہوں گے۔‘‘\nپھر اللہ جل جلالہٗ نے فرمایا ہے: ﴿فَاِنَّمَا هِيَ زَجْرَةٌ وَّاحِدَةٌ فَاِذَا هُمْ يَنْظُرُوْنَ۰۰۱۹﴾ ’’سو بس وہ (اٹھانا) ایک جھڑکی ہی ہو گی تو وہ یکایک دیکھنے لگیں گے۔‘‘ یعنی یہ اللہ تعالیٰ کی طرف سے ایک حکم ہو گا اوروہ انہیں یکبار بلائے گا کہ وہ زمین سے نکل آئیں، تو وہ اپنے رب کے سامنے کھڑے ہو کر قیامت کے دن کی ہولناکیوں کو دیکھ رہے ہوں گے۔ وَاللہُ تَعَالٰی أَعْلَمُ."],[6115,"§مٹی کی مختلف حالتیں جن سے آدم کا پتلا بنایا گیا، ڈارون کے نظریہ کا اِبطال\nمٹی کو جن سات مختلف حالتوں سے گزار کر انسان کو پیدا کیا گیا ان کی تفصیل یہ ہے (1)تراب بمعنی خشک مٹی (40:67)۔ (2) ارض بمعنی عام مٹی یا زمین (71:17)۔(3)طین بمعنی گیلی مٹی یا گارا (6:2)۔(4)طین لازب معنی لیس دار یا چپک دار مٹی (37:11)۔ (5) حمأ مسنون بمعنی بدبودار کیچڑ (15:26)۔ (6)صلصال بمعنی ٹھیکرا یعنی حرارت سے پکائی ہوئی مٹی (15:26)۔ (7)صلصال کالفخار بمعنی ٹن سے بجنے والی ٹھیکری (55:14)یہ مٹی یا زمین کی مختلف شکلیںہیں۔ کسی وقت مٹی میں پانی کی آمیزش کی گئی تو بعدمیں حرارت کے ذریعہ پانی کو خشک کر دیا گیا۔\nقرآن نے مختلف مقامات پر ان مختلف حالتوں میں سے کسی بھی ایک یا دو حالتوں کا ذکر کر دیا ہے۔ اور جس حالت کا بھی نام لیاجائے وہ سب درست ہے۔ اس بیان سے ڈارون کا نظریہ ارتقاء کا رد ہوجاتا ہے جس کی رُو سے انسان نباتات اور حیوانات کی منزلوں سے گزر کر وجود میں آیا ہے حالانکہ اللہ تعالیٰ نے جو سات مختلف حالتیں بیان کی ہیں وہ سب کی سب جمادات یامٹی میں ہی پوری ہوجاتی ہیں۔\nاس آیت میں اللہ تعالیٰ نے دو مزید باتیں ارشاد فرمائیں ایک یہ کہ اللہ تعالیٰ جو عظیم الجثہ اور محیر العقول مخلوقات پیدا کر چکا ہے اس کے مقابلہ میں انسان کی حیثیت ہی کیا ہے کہ اس کی تخلیق ا س کے لیے کچھ مشکل ہو اور دوسری یہ کہ اللہ تعالیٰ نے انسان کو مٹی ہی کی سات مختلف حالتوں سے گزار کر پیدا کیا ہے۔ پھر وہ مر کرمٹی میں مل کرمٹی ہی بن جائے گا۔ تو کیا جس نے مٹی کی اتنی حالتوں سے گزار کر انسان کو پہلے پیدا کیا تھا اب دوبارہ مختلف حالتوں سے گزار کر پیدا نہ کر سکے گا ؟"],[6116,"§انسان کی دوبارہ زندگی کیسے ؟\nکفار مکہ کے اس اعتراض اور انکار کو قرآن میں بہت سے مقامات پر ذکر کیا گیا ہے اور اس کا جواب بھی کئی طرح سے دیا گیا ہے اس مقام پر بھی مذکور ہے کہ انسان کی پیدائش مٹی سے ہوئی ہے۔ پھر وہ زندہ ہو کر مٹی یا زمین سے جدا نہیں ہوا بلکہ اس کی تمام تر ضروریات مٹی یا زمین ہی سے وابستہ ہیں۔ مرکر بھی وہ اس مٹی میں دفن ہوگا تو جب گل سڑ کر مٹی بن کر مٹی میں مل جائے گا تو زمین اس کے تحلیل شدہ اجزاء نکال کر باہر نہیں پھینک دے گی۔ بلکہ سنبھال کر اپنے اندر محفوظ رکھے گی پھر انہی تحلیل شدہ اجزاء کو اللہ تعالیٰ پھر سے اکٹھا کرکے ان اجزاء کو اپنی پہلی حالت میں لے آئے گا۔ اس کی روح پہلے ہی مرتے وقت قبض کر لی تھی۔ اور یہی روح اس کا اصل تشخص ہے جو پہلے ہی اللہ کے قبضہ میں ہے۔ یہی روح ا سکے جسم میں ڈال کر اسے پھر سے اُٹھا کھڑا کیاجائے گا۔\nرہی یہ بات کہ ان کے آباء و اجداد جومدتوں پہلے مرچکے ان میں سے کوئی بھی زندہ ہوا نہ ان کے پاس واپس آیا۔ تو اس کا جواب یہ ہے کہ زمین میں پڑا ہوا بیج پڑا ہی رہتا ہے۔ جب اس کے اُگنے کا موقع آتا ہے۔ اُگتا وہ اسی وقت ہے پہلے نہیں اُگتا۔ اسی طرح جب تمہارے دوبارہ جی اُٹھنے کا وقت یا موسم آئے گا اسی وقت تم بھی اور تمہارے آباء و اجداد بھی جی کر زمین سے نکل آؤ گے پہلے نہیں۔ اور دوسری بات یہ کہ دوبارہ زندہ ہو کر تمہارے پاس نہیں آئیں گے بلکہ تم بھی اور وہ بھی اللہ کے حضور حاضر ہو جاؤ گے۔\nجس طرح دوسرے مقام پر بھی فرمایا ﴿وَ كُلٌّ اَتَوْهُ دٰخِرِيْنَ۰۰۸۷﴾ (النمل:87) ’’سب اس کی بارگاہ میں ذلیل ہو کر آئیں گے‘‘۔ ﴿اِنَّ الَّذِيْنَ يَسْتَكْبِرُوْنَ۠ عَنْ عِبَادَتِيْ سَيَدْخُلُوْنَ جَهَنَّمَ دٰخِرِيْنَؒ۰۰۶۰﴾ (المؤمن:60) ’’جو لوگ میری عبادت سے انکار کرتے ہیں، عنقریب وہ جہنم میں ذلیل و خوار ہو کر داخل ہوں گے۔‘‘\nفَاسْتَفْتِهِمْ اَهُمْ اَشَدُّ : آپ ان سے دریافت کریں جو قیامت کے دن اٹھائے جانے کا انکار کرتے ہیں کہ ایجاد کے لحاظ سے کیا زیادہ مشکل ہے ؟ کیا انھیں دوبارہ پیدا کرنا یا آسمانوں زمین اور ان دونوں کے درمیان جو فرشتے اور بڑی بڑی مخلوق ہیں ؟ ذہن نشین کریں اس استفہام میں انھیں ڈانٹ پلانامقصود ہے جب کہ وہ اس حقیقت کو تسلیم کرتے ہیں کہ یہ مخلوقات تخلیق کے لحاظ سے ان سے زیادہ مشکل ہے توتعجب ہے کہ وہ کیسے اٹھائے جانے کا انکار کر رہے ہیں جب کہ وہ ان مخلوقات کا مشاہدہ کررہے ہیں جوان سے حجم وغیرہ میں بڑی ہیں، تو ان کے مقابلہ میں ان انسانوں کی کیا نسبت ہے ؟ مزید دونوں کے درمیان تفاوت کو واضح کرتے ہوئے آگاہ کیا کہ ہم نے ان کے باپ آدم علیہ السلام کو نرم باہم ملی ہوئی مٹی سے پیدا کیا ہے اس وضاحت سے مقصود انسان کا ضعف اور اس میں نرمی کا مادہ ہے صلابت اور قوت نہیں ہے تو آسمان کے ستاروں اور فرشتوں اور عالم دنیا کے مشارق، مغارب کی نسبت کے لحاظ سے ہوئی اب دوبارہ اس کی تخلیق کیوں کر نہیں ہوسکتی ہے۔\nبَلْ عَجِبْتَ وَ يَسْخَرُوْنَ: اے محمد! صلی اللہ علیہ وسلم آپ تعجب کررہے ہیں کہ جب کہ کفار قیامت کے دن اٹھائے جانے کو جھوٹ قرار دیتے ہیں حالانکہ یہ لوگ اللہ کی عظیم حیران کن قدرت کے آثار کا مشاہدہ کررہے ہیں اس کے ساتھ ساتھ وہ نہ صرف آپ صلی اللہ علیہ وسلم کو اپنے تمسخر کا نشانہ بنا رہے ہیں اور آپ صلی اللہ علیہ وسلم کی باتوں کو لایعنی قرار دے رہے ہیں بلکہ آپ صلی اللہ علیہ وسلم کے تعجب پر بھی ہنس رہے ہیں اور جب انھیں قرآن پاک کی آیات کے ساتھ نصیحت کی جاتی ہے اور انہں ڈرایاجاتا ہے تو وہ نصیحت قبول نہیں کرتے ہیں بلکہ غور و فکر بھی نہیں کرتے ہیں جب کسی حیران کن نشانی یا کسی معجزہ کا مشاہدہ کرتے ہیں جو آپ صلی اللہ علیہ وسلم کی صداقت کا واضح نشان ہوتا ہے جیسا کہ آپ صلی اللہ علیہ وسلم کی انگلی کے اشارے سے چاند کا دوٹکڑے ہوجانا اور درختوں اور پتھروں کا کلام کرنا تو وہ مبالغہ کی حد تک مزاحیہ انداز پر اتر آتے ہیں بلکہ دیگر افراد کو بھی اکساتے ہیں کہ وہ بھی خود کو مزاح کے میدان میں اتاریں نیز وہ نہایت دھٹائی اور بےشرمی کے ساتھ کہتے ہیں کہ اے محمد صلی اللہ علیہ وسلم ! جس دین کو تونے ہمارے سامنے پیش کیا ہے یہ توکھلم کھلا جادوہی ہے دراصل اس سے ان واقعات کی جانب اشارہ ہے جو آپ صلی اللہ علیہ وسلم کے ہاتھوں پر عادت کے خلاف ظہور پذیر ہوئے۔\nءَاِذَا مِتْنَا وَ كُنَّا تُرَابًا : استفہام انکار ی ہے کفار انکار کرتے ہوئے مزاحیہ انداز اختیار کرتے ہوئے نہایت بےباکی کے ساتھ کہتے ہیں کہ جب ہمارے جسم موت کے بعد بوسیدہ ہوجائیں گے اور جسم کے اعضا ٹوٹ پھوٹ کا شکار ہو کر مٹی اور ہڈیوں کا ڈھانچہ دکھائی دیں گے تو پھر ہمیں کیسے اٹھایا جائے گا ؟ یا اسی طرح ہمارے آباء و اجداد کو جو ہم سے پہلے فوت ہوچکے ہیں انھیں کیسے اٹھایا جائے گا ؟ گویا کہ اٹھائے جانے کی حقیقت کو بعید از عقل قرار دے رہے ہیں کہ یہ کام ممکن ہی نہیں ہے۔"],[6117,"§کفار کی اس نازیبا گفتگو کا جواب\nاللہ پاک اس جواب سے محمد صلی اللہ علیہ وسلم کو آگاہ کررہے ہیں کہ تم یقیناً اٹھائے جاؤ گے اور تمہاری کیفیت انتہائی ذلت اور کسمپرسی کی ہوگی بس ایک زبردست خوفناک چیخ فضا میں پھیل جائے گی جس کو اسرافیل علیہ السلام ایک سینگ (صور) میں پھونکیں گے تو تمام لوگ قبروں سے اٹھ کھڑے ہوں گے حشر کے میدان میں سب اکٹھے ہوں گے ایک دوسرے کی جانب دیکھ رہے ہوں گے، تو جب وہ قیامت کی خوفناکیوں کا ملاحظہ کریں گے توحسرت اور ندامت کی کیفیت میں وہ یہ جملہ دہرائیں گے ہائے افسوس! ہم تباہ و برباد ہوگئے!!!۔\nہمیں زبردست نقصان پہنچا یہ دن تو واقعی جزاو سزا کا دن ہے کہ جس دن لوگوں کا محاسبہ ہونا ہے مزیدا نہیں افسوس میں اور حیرت میں ڈالنے کے لیے فرشتے نہایت گرجدارآواز میں جو دلوں کو دھلادینے والی ہوگی کہیں گے آج کا یہ دن فیصلے کا دن ہے تمام مخلوقات کے معاملات کا آج فیصلہ کیا جائے گا اور یہ وہ دن ہے جس کا تم زندگی بھرانکار کرتے رہے اور اس کو جھوٹ قرار دیتے رہے اس دن جنہوں نے زندگی بھر اچھے کام کیے ہوں گے ان کو انعامات کے ساتھ نوازا جائے گا، خوش خبری دی جائے گی مبارک باد دی جائے گی اور جن لوگوں نے دنیوی زندگی میں اللہ کے احکام کی مخالفت کی ہوگی اور اپنی خواہشات کے مطابق زندگی گزاری ہوگی ان کے درمیان فیصلہ کیا جائے گا۔\nوَ قَالُوْا يٰوَيْلَنَا هٰذَا يَوْمُ الدِّيْنِ۰۰۲۰ هٰذَا يَوْمُ الْفَصْلِ الَّذِيْ كُنْتُمْ بِهٖ\nتُكَذِّبُوْنَؒ۰۰۲۱ اُحْشُرُوا الَّذِيْنَ ظَلَمُوْا وَ اَزْوَاجَهُمْ وَ مَا كَانُوْا يَعْبُدُوْنَۙ۰۰۲۲ مِنْ دُوْنِ\nاللّٰهِ فَاهْدُوْهُمْ اِلٰى صِرَاطِ الْجَحِيْمِ۰۰۲۳ وَ قِفُوْهُمْ اِنَّهُمْ مَّسْـُٔوْلُوْنَ۠ۙ۰۰۲۴ مَا لَكُمْ\nلَا تَنَاصَرُوْنَ۰۰۲۵ بَلْ هُمُ الْيَوْمَ مُسْتَسْلِمُوْنَ۠۰۰۲۶\nاور وہ کہیں گے :ہائے ہماری بدبختی ! یہ تو جزا کا دن ہے) یہی فیصلے کا دن ہے جسے تم جھٹلاتے تھے ` (اے فرشتو!) اکٹھا کرو ان لوگوں کو جنھوں نے ظلم کیا اور ان کے جوڑوں کو اور (ان کو) جن کی وہ عبادت کیا کرتے تھے~ اللہ کے سوا، پھر انھیں دوزخ کی راہ دکھا دو - اور انھیں ٹھہرائو، بلاشبہ ان سے باز پرس کی جائے گی_ (کہا جائے گا:)تمھیں کیا ہوا، تم ایک دوسرے\nکی مدد نہیں کرتے ؟= بلکہ آج وہ (سب) فرماں بردار ہیں +\nقیامت کے دن کی ہولناکیاں: اللہ تعالیٰ نے بیان فرمایا ہے کہ قیامت کے دن کفار اپنے آپ کو ملامت کریں گے اور اعتراف کریں گے کہ انہوں نے دنیا میں اپنے اوپر خود ظلم کیا تھا اور جب روز قیامت کی ہولناکیوں کو دیکھیں گے تو بے حد ندامت کا اظہار کریں گے لیکن اس وقت ندامت کا انہیں کوئی فائدہ نہ ہو گا: ﴿وَ قَالُوْا يٰوَيْلَنَا هٰذَا يَوْمُ الدِّيْنِ۰۰۲۰﴾ ’’اور کہیں گے: ہائے شامت! یہی جزا کا دن ہے۔‘‘ فرشتے اور مومن انہیں جواب دیں گے: ﴿هٰذَا يَوْمُ الْفَصْلِ الَّذِيْ كُنْتُمْ بِهٖ تُكَذِّبُوْنَؒ۰۰۲۱﴾ ’’(کہا جائے گا:) یہی ہے فیصلے کا دن جس کو تم جھوٹ سمجھتے تھے۔‘‘ یہ انہیں ڈانٹ ڈپٹ کرتے ہوئے کہا جائے گا اور اللہ تعالیٰ فرشتوں کو حکم دے گا کہ وہ میدان حشر میں کافروں کو مومنوں سے الگ کر دیں، ارشاد ہو گا: ﴿اُحْشُرُوا الَّذِيْنَ ظَلَمُوْا وَ اَزْوَاجَهُمْ ﴾ ’’جو لوگ ظلم کرتے تھے ان کو اور ان کے ہم جنسوں کو جمع کر لو۔‘‘ نعمان بن بشیر رضی اللہ عنہما نے کہا ہے کہ ہم جنسوں سے مراد ان کے اشاہ وامثال ہیں۔ (تفسیر الطبری:56/23) ابن عباس رضی اللہ عنہما، سعید بن جبیر، عکرمہ، مجاہد، سدی، ابو صالح، ابو العالیہ اور زید بن اسلم رحمہ اللہ نے بھی اسی طرح کہا۔ (تفسیر الطبری:56/23،57) اور شریک رحمہ اللہ نے سماک رحمہ اللہ سے اور انہوں نے نعمان رحمہ اللہ سے روایت کیا ہے، انہوں نے کہا کہ میں نے سیدنا عمر رضی اللہ عنہ کو فرماتے ہوئے سنا: ﴿اُحْشُرُوا الَّذِيْنَ ظَلَمُوْا وَ اَزْوَاجَهُمْ ﴾ میں ہم جنسوں سے ایک جیسے لوگ مراد ہیں، زانی زانیوں کے ساتھ، سود خور سود خوروں کے ساتھ اور شرابی شرابیوں کے ساتھ آئیں گے۔ (تفسیر القرطبی:73/15) مجاہد اور سعید بن جبیر رحمہم اللہ نے ابن عباس رضی اللہ عنہما سے روایت کیا ہے کہ ﴿وَ اَزْوَاجَهُمْ ﴾ سے مراد ان کے ساتھی ہیں ﴿وَ مَا كَانُوْا يَعْبُدُوْنَۙ۰۰۲۲مِنْ دُوْنِ اللّٰهِ ﴾ ’’اور جن کی وہ اللہ کے سوا پوجا کرتے تھے (سب کو جمع کر لو۔)‘‘ یعنی ان کے بتوں اور معبودان باطلہ کو بھی ان کے ساتھ ان کی جگہوں میں جمع کیا جائے گا۔ ﴿فَاهْدُوْهُمْ اِلٰى صِرَاطِ الْجَحِيْمِ۰۰۲۳﴾ ’’پھر ان کو جہنم کے رستے پر چلا دو۔‘‘ یعنی جہنم کے رستے کی طرف ان کی رہنمائی کرو، یہ آیت حسب ذیل ارشاد باری تعالیٰ کی طرح ہے: ﴿وَ نَحْشُرُهُمْ يَوْمَ الْقِيٰمَةِ عَلٰى وُجُوْهِهِمْ عُمْيًا وَّ بُكْمًا وَّ صُمًّا١ؕ مَاْوٰىهُمْ جَهَنَّمُ١ؕ كُلَّمَا خَبَتْ زِدْنٰهُمْ سَعِيْرًا۰۰۹۷﴾ (بنی اسرائیل:97) ’’اور ہم ان کو قیامت کے دن اوندھے منہ، اندھے، گونگے اور بہرے (بنا کر) اٹھائیں گے اور ان کا ٹھکانا دوزخ ہے جب (اس کی آگ) بجھنے کو ہو گی تو ہم ان کو (عذاب دینے کے لیے) اور بھڑکا دیں گے۔‘‘\nاور ارشاد باری تعالیٰ ہے: ﴿وَ قِفُوْهُمْ اِنَّهُمْ مَّسْـُٔوْلُوْنَ۠ۙ۰۰۲۴﴾ ’’اور انہیں ٹھہرائے رکھو کہ ان سے (کچھ) پوچھنا ہے۔‘‘ یعنی ان کا ٹھہرائو تاکہ ان سے ان کے ان اعمال واقوال کی بابت پوچھا جائے جو دنیا میں ان سے صادر ہوئے تھے جیسا کہ ضحاک رحمہ اللہ نے ابن عباس رضی اللہ عنہما سے روایت کیا ہے کہ اس کے معنی یہ ہیں کہ انہیں روک لو تا کہ ان سے حساب لیا جائے۔ (تفسیر ابن أبی حاتم:3208/10) عبداللہ بن مبارک رحمہ اللہ نے کہا ہے کہ میں نے عثمان بن زائدہ رحمہ اللہ سے سنا، فرماتے تھے کہ آدمی سے سب سے پہلے اس کے ساتھیوں کے بارے میں سوال کیا جائے گا اور پھر ڈانٹ ڈپٹ کے طور پر ان سے کہا جائے گا: ﴿مَا لَكُمْ لَا تَنَاصَرُوْنَ۰۰۲۵﴾ ’’تمہیں کیا ہوا کہ ایک دوسرے کی مدد نہیں کرتے؟‘‘ جیسا کہ تم گمان کرتے تھے کہ ہماری جماعت بڑی مضبوط ہے ﴿بَلْ هُمُ الْيَوْمَ مُسْتَسْلِمُوْنَ۠۰۰۲۶﴾ ’’بلکہ آج تو وہ فرماں بردار ہیں۔‘‘ یعنی اللہ تعالیٰ کے حکم کے فرماں بردار ہیں، اس کی مخالفت نہیں کریں گے اور نہ اس سے دور ہوں گے۔ وَاللہُ أَعْلَمُ.\nاللہ تعالیٰ فرشتوں سے کہے گا کہ ان مجرموں کو میدانِ محشر میں روک لو تاکہ ان سے ان کے عقائد، اقوال اور اعمال کے بارے میں پوچھا جائے،پھر ان سے زجر و توبیخ کے طور پر پوچھا جائے گا کہ تم لوگ دنیا کی طرح یہاں بھی ایک دوسرے کی مدد کیوں نہیں کر رہے ہو ؟ ان کے پاس اس کا کوئی جواب نہ ہوگا، اس دن تو ذلت و رسوائی سے ان کی گردنیں جھکی ہوں گی اور ان میں سے جو کمزور لوگ دنیا میں متکبرین کی پیروی کرتے رہے تھے، ان متکبرین سے پوچھیں گے کہ تم لوگ دنیا میں ہمیں اپنی پیروی پر مجبور کرتے تھے، تو آج کیوں نہیں ہماری مدد کے لیے آگے بڑھتے ہو اور جہنم کا عذاب ہم سے ٹال دیتے ہو؟"],[6118,"§زوج کے تینوں معانی اکٹھے مراد ہیں\nازواج کا لفط تین معنوں میں استعمال ہوتا ہے اور اس مقام پر تینوں معنی دے رہا ہے۔ ایک معنی یہ ہے کہ مرد بیوی کا اور بیوی مرد کی زوج ہے۔ اس لحاظ سے معنی یہ ہوگا کہ فرشتوں کو حکم ہوگا کہ ظالموں اور ان کی بیویوں کو جو بغاوت میں ان کی شریک تھیں سب کو گھیر لاؤ۔ زوج کا دوسرا معنی اس کے مماثل ہوتا ہے۔ جیسے ایک جوتادوسرے کا زوج ہے۔ اس لحاظ سے معنی یہ ہوگا ظالموں کی جتنی اقسام ہیں ان سب کو گھیر کر لے آؤ۔ اور زوج کاتیسرا معنی اس کی ضد ہے جیسے رات دن کا زوج ہے اور دن رات کا، یا تاریکی روشنی کا زوج ہے۔ اور روشنی تاریکی کا۔ اس لحاظ سے معنی یہ ہوگا۔ معبودوں اور ان کے عبادت گزاروں سب کو گھیر گھار کر ہمارے سامنے لاحاضر کرو۔"],[6119,"§معبودانِ باطل کی تین اقسام\nاللہ کے سوا معبودوں کی بڑی قسمیں دو ہیں۔ ایک غیر ذوی العقول، ان میں بت، ستارے، شجر و حجر اور حیوانات وغیرہ مثلاً گائے، بیل اور سانپ وغیرہ سب کچھ آجاتا ہے۔ دوسرے ذوی العقول جیسے انبیاء، فرشتے، اولیاء اور بزرگ۔ پھر انسانوں اور جنوں میں سے کچھ ایسے معبود ہیں جو خود بھی چاہتے تھے کہ اللہ کے مقابلہ میں ان کی اطاعت کی جائے یا ان کی خدائی اور خدائی اختیارات تسلیم کیے جائیں۔ ان سب میں سے صرف فرشتے، انبیاء اور وہ بزرگ جہنم میں نہیں جائیں گے جو خود شرک سے منع کرتے رہے۔ باقی سب معبودوں کو اکٹھا کرکے جہنم میں پھینک دیاجائے گا اور اس کی وجہ پہلے کئی جگہ درج کی جا چکی ہیں۔"],[6120,"§مطیع اور مطاع کا قیامت کے دن مکالمہ\nایسے عابد اور معبود جنہیں جہنم میں داخل کر دینے کا حکم دیا جائے گا۔ فرشتوں کو حکم ہوگا کہ انہیں ذرا روک لو پہلے ان سے ایک بات تو پوچھ لیں۔ ان مجرموں میں ہر قسم کے عابد اور ہر قسم کے معبود ہوں گے۔ مشرکین اور ان کے معبودوں کا تو پہلے ذکر ہو چکا۔ ان میں چودھری اور رئیس بھی ہوں گے اور ان کے پیروکار بھی، سیاسی لیڈر بھی اور ان کی پارٹی کے لوگ بھی۔ خدائی کا دعویٰ کرنے والے اور خدائی کو منوانے والے بھی اور ماننے والے بھی۔ گوروجی اور ان کے چیلے چانٹے بھی، اعلیٰ حضرت بھی اور ان کی شفاعت پر بھروسہ کرنے والے مریدان باصفا بھی۔ اور یہ سب جوڑے اس دن ایک دوسرے سے بیزاری کا اظہار کررہے ہوں گے۔ ان سے پوچھاجائے گا کہ آج تمہیں کیا ہوگیاہے۔ آج تم ایک دوسرے سے بے تعلق کیوں ہو گئے ہو۔ اور وہ تمہاری شیخیاں اور تمہارے بلند بانگ دعوے کہاں گئے، دنیا میں جو تم نے آپس میں مل کر جتھے بنا رکھے تھے یا ایک دوسرے کی مدد کے دعوے کیا کرتے تھے۔ آج وہ تمہارے وعدے کہاں گئے انہیں پورا کیوں نہیں کرتے ؟\n﴿وَیْلٌ﴾ کا لفظ ہلاکت کے موقع پر بولا جاتا ہے، یعنی معائنہ عذاب کے بعد انہیں اپنی ہلاکت صاف نظر آ رہی ہوگی اور اس سے مقصود ندامت کا اظہار اور اپنی کوتاہیوں کا اعتراف ہے لیکن اس وقت ندامت اور اعتراف کا کوئی فائدہ نہیں ہوگا۔ اسی لیے ان کے جواب میں فرشتے اور اہل ایمان کہیں گے کہ یہ وہی فیصلے کا دن ہے جسے تم مانتے نہیں تھے۔ یہ بھی ممکن ہے کہ آپس میں ایک دوسرے کو کہیں گے۔\nوَ اَقْبَلَ بَعْضُهُمْ عَلٰى بَعْضٍ يَّتَسَآءَلُوْنَ۰۰۲۷ قَالُوْۤا اِنَّكُمْ كُنْتُمْ تَاْتُوْنَنَا عَنِ\nالْيَمِيْنِ۰۰۲۸ قَالُوْا بَلْ لَّمْ تَكُوْنُوْا مُؤْمِنِيْنَۚ۰۰۲۹ وَ مَا كَانَ لَنَا عَلَيْكُمْ مِّنْ\nسُلْطٰنٍ١ۚ بَلْ كُنْتُمْ قَوْمًا طٰغِيْنَ۰۰۳۰ فَحَقَّ عَلَيْنَا قَوْلُ رَبِّنَاۤ١ۖۗ اِنَّا لَذَآىِٕقُوْنَ۰۰۳۱\nفَاَغْوَيْنٰكُمْ۠ اِنَّا كُنَّا غٰوِيْنَ۰۰۳۲ فَاِنَّهُمْ يَوْمَىِٕذٍ فِي الْعَذَابِ مُشْتَرِكُوْنَ۰۰۳۳ اِنَّا\nكَذٰلِكَ نَفْعَلُ بِالْمُجْرِمِيْنَ۰۰۳۴ اِنَّهُمْ كَانُوْۤا اِذَا قِيْلَ لَهُمْ لَاۤ اِلٰهَ اِلَّا اللّٰهُ١ۙ\nيَسْتَكْبِرُوْنَ۠ۙ۰۰۳۵ وَ يَقُوْلُوْنَ اَىِٕنَّا لَتَارِكُوْۤا اٰلِهَتِنَا لِشَاعِرٍ مَّجْنُوْنٍؕ۰۰۳۶ بَلْ جَآءَ بِالْحَقِّ\nوَ صَدَّقَ الْمُرْسَلِيْنَ۰۰۳۷\nاور وہ ایک دوسرے کی طرف متوجہ ہو کر باہم پوچھیں گے کہیں گے : بے شک تم تو ہمارے پاس دائیں (اور بائیں) طرف سے آیا کرتے تھے رضی اللہ عنہما وہ کہیں گے : (نہیں!) بلکہ تم خود ہی ایمان لانے والے نہیں تھے صلی اللہ علیہ وسلم اور تم پر ہمارا کوئی زور نہیں تھا، بلکہ تم خود ہی سرکشی کرنے والے تھے رضی اللہ عنہا پھر ہم (سب) پر ہمارے رب کی بات ثابت ہو گئی، بے شک ہم (سب ہی عذاب کا مزہ) چکھنے والے ہیں رضی اللہ عنہ چنانچہ ہم نے تمھیں گمراہ کیا، بلاشبہ ہم خود بھی گمراہ تھے رضی اللہ عنہم چنانچہ یقیناً وہ اس دن عذاب میں مشترک ہوں گے علیہ السلام بے شک ہم مجرموں سے ایساہی (سلوک) کرتے ہیں علیہما السلام بے شک جب ان سے کہاجاتا کہ اللہ کے سوا کوئی معبود نہیں تو وہ تکبر کرتے تھے علیہم السلام اور کہتے: کیا بھلا ہم اپنے معبودوں کو ایک دیوانے شاعر کے کہنے پر چھوڑ دیں ؟ صلی اللہ علیہ وسلم بلکہ وہ تو حق لایا\nہے اور اس نے (سب) رسولوں کی تصدیق کی ہے ["],[6121,"§روزِ قیامت مشرکین کا باہمی جھگڑا\nاللہ تعالیٰ نے بیان فرمایا ہے کہ کفار قیامت کے دن ایک دوسرے کو ملامت کریں گے جیسا کہ وہ جہنم میں ایک دوسرے سے جھگڑیں گے: ﴿فَيَقُوْلُ الضُّعَفٰٓؤُا لِلَّذِيْنَ اسْتَكْبَرُوْۤا اِنَّا كُنَّا لَكُمْ تَبَعًا فَهَلْ اَنْتُمْ مُّغْنُوْنَ عَنَّا نَصِيْبًا مِّنَ النَّارِ۰۰۴۷قَالَ الَّذِيْنَ اسْتَكْبَرُوْۤا اِنَّا كُلٌّ فِيْهَاۤ١ۙ اِنَّ اللّٰهَ قَدْ حَكَمَ بَيْنَ الْعِبَادِ۰۰۴۸﴾ (المؤمن:47، 48) ’’تو کمزور لوگ ان لوگوں سے کہیں گے جنہوں نے تکبر کیا کہ ہم تو تمہارے تابع تھے تو کیا تم دوزخ (کے عذاب) کا کچھ حصہ ہم سے دور کر سکتے ہو؟ متکبر لوگ کہیں گے کہ تم (بھی اور) ہم (بھی) سب دوزخ میں ہیں۔ بے شک اللہ بندوں میں فیصلہ کر چکا ہے۔‘‘ اور فرمایا:﴿وَ لَوْ تَرٰۤى اِذِ الظّٰلِمُوْنَ مَوْقُوْفُوْنَ عِنْدَ رَبِّهِمْ١ۖۚ يَرْجِعُ بَعْضُهُمْ اِلٰى بَعْضِ ا۟لْقَوْلَ١ۚ يَقُوْلُ الَّذِيْنَ اسْتُضْعِفُوْا لِلَّذِيْنَ اسْتَكْبَرُوْا لَوْ لَاۤ اَنْتُمْ لَكُنَّا مُؤْمِنِيْنَ۰۰۳۱قَالَ الَّذِيْنَ اسْتَكْبَرُوْا لِلَّذِيْنَ اسْتُضْعِفُوْۤا اَنَحْنُ صَدَدْنٰكُمْ عَنِ الْهُدٰى بَعْدَ اِذْ جَآءَكُمْ بَلْ كُنْتُمْ مُّجْرِمِيْنَ۰۰۳۲وَ قَالَ الَّذِيْنَ اسْتُضْعِفُوْا لِلَّذِيْنَ اسْتَكْبَرُوْا بَلْ مَكْرُ الَّيْلِ وَ النَّهَارِ اِذْ تَاْمُرُوْنَنَاۤ۠ اَنْ نَّكْفُرَ بِاللّٰهِ وَ نَجْعَلَ لَهٗۤ اَنْدَادًا١ؕ وَ اَسَرُّوا النَّدَامَةَ لَمَّا رَاَوُا الْعَذَابَ١ؕ وَ جَعَلْنَا الْاَغْلٰلَ فِيْۤ اَعْنَاقِ الَّذِيْنَ كَفَرُوْا١ؕ هَلْ يُجْزَوْنَ اِلَّا مَا كَانُوْا يَعْمَلُوْنَ۰۰۳۳﴾ (سبا:31-33) ’’اور کاش! (ان) ظالموں کو آپ اس وقت دیکھیں جب یہ اپنے پروردگار کے سامنے کھڑے کیے جائیں گے جبکہ ان کا بعض کی بات کا رد کر رہا ہو گا، جو لوگ کمزور سمجھے جاتے تھے وہ ان لوگوں سے کہیں گے جو تکبر کرتے تھے: اگر تم نہ ہوتے تو ہم ضرور مومن ہو جاتے، بڑے لوگ کمزوروں سے کہیں گے: بھلا ہم نے تمہیں ہدایت سے، جب وہ تمہارے پاس آ چکی تھی روکا تھا؟ (نہیں) بلکہ تم ہی گناہ گار تھے اور کمزور لوگ بڑے لوگوں سے کہیں گے: (نہیں) بلکہ (تمہاری) رات دن کی چالوں نے (ہمیں روک رکھا تھا) جب تم ہم سے کہتے تھے کہ ہم اللہ سے کفر کریں اور اس کے شریک بنائیں اور جب وہ عذاب کو دیکھیں گے تو (سب دل میں) ندامت چھپائیں گے اور ہم کافروں کی گردنوں میں طوق ڈال دیں گے، بس جو عمل وہ کرتے تھے انہی کا انہیں بدلہ ملے گا۔‘‘\nاسی طرح وہ یہاں بھی ان سے کہیں گے: ﴿اِنَّكُمْ كُنْتُمْ تَاْتُوْنَنَا عَنِ الْيَمِيْنِ۰۰۲۸﴾ ’’بے شک تم ہی ہمارے پاس دائیں سے آتے تھے۔‘‘ ضحاک رحمہ اللہ نے ابن عباس رضی اللہ عنہما سے روایت کیا ہے کہ وہ کہیں گے کہ تمہیں ہم پر جو غلبہ وتسلط حاصل تھا اس کی وجہ سے تم ہمیں مغلوب کر لیتے تھے کیونکہ ہم کمزور تھے اور تم طاقتور تھے۔ (زاد المسیر:303/6) قتادہ رحمہ اللہ کہتے ہیں کہ انسان جنوں سے کہیں گے کہ تم ہمارے پاس دائیں طرف سے آتے تھے، یعنی خیر کی طرف سے اور ہمیں اس سے منع کرتے اور روکتے تھے۔ (تفسیر الطبری:60/23) اور سدّی رحمہ اللہ کہتے ہیں کہ تم ہمارے پاس حق کی طرف سے آتے تھے اور باطل کو ہمارے سامنے مزین کرتے تھے اور حق سے ہمیں روکتے تھے۔ (تفسیر الطبری:60/23) اور ابن زید رحمہ اللہ کہتے ہیں کہ اس کے معنی یہ ہیں کہ تم ہمارے اور خیر وبھلائی کے مابین حائل ہو جاتے تھے اور تم نے ہمیں اسلام، ایمان اور اس اچھے عمل سے دور کر دیا تھا جس کے کرنے کا ہمیں حکم دیا گیا تھا۔ (تفسیر الطبری:60/23) اور یزید رشک رحمہ اللہ کا قول ہے کہ اس کے معنی یہ ہیں کہ تم ہمیں لا الہ الا اللہ سے روکتے تھے۔\nارشاد باری تعالیٰ ہے: ﴿قَالُوْا بَلْ لَّمْ تَكُوْنُوْا مُؤْمِنِيْنَۚ۰۰۲۹﴾ ’’وہ کہیں گے بلکہ تم (خود ہی) ایمان لانے والے نہ تھے۔‘‘ جنوں اور انسانوں میں سے قائدین اپنے پیروکاروں سے کہیں گے کہ نہیں بات اس طرح نہیں جو تم کہتے ہو بلکہ بات یہ ہے کہ تمہارے دل ایمان سے منکر اور کفرونافرمانی کو قبول کرنے والے تھے ﴿وَ مَا كَانَ لَنَا عَلَيْكُمْ مِّنْ سُلْطٰنٍ١ۚ ﴾ ’’اور ہمارا تم پر کوئی زور نہ تھا۔‘‘ یعنی ہم نے تمہیں جس چیز کی دعوت دی تھی، اس کے صحیح ہونے کی ہمارے پاس کوئی دلیل نہ تھی ﴿بَلْ كُنْتُمْ قَوْمًا طٰغِيْنَ۰۰۳۰﴾ ’’بلکہ تم (خود) ہی سرکش لوگ تھے۔‘‘ بلکہ تم میں سرکشی تھی اور تم حق سے تجاوز کرتے تھے، اسی وجہ سے تم نے ہماری بات کو قبول کر لیا تھا اور تم نے اس حق کو ترک کر دیا تھا جسے انبیاء تمہارے پاس لائے تھے اور انہوں نے اس کے صحیح ہونے کے دلائل بھی قائم کر دیے تھے مگر تم نے ان کی مخالفت کی تھی ﴿فَحَقَّ عَلَيْنَا قَوْلُ رَبِّنَاۤ١ۖۗ اِنَّا لَذَآىِٕقُوْنَ۰۰۳۱ فَاَغْوَيْنٰكُمْ۠ اِنَّا كُنَّا غٰوِيْنَ۰۰۳۲﴾ ’’سو ہمارے بارے میں ہمارے پروردگار کی بات پوری ہو گئی، بے شک (اب) ہم (عذاب کے) مزے چکھنے والے ہیں۔ پس ہم نے تمہیں گمراہ کیا، یقیناً ہم خود بھی گمراہ تھے۔‘‘ بڑے لوگ کمزورں سے کہیں گے کہ ہم پر اللہ کی بات حق ثابت ہو گئی، لہٰذا ہم قیامت کے دن عذاب چکھنے والے بد بختوں میں سے ہو گئے ﴿فَاَغْوَيْنٰكُمْ۠ ﴾ ’’پس ہم نے تمہیں بھی گمراہ کیا۔‘‘ یعنی ہم نے تمہیں گمراہی کی طرف دعوت دی﴿اِنَّا كُنَّا غٰوِيْنَ۰۰۳۲﴾ ’’بے شک ہم خود بھی تو گمراہ تھے۔‘‘ یعنی جس گمراہی میں ہم خود مبتلا تھے ہم نے تمہیں دعوت دی اور تم نے اسے قبول کر لیا۔\nارشاد باری تعالیٰ ہے:﴿فَاِنَّهُمْ يَوْمَىِٕذٍ فِي الْعَذَابِ مُشْتَرِكُوْنَ۰۰۳۳﴾ ’’چنانچہ یقیناً وہ اس روز عذاب میں (ایک دوسرے کے)شریک ہوں گے۔‘‘یعنی سب درجہ بدرجہ جہنم میں ہوں گے۔ ﴿اِنَّا كَذٰلِكَ نَفْعَلُ بِالْمُجْرِمِيْنَ۰۰۳۴اِنَّهُمْ كَانُوْۤا اِذَا قِيْلَ لَهُمْ لَاۤ اِلٰهَ اِلَّا اللّٰهُ١ۙ يَسْتَكْبِرُوْنَ۠ۙ۰۰۳۵﴾ ’’یقیناً ہم مجرموں کے ساتھ ایسا ہی کرتے ہیں، بلاشبہ (ان کا یہ حال تھا کہ دنیا میں) جب بھی ان سے کہا جاتا تھا کہ اللہ کے سوا کوئی معبود نہیں تو غرور کرتے تھے۔‘‘ یعنی جس طرح مومن کہتے تھے کہ اللہ کے سوا کوئی معبود نہیں، وہ ازراہ تکبر ایسا نہیں کہتے تھے۔ ابن ابو حاتم رحمہ اللہ نے سیدنا ابو ہریرہ رضی اللہ عنہ کی روایت کو بیان کیا ہے، انہوں نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’مجھے حکم دیا گیا ہے کہ میں لوگوں سے لڑوں حتیٰ کہ وہ لا الہ الا اللہ کہہ دیں، پس جس نے لا الہ الا اللہ کہہ دیا اس نے مجھ سے اپنا مال اور جان کو بچا لیا سوائے اس کے حق کے اور اس کا حساب اللہ عزوجل کے ذمے ہے۔‘‘ اللہ نے اپنی کتاب میں لا الہ الا اللہ کہنے سے انکار کرنے والوں کا ذکر کرتے ہوئے فرمایا ہے: ﴿اِنَّهُمْ كَانُوْۤا اِذَا قِيْلَ لَهُمْ لَاۤ اِلٰهَ اِلَّا اللّٰهُ١ۙ يَسْتَكْبِرُوْنَ۠ۙ۰۰۳۵ وَ يَقُوْلُوْنَ اَىِٕنَّا لَتَارِكُوْۤا اٰلِهَتِنَا لِشَاعِرٍ مَّجْنُوْنٍؕ۰۰۳۶﴾ ’’بلاشبہ (ان کا یہ حال تھا کہ دنیا میں) جب (بھی) ان سے کہا جاتا تھا کہ اللہ کے سوا کوئی معبود نہیں تو غرور کرتے تھے اور کہتے تھے کہ بھلا ہم ایک دیوانے شاعر کے کہنے سے اپنے معبودوں کو چھوڑ دینے والے ہیں؟‘‘ (تفسیر ابن أبی حاتم:3210/10) یعنی کیا ہم اس دیوانے شاعر کے کہنے پر اپنے اور اپنے آباء واجداد کے معبودوں کی عبادت کو ترک کر دیں؟ دیوانہ شاعر وہ (معاذ اللہ) رسول اللہ صلی اللہ علیہ وسلم کو کہا کرتے تھے، اللہ تعالیٰ نے ان کی تکذیب وتردید کرتے ہوئے فرمایا ہے: ﴿بَلْ جَآءَ بِالْحَقِّ ﴾ ’’(نہیں) بلکہ وہ حق لائے ہیں۔‘‘ یعنی رسول اللہ صلی اللہ علیہ وسلم اللہ تعالیٰ کی طرف سے جس شریعت کو لے کر آئے ہیں وہ ساری کی ساری حق پر مبنی ہے، ﴿وَ صَدَّقَ الْمُرْسَلِيْنَ﴾ ’’اور اس نے (سب) رسولوں کی تصدیق کی ہے۔‘‘ یعنی انہوں نے آپ صلی اللہ علیہ وسلم کی جن پسندیدہ صفات اور صالح اعمال کا ذکر کیا تھا آپ صلی اللہ علیہ وسلم نے انہیں سچ ثابت کر دکھایا ہے اور اللہ تعالیٰ کی شریعت اور احکام کو اسی طرح بتایا ہے جس طرح سابقہ انبیائے کرام نے اس کی خبر دی تھی، ارشاد باری تعالیٰ ہے: ﴿مَا يُقَالُ لَكَ اِلَّا مَا قَدْ قِيْلَ لِلرُّسُلِ مِنْ قَبْلِكَ١ؕ ﴾ (حٰمٓ السجدة:43) ’’آپ سے وہی باتیں کہی جاتی ہیں جو آپ سے پہلے پیغمبروں سے بھی کہی گئی تھیں۔‘‘\nشیاطین یا سردارانِ کفر جواب دیں گے کہ تم مومن کب تھے کہ ہم نے تمہیں کفر پر آمادہ کیا اور نیک کب تھے کہ ہم نے تمہیں برائی کی راہ پر ڈال دیا اور اہل توحید کب تھے کہ ہم نے تمہیں شرک پر مجبور کیا ؟ تم لوگ ہمارے زیر تسلط نہیں تھے کہ ہم تمہیں طاقت کے بل بوتے پر کفر سے نکال کر ایمان میں داخل کر دیتے، تم تو ظلم و شرک اور کفر وطغیان میں حد سے تجاوز کیے ہوئے تھے، اس لیے آج اللہ کا وعدہ ہم سب کے لیے ثابت ہو گیا کہ ﴿لَاَمْلَـَٔنَّ جَهَنَّمَ مِنْكَ وَ مِمَّنْ تَبِعَكَ مِنْهُمْ اَجْمَعِيْنَ۰۰۸۵﴾ ’’اے ابلیس! ہم تجھ سے اور تیری پیروی کرنے والوں سے جہنم کو بھر دیں گے۔‘‘ (صٓ :85) اب ہم سب کو اس عذاب کا مزا چکھنا ہے جس کی دھمکی اللہ نے ہمیں دے رکھی تھی۔ اور بالآخر اپنی مجرمانہ حرکتوں کا اعتراف کرتے ہوئے کہیں گے کہ ہاں ! ہم نے تمہیں گمراہ کیا تھا، ہم چونکہ گمراہ تھے اس لیے چاہا کہ تم بھی ہمارے جیسے ہوجاؤ، لیکن ہم نے تمہیں مجبور نہیں کیا تھا، بلکہ کفر و شرک کی راہوں کو تمہارے لیے خوشنما بنا دیا تو تم ان پر ہمارے ساتھ چل پڑے۔"],[6122,"§لفظ یمین کے مختلف معنی اور ان سب کا اطلاق\nیمین کا لفظ بہت وسیع معنوں میں استعمال ہوتا ہے۔ مثلاً (1) یمین بمعنی دایاں ہاتھ بھی اور دائیں طرف بھی اور (2)اصحاب الیمین کے معنی دائیں ہاتھ یا دائیں جانب والے بھی اور اصحاب خیر وبرکت بھی (مفردات القرآن)۔ (3)پھر جس طرح یدکا لفظ قوت اور قبضہ کے معنوں میں آتا ہے یمین اس سے بھی زیادہ وسیع معنوں میں آتا ہے۔ کیونکہ قوت اور کارکردگی کے لحاظ سے دایاں ہاتھ بائیں سے افضل اور بہتر ہے۔ اور ملک یمین اس چیز کو کہتے ہیں جس پر پورا قبضہ اور اختیار ہو اور محاورۃ یہ لفظ لونڈی اور غلام کے معنوں میں آتا ہے۔ (4)علاوہ ازیں اہل عرب کی عادت تھی کہ اپنے عہد وپیمان اور قسم کومضبوط تر بنانے کے لیے اپنا ہاتھ مخاطب کے ہاتھ میں دیتے تھے یا مارتے تھے۔ لہٰذا یہ لفظ قسم کے معنوں میں بھی استعمال ہونے لگا یعنی ایسی قسم جو عہد و پیمان کو پختہ کرنے کے لیے اُٹھائی جائے۔\nاس آیت میں یمین کا لفظ تقریباً اپنے سب معانی کے لحاظ سے درست ہے۔ مثلاً کمزور یا پیروی کرنے والے لوگ اپنے بڑے بزرگوں سے کہیں گے کہ (1)تم لوگوں نے ہم پر کچھ ایسا دباؤ ڈال رکھا تھا کہ ہم تمہاری باتیں ماننے پر مجبور ہو گئے تھے۔یا(2)تم لوگوں نے یہ پروپیگنڈاکر رکھا تھا کہ جو راہ ہم نے اختیار کر رکھی ہے وہی خیر و برکت کا راستہ ہے لہٰذا ہم تمہارے بھرے میں آگئے یا(3)تم لوگوں نے قسمیں کھاکھا کر ہمیں یقین دلایا تھا کہ ہم فی الواقع تمہارے خیر خواہ ہیں۔ اس طرح تم نے ہمیں بھٹکا کر اپنے ساتھ لگالیا تھا اور ہم تمہاری اطاعت کرنے لگے تھے۔ اور ان سب مطالب کا خلاصہ یہی ہے کہ ہمیں اس انجام بد سے دو چار کرنے والے اور گمراہ کرنے والے تم ہی لوگ ہو۔"],[6123,"§خوشحال لوگوں کے اکڑنے کی تین وجوہ\nان کے تکبر کی کئی وجوہ تھیں، ایک یہ کہ جب انہیں یہ بتایا جاتا کہ اللہ کے سوا کوئی حاجت روا اور مشکل کشا نہیں تو تم اس میں اپنے بتوں اورمعبودوں کی بھی توہین سمجھتے تھے، اپنی بھی اور اپنے آباء و اجداد کی بھی لہٰذا وہ اکڑ بیٹھتے تھے دوسری یہ کہ مشرکانہ رسوم کے رواج سے جو کچھ دنیوی مفادات حاصل کر رہے تھے اس سے انہیں دستبردار ہونا پڑتا تھا لہٰذا وہ اکڑ بیٹھتے تھے، تیسری یہ کہ اگر وہ لاالٰہ الا اللہ کا دل سے اقرار کرتے تو انہیں اپنی چودھراہٹوں اور سرداریوں سے دستبردار ہو کر اللہ اور اس کے رسول صلی اللہ علیہ وسلم کی اطاعت کرنا پڑھتی تھی۔ لہٰذا وہ اکڑ بیٹھتے تھے۔"],[6124,"§شاعر اور نبی کا فرق\nتمام پیغمبروں کو اور اسی طرح رسول اللہ صلی اللہ علیہ وسلم کو بھی شاعر اور مجنون کے القابات سے نوازاجاتا رہاہے۔ شاعر کا کام یہ ہوتا ہے کہ وہ فصیح اور منظوم زبان میں اپنے تخیل کی بلندی اور نکتہ آفرینی یوں پیش کرتا ہے کہ اس سے سننے والے پر عارضی اور وقتی طور پر ایک وجدانی سی کیفیت آجاتی ہے۔ قرآن کریم گوبحر اور اوزان سے مبرا ہے لیکن دل میں اُتر جانے کے لحاظ سے اس میں شعر سے بھی زیادہ تاثیر پائی جاتی ہے۔ اسی وجہ مماثلت کی بنا پر آپ صلی اللہ علیہ وسلم کو شاعر بھی کہاجاتا رہا ہے۔ حالانکہ شاعر اور نبی میں زمین و آسمان کا فرق ہوتا ہے۔ شاعر کے کلام میں جب تک جھوٹ، مبالغہ اور غلو شامل نہ ہو اس میں کچھ دلکشی پیدا نہیں ہوتی۔ جبکہ اللہ کا کلام ایسی تمام بے ہودگیوں سے پاک ہوتا ہے۔ شاعر کے تخیل کی پرواز کا میدان زندگی کا ہر اچھا یا بُرا پہلو ہوتا۔ماحول کا تاثر اس کی طبیعت پر غالب رہتا ہے اور معاشرہ کی اکثریت چونکہ گمراہ ہوتی ہے لہٰذا اس کا تخیل بھی انہی راستوں پر پرواز کرتا ہے۔ جبکہ اللہ کے کلام کا بنیادی موضوع صرف ایک ہے اور وہ ہے انسان کو حکیمانہ اور ناصحانہ اندازمیں ہدایت کی راہ دکھانا۔ مزید برآں شاعر کے قول اور فعل میں نمایاں تضاد ہوتا ہے جبکہ ایک پیغمبر جو کچھ کہتا ہے سب سے پہلے اس پر خود عمل کرکے دکھاتا ہے۔ پھر دوسروں کو دعوت دیتا ہے۔"],[6125,"§مجنون اور نبی کا فرق\nپیغمبروں کو کفار اور بالخصوص وہ لوگ جو آخرت اور جزا و سزا کے منکر ہوتے ہیں دیوانہ اس لحاظ سے کہتے ہیں کہ ان کے خیال میں مرنے کے بعد جی اُٹھنا، اللہ کی عدالت میں پیش ہونا اور روزِ قیامت کے ہولناک مناظر اور جنت و دوزخ سب طلسماتی اور افسانوی قسم کی باتیں ہیں۔ لہٰذا وہ سمجھتے ہیں کہ ان کے حواس ٹھکانے نہیں رہے۔ حالانکہ نبی ہر ایک کا ہمدرد، عہد کا پابند، پاکیزہ سیرت و کردار کا مالک ہوتا ہے۔ جبکہ دیوانوں کا نہ کوئی اخلاق ہوتا ہے نہ سیرت و کردار حتیٰ کہ وہ ساری ہی باتیں بہکی بہکی کرتے ہیں۔ اور لوگ ان کی دیوانہ وارحرکتوں سے خائف رہتے ہیں اور ان سے بچنے کی کوشش کرتے ہیں۔\nاور کافروں کی ناانصافی یہ ہوتی ہے کہ ان کے زعم کے مطابق محض ایک وجہ مماثلت کی بنا پر پیغمبروں کو شاعر اور مجنوں کہہ دیتے ہیں جبکہ بے شمار پہلوؤں میں وہ شاعروں اور دیوانوں سے مختلف ہوتےہیں۔ اور ان کے دل ان سب باتوں کی گواہی بھی دیتے ہیں۔ مگر صرف پیغمبروں سے مخالفت کی بنا پر انہیں ایسے ناموزوں القابات سے نوازتے ہیںاور ایک دوسرے سے کہتے ہیں کہ بھلا ہم ایسے شاعروں اور دیوانوں کے کہنے پر اپنے معبودوں کوچھوڑ سکتے ہیں۔"],[6126,"§بُعد زمانی کے باوجود مماثلت نبی کی تعلیم کے برحق ہونے کا ثبوت ہے\nرسول جو کچھ کلام پیش کرتا ہے وہ نہ طلسماتی باتیںہیں اور نہ افسانے اور تمثیلی داستانیں ہیں بلکہ اس کی تعلیم ٹھوس حقائق پر مبنی ہے۔ نبی اپنے سے پہلے رسولوں کی بھی تصدیق کرتا ہے اور ان کی تعلیم کی بھی حالانکہ ان کے زمانہ میں سینکڑوں سال کی مدت حائل ہوتی ہے۔ اس بعد زمانی کے باوجود رسولوں علیہم السلام کی تعلیم میں مماثلت یہ ان کی اور ان کی تعلیم کے حق ہونے کا بڑا قوی ثبوت ہے۔"],[6127,"§جنت کے رزق کی خصوصیات\nیعنی وہ رزق جو کتاب و سنت میں جا بجامذکور ہے۔ مثلاً یہ کہ وہ ہر قسم کے اور آپس میں ملتے جلتے پھلوں پر مشتمل ہوگا۔ جبکہ ان کا مزا بالکل ایک دوسرے سے جداگانہ ہوگا۔ نیز انہیں ہر وہ چیز مہیا کی جائے گی جس کی وہ خواہش کریں گے۔ اس رزق کی ایک صفت یہ ہے کہ وہ باعزت طور پر دیاجائے گا۔ ایک یہ ہے کہ وہ کبھی ختم نہ ہوگا نہ اس کا سلسلہ منقطع ہوگا۔ ایک یہ کہ جو رزق انہیں دیاجائے گا اسے اس دنیا میں پوری طرح سمجھا بھی نہیں جا سکتا کیونکہ ویسی چیزیں نہ کسی نے دیکھی ہیں، نہ سنی ہیں اور نہ کسی کے حاشیہ خیال میں آسکتی ہیں۔ اور سب سے بڑھ کر یہ کہ وہ رزق صرف لذت حاصل کرنے کے لیے کھایاجائے گا۔ بھوک لگنے کی بنا پرنہیں کھایاجائے گا۔یعنی اس لیے نہیں کہ محنت و مشقت کی وجہ سے بدن کے کچھ اجزاء تحلیل ہو چکے ہیں تو ان کی تلافی کے لیے یا اپنی زندگی کی بقا کے لیے وہ رزق کھایاجائے۔\nتابعین اور متبوعین کی یہ باہمی تکرار قرآن کریم میں کئی جگہ بیان کی گئی ہے۔ ان کی ایک دوسرے کو یہ ملامت عرصہ قیامت (میدان محشر) میں بھی ہوگی اور جہنم میں جانے کے بعد جہنم کے اندر بھی۔ ملاحظہ ہو المؤمن۔47، 48۔ سورة سبا۔ 31، 32۔ الاحزاب۔ 67، 68- الأعراف۔38، 39 وغیرھا من الآیات۔\nیعنی جس بات کی پہلے، انہوں نے نفی کی، کہ ہمارا تم پر کون سا زور تھا کہ تمہیں گمراہ کرتے۔ اب اس کا یہاں اعتراف ہے کہ ہاں واقعی ہم نے تمہیں گمراہ کیا تھا۔ لیکن یہ اعتراف اس تنبیہ کے ساتھ کیا کہ ہمیں اس ضمن میں مورد طعن مت بنائو، اس لیے کہ ہم خود بھی گمراہ ہی تھے، ہم نے تمہیں بھی اپنے جیسا ہی بنانا چاہا اور تم نے آسانی سے ہماری راہ اپنا لی۔ جس طرح شیطان بھی اس روز کہے گا۔ ﴿وَ مَا كَانَ لِيَ عَلَيْكُمْ مِّنْ سُلْطٰنٍ اِلَّاۤ اَنْ دَعَوْتُكُمْ فَاسْتَجَبْتُمْ لِيْ١ۚ فَلَا تَلُوْمُوْنِيْ وَ لُوْمُوْۤا اَنْفُسَكُمْ١ؕ﴾ (ابراہیم:22) ’’میرا تم پر کوئی اختیار نہیں تھا، ہاں میں نے تمہیں بلایا تو تم نے میری بات مان لی، پس (اب) تم مجھے ملامت نہ کرو، اپنے آپ کو ملامت کرو۔‘‘\nیعنی دنیا میں، جب ان سے کہا جاتا تھا کہ جس طرح مسلمانوں نے یہ کلمہ پڑھ کر شرک و معصیت سے توبہ کر لی ہے، تم بھی یہ پڑھ لو، تاکہ تم دنیا میں بھی مسلمانوں کے قہروغضب سے بچ جائو اور آخرت میں بھی عذاب الٰہی سے تمہیں دوچار ہونا نہ پڑے، تو وہ تکبر کرتے اور انکار کرتے۔ نبی صلی اللہ علیہ وسلم کا فرمان ہے۔ ((اُمِرْتُ اَنْ اُقَاتِلَ النَّاسَ حَتّٰی یَقُوْلُوْا لَا اِلٰـہَ اِلَّا اللہُ فَمَنْ قَالَ لَا اِلٰـہَ اِلَّا اللہُ فَقَدْ عَصَمَ مِنِّیْ مَا لَـہٗ وَ نَفْسَہٗ)). (صحیح البخاری، صحیح مسلم) ’’مجھے اس بات کا حکم دیا گیا ہے کہ میں اس وقت تک لوگوں سے قتال کروں جب تک وہ لا الٰہ الا اللہ کا اقرار نہ کر لیں۔ جس نے یہ اقرار کر لیا، اس نے اپنی جان اور مال کی حفاظت کر لی۔‘‘\nاللہ فرمائے گا ظالموں اور ان جیسے نافرمانوں اور مجرم لوگوں کو اکٹھاکرو ہر انسان کو اس کے رفقاء کے ساتھ اکٹھاکرو زانیوں کو زانیوں کے ساتھ اور شرابیوں کو شرابیوں اور چوروں کو چوروں کے ساتھ بلکہ ان کی عورتیں جو بھی کافر تھیں اور ان کو جو اللہ کے سوامعبودوں کی عبادت کیا کرتے تھے اور ان کے اکٹھا کرنے میں ان کی شرمندگی اور حسرت میں اضافہ ہوگا اور ان کو جو بتوں کی عبادت کرتے تھے انھیں دوزخ کے راہ کا تعارف کراؤ ان کے چہرے دوزخ کی جانب ہوں اس لیے کہ وہ دنیوی زندگی میں صراط مستقیم پر رواں دواں نہیں رہے ہیں تو آج وہ دوزخ کے راہ کی جانب چلیں اور پل صراط پر انھیں روکے رکھوان سے ان کی گفتار اور کردار کے بارے میں سوال کیا جائے گا پھرا نہیں ڈانٹ پلاتے ہوئے کہا جائے گا کہ تمہیں کیا ہوگیا ہے کہ تم ایک دوسرے کی مدد نہیں کررہے ہو جب کہ تم یہاں اکٹھے ہو اور تم میں سے ہر شخص کو مددگار اور معاون کی ضرورت ہے اس میں ابوجہل کے قول کی جانب اشارہ ہے جب اس نے کہا کہ ہم سب اکٹھے ہیں ایک دوسرے کی مدد کرنے والے ہیں بلکہ وہ آج کے دن ذلیل ہیں اطاعت و فرمان برداری کا مجسمہ دکھائی دے رہے ہیں اپنے مخالف سے بدلہ لینے کی ان میں سکت نہیں ہے خواہ ایسے افراد ہوں جو غیر اللہ کی عبادت کرنے والے تھے خواہ ان کی عبادت ہوا کرتی تھی قیامت کے دن کسی انسان کے دونوں قدم اس وقت تک بارگاہ الٰہی سے ادھرادھر نہیں ہوں گے جب تک کہ وہ پانچ سوالات کا جواب نہیں دے پائیں گے ان سے دور جوانی کے بارے میں استفسار کیا جائے گا کہ تم نے ان کو کن کاموں کے باعث بوسیدہ کیا اور اپنی پیاری زندگی کو کن کاموں کے سرانجام دینے میں فنا کیا اور مال کو کیسے حاصل کیا اور کہاں خرچ کیا اور کون ساعلم حاصل کیا اور کیا علم کے مطابق عمل کیا۔\nپھرا نہیں ڈانٹ پلاتے ہوئے کہا جائے گا کہ تمہیں کیا ہوگیا ہے کہ تم ایک دوسرے کی مدد نہیں کررہے ہو جب کہ تم اکٹھے ہو اور تم میں سے ہر ایک کو مددگا رکی ضرورت ہے بلکہ وہ اس دن ذلیل مجسمہ اطاعت ہوں گے ان میں سے کسی میں بدلہ لینے کی سکت نہیں ہے عام ہے کہ ان کی عبادت ہوتی رہی یا وہ کسی کی عبادت میں مصروف رہے اور لیڈر اور ان کے پیروکار آپس میں ایک دوسرے کو ملامت کریں گے اور جھگڑا کریں گے جب کہ ان کا ایک دوسرے سے استفسار کرنا ڈانٹ پلانے کے انداز کے مطابق ہوگا اور آپس میں جنگ و جدال کی نوعیت کا ہوگا چنانچہ عوامی قسم کے لوگ اپنے لیڈروں کو ملامت کریں گے ان سے جھگڑاکریں گے اور کہیں گے تم بظاہر ہمارے پاس حق و صداقت کالبادہ اوڑھ کر آتے تھے اور درپردہ باطل کو تزئین و آرائش کے ساتھ پیش کرتے تھے ہمیں دھوکے میں مبتلا کرتے رہے مزیدبرآں تم ہمیں وسوسہ میں مبتلا کرتے رہے ان کی ان باتوں کے جواب میں لیڈ رقسم کے لوگ کہیں گے ہم نے تمہیں گمراہ کے گڑھے میں نہیں گرایا اور نہ تمہیں ایمان لانے سے روکا ہے بلکہ تم نے کفر اختیار کیا اور ایمان کو قبول نہ کیا۔\nمزیدبرآں ہمیں تم پر ہرگز غلبہ نہ تھا کہ ہم تمہیں بالجبر اپنی اطاعت میں لے آتے بلکہ تم سرکش لوگ تھے فسق وفجور کے دل دادہ تھے یہی وجہ ہے کہ تم نے ہماری بات کو تسلیم کیا اور تم ہمارے پیروکار ہوگئے تو ہم سب پر اللہ کی وعید لازم ہوگئی کہ ہمیں عذاب میں گرفتار کیا جائے گا جب کہ ہم نے تمہارے سامنے باطل کو مزین کرکے پیش کیا اور ہم نے تم کو گمراہی کی جانب دعوت دی اس لیے کہ ہم خود گمراہی کے تاریک گڑھے میں گرے ہوئے تھے اس پر اللہ تعالیٰ ان کی کیفیت سے آگاہ کررہے ہیں کہ وہ لوگ لازمی طور پر عذاب میں شریک ہوں گے جیسا کہ گمراہی میں شریک تھے ہم اسی طرح بدنصیب گناہ گا روں کو عذاب میں مبتلا کیا کرتے ہیں۔\nاِنَّهُمْ كَانُوْۤا اِذَا قِيْلَ لَهُمْ لَاۤ اِلٰهَ اِلَّا اللّٰهُ١ۙ يَسْتَكْبِرُوْنَ۠: انھیں عذاب میں مبتلا کرنے کا باعث کیا تھا اس کی وضاحت ہورہی ہے کہ جب ان سے کہا جاتا تھا کہ تم ایک اللہ ہی کو معبود حقیقی قرار دو تو وہ کبر ونخوت پر اُتر آتے تھے نیز دعوت کے جواب میں کہتے کہ کیا ہم ایک شاعر دیوانہ قسم کے شخص کے کہنے پر اپنے معبودوں سے انقطاع کرلیں ان کا اشارہ (نعوذ باللہ) محمد صلی اللہ علیہ وسلم کی جانب تھا ان کی تردید کرتے ہوئے اللہ پاک فرماتے ہیں معاملہ اس طرح نہیں ہے جیسا کہ وہ افترا پردازی سے کام لے رہے ہیں بلکہ محمد صلی اللہ علیہ وسلم نے ان کے پاس اسلام اور توحید کو پیش کیا ہے جس کی حقانیت روز روشن کی طرح واضح ہے اور جس طرح ان سے پہلے پیغمبروں نے جس چیز کو پیش کیا وہ بھی اس کو پیش کررہے ہیں۔"],[6128,"§ابوحیان رحمہ اللہ کی وضاحت\nمشرکین نے جہاں اللہ پاک کی وحدانیت کا انکار کیا وہاں انھوں نے رسالت کا بھی انکار کیا مزید برآں انھوں نے آپ صلی اللہ علیہ وسلم کے خلاف ایک الزام یہ عائد کیا کہ وہ شاعر ہے اس کے ساتھ انھوں نے آپ صلی اللہ علیہ وسلم کو دیوانہ بھی قرار دیا جب کہ شاعر اس شخص کو کہا جاتا ہے جس میں فہم و ادراک کا مادہ پایاجاتا ہے اور جن معانی و مقاصد کو وہ اپنے الفاظ میں سموتا ہے ان کے لحاظ سے اس کا فہیم اور سمجھدار ہونا ضروری ہے تب ہی پرکشش معانی کو فصاحت و بلاغت کے قالب میں سموسکتا ہے ظاہر ہے کہ دیوانہ انسان اس لائق نہیں ہوتا کہ وہ پر مغز اور باعث کشش کلام پیش کرے اس لحاظ سے ان کا آپ صلی اللہ علیہ وسلم کے بارے میں شاعر مجنون کہنا ان کی حماقت کی دلیل ہے۔\nاِنَّكُمْ لَذَآىِٕقُوا الْعَذَابِ الْاَلِيْمِ: مجرمین کے بارے میں تاکید کے ساتھ آگاہ کیا جارہا ہے کہ تمہیں شدید قسم کے عذاب میں مبتلا کیا جائے گا اور تمہیں تمہارے برے اعمال کے برابر سزاد ی جائے گی ظاہر ہے کہ برائی پر سزاتوبرائی کے مطابق دی جائے گی جب کہ نیک اعمال کا بدلہ دس گنا سے لے کر کئی گنا تک حاصل ہوسکتا ہے۔\nاِنَّكُمْ لَذَآىِٕقُوا الْعَذَابِ الْاَلِيْمِۚ۰۰۳۸ وَ مَا تُجْزَوْنَ اِلَّا مَا كُنْتُمْ تَعْمَلُوْنَۙ۰۰۳۹ اِلَّا\nعِبَادَ اللّٰهِ الْمُخْلَصِيْنَ۰۰۴۰ اُولٰٓىِٕكَ لَهُمْ رِزْقٌ مَّعْلُوْمٌۙ۰۰۴۱ فَوَاكِهُ١ۚ وَ هُمْ\nمُّكْرَمُوْنَۙ۰۰۴۲ فِيْ جَنّٰتِ النَّعِيْمِۙ۰۰۴۳ عَلٰى سُرُرٍ مُّتَقٰبِلِيْنَ۰۰۴۴ يُطَافُ عَلَيْهِمْ بِكَاْسٍ\nمِّنْ مَّعِيْنٍۭۙ۰۰۴۵ بَيْضَآءَ لَذَّةٍ لِّلشّٰرِبِيْنَۚۖ۰۰۴۶ لَا فِيْهَا غَوْلٌ وَّ لَا هُمْ عَنْهَا يُنْزَفُوْنَ۰۰۴۷\nوَ عِنْدَهُمْ قٰصِرٰتُ الطَّرْفِ عِيْنٌۙ۰۰۴۸ كَاَنَّهُنَّ بَيْضٌ مَّكْنُوْنٌ۰۰۴۹\nبے شک تم اب دردناک عذاب (کامزہ) ضرور چکھو گے ] تمھیں بس اسی کا بدلہ دیا جائے گا جو تم عمل کرتے تھے مگر اللہ کے چنے ہوئے بندے (عذاب سے محفوظ رہیں گے) انھی (لوگوں) کے لیے مقررہ روزی ہے یعنی (جنت کے) لذیذ پھل اور وہ لوگ معزز ہوں گے نعمت کے باغوں میں ایک دوسرے کے سامنے تختوں پر (براجمان) ہوں گے ان کے لیے جاری چشمے سے شراب (طہور) کا بھرا جام پھرایا جائے گا سفید رنگ (بالکل صاف شفاف) پینے والوں کے لیے لذت (والی ہوگی) نہ اس سے سر چکرائے گا اور نہ وہ اس سے مدہوش ہوں گے اور ان کے پاس ہوں گی نیچی نگاہ والی،\nغزال چشم (خوبصورت آنکھوں والی حوریں)گویا کہ وہ پردوں میں چھپائے ہوئے (شتر مرغ کے)انڈے ہیں۔{"],[6129,"§مشرکین کی سزا اور مخلصین کی جزا\nاللہ تعالیٰ نے لوگوں سے مخاطب ہو کر فرمایا ہے: ﴿اِنَّكُمْ لَذَآىِٕقُوا الْعَذَابِ الْاَلِيْمِۚ۰۰۳۸ وَ مَا تُجْزَوْنَ اِلَّا مَا كُنْتُمْ تَعْمَلُوْنَۙ۰۰۳۹﴾ ’’بے شک تم تکلیف دینے والے عذاب کو چکھنے والے ہو اور تمہیں ویسے ہی بدلہ ملے گا جیسے تم کام کرتے تھے۔‘‘ پھر اللہ تعالیٰ نے اپنے مخلص بندوں کو اس سے مستثنیٰ قرار دیا ہے جیسا کہ ارشاد باری تعالیٰ ہے: ﴿وَ الْعَصْرِۙ۰۰۱اِنَّ الْاِنْسَانَ لَفِيْ خُسْرٍۙ۰۰۲اِلَّا الَّذِيْنَ اٰمَنُوْا وَ عَمِلُوا الصّٰلِحٰتِ وَ تَوَاصَوْا بِالْحَقِّ١ۙ۬ وَ تَوَاصَوْا بِالصَّبْرِؒ۰۰۳﴾ (العصر:1-3) ’’زمانے کی قسم! یقیناً انسان نقصان میں ہے مگر وہ لوگ جو ایمان لائے اور نیک عمل کرتے رہے اور آپس میں حق (بات) کی تلقین اور صبر کی تاکید کرتے رہے۔‘‘ اور فرمایا:﴿لَقَدْ خَلَقْنَا الْاِنْسَانَ فِيْۤ اَحْسَنِ تَقْوِيْمٍٞ۰۰۴ثُمَّ رَدَدْنٰهُ اَسْفَلَ سٰفِلِيْنَۙ۰۰۵اِلَّا الَّذِيْنَ اٰمَنُوْا وَ عَمِلُوا الصّٰلِحٰتِ ﴾ (التین:4-6) ’’البتہ تحقیق ہم نے انسان کو بہت اچھی صورت میں پیدا کیا ہے، پھر ہم نے اسے نیچوں سے نیچے پھینک دیا مگر جو لوگ ایمان لائے اور نیک عمل کرتے رہے۔‘‘ اور فرمایا: ﴿وَ اِنْ مِّنْكُمْ اِلَّا وَارِدُهَا١ۚ كَانَ عَلٰى رَبِّكَ حَتْمًا مَّقْضِيًّاۚ۰۰۷۱ثُمَّ نُنَجِّي الَّذِيْنَ اتَّقَوْا وَّ نَذَرُ الظّٰلِمِيْنَ فِيْهَا جِثِيًّا۰۰۷۲﴾ (مریم :71-72) ’’اور تم میں کوئی (شخص) نہیں مگر اسے اس پر (سے) گزرنا ہو گا، یہ آپ کے پروردگار کے ذمے حتمی اور طے شدہ بات ہے، پھر ہم پرہیز گاروں کو نجات دیں گے اور ظالموں کو اسی میں گھٹنوں کے بل پڑا ہوا چھوڑ دیں گے۔‘‘ اور فرمایا: ﴿كُلُّ نَفْسٍۭ بِمَا كَسَبَتْ رَهِيْنَةٌۙ۰۰۳۸اِلَّاۤ اَصْحٰبَ الْيَمِيْنِؕۛ۰۰۳۹﴾ (المدثر:38،39) ’’ہر شخص اپنے اعمال کے بدلے گروی ہے، مگر دائیں طرف والے (نیک لوگ۔)‘‘\nاسی لیے اللہ جل وعلانے یہاں فرمایا ہے:﴿اِلَّا عِبَادَ اللّٰهِ الْمُخْلَصِيْنَ۰۰۴۰﴾ ’’مگر جو اللہ کے چنے ہوئے بندے ہیں۔‘‘وہ تکلیف دینے والے عذاب کا مزہ نہیں چکھیں گے اور نہ ان سے حساب لیا جائے گا بلکہ اگر ان کے گناہ ہوئے بھی تو اللہ تعالیٰ ان کے گناہوں سے درگزر فرمائے گا اور ان کی نیکیوں کا انہیں دس گنا سے لے کر سات سو گنا تک اجروثواب عطا فرمائے گا بلکہ جس قدر اللہ تعالیٰ چاہے گا انہیں اجروثواب عطا فرمائے گا۔ ارشاد باری تعالیٰ ہے: ﴿اُولٰٓىِٕكَ لَهُمْ رِزْقٌ مَّعْلُوْمٌ﴾ ’’یہی لوگ ہیں جن کے لیے روزی مقرر ہے۔‘‘ امام قتادہ اور سدّی رحمہم اللہ کہتے ہیں کہ اس سے مراد جنت ہے۔ (تفسیر الطبری:63/23) پھر اللہ تعالیٰ نے ﴿رِزْقٌ مَّعْلُوْمٌۙ۰۰۴۱﴾ کی وضاحت کرتے ہوئے فرمایا: ﴿فَوَاكِهُ١ۚ ﴾ ’’پھل‘‘ مختلف واقسام کے ﴿وَ هُمْ مُّكْرَمُوْنَۙ۰۰۴۲﴾ ’’اور وہ معزز لوگ ہوں گے۔‘‘ یعنی انہیں خادم مہیا کیے جائیں گے، عیش وعشرت کی زندگی عطا کی جائے گی اور طرح طرح کی نعمتوں سے سرفراز کیا جائے گا ﴿فِيْ جَنّٰتِ النَّعِيْمِۙ۰۰۴۳عَلٰى سُرُرٍ مُّتَقٰبِلِيْنَ۰۰۴۴﴾ ’’نعمت کے باغوں میں، ایک دوسرے کے سامنے تختوں پر (بیٹھے ہوں گے۔)‘‘ مجاہد کہتے ہیں کہ ان میں سے بعض، بعض کی گدی کی طرف نہیں دیکھیں گے۔ (تفسیر القرطبی:77/15) ﴿يُطَافُ عَلَيْهِمْ بِكَاْسٍ مِّنْ مَّعِيْنٍۭۙ۰۰۴۵بَيْضَآءَ لَذَّةٍ لِّلشّٰرِبِيْنَۚۖ۰۰۴۶لَا فِيْهَا غَوْلٌ وَّ لَا هُمْ عَنْهَا يُنْزَفُوْنَ۰۰۴۷﴾ ’’ان پر جاری چشموں سے شراب (طہور) کا بھرا جام پھرایا جائے گا، سفید رنگ، پینے والوں کے لیے (سراسر) لذت (والی ہو گی)، نہ اس سے سر چکرائے گا اور نہ مدہوش ہوں گے۔‘‘ جیسا کہ ایک دوسرے مقام پر فرمایا: ﴿يَطُوْفُ عَلَيْهِمْ وِلْدَانٌ مُّخَلَّدُوْنَۙ۰۰۱۷بِاَكْوَابٍ وَّ اَبَارِيْقَ١ۙ۬ وَ كَاْسٍ مِّنْ مَّعِيْنٍۙ۰۰۱۸لَّا يُصَدَّعُوْنَ عَنْهَا وَ لَا يُنْزِفُوْنَۙ۰۰۱۹﴾ (الواقعہ:17-19) ’’ان کے پاس سدا رہنے والے لڑکے آتے جاتے ہوں گے، ساغر اور صراحیاں اور شراب کے جاری چشمے سے چھلکتے جام لیے ہوئے، وہ اس سے نہ سر درد میں مبتلا ہوں گے اور نہ مدہوش ہوں گے۔‘‘\nاللہ سبحانہ وتعالیٰ نے جنت کی شراب کو ان آفتوں سے پاک کر دیا ہے جو دنیا کی شراب میں سر درد، پیٹ درد اور عقل زائل کر دینے کی صورت میں ہیں۔\nارشاد باری تعالیٰ ہے:﴿يُطَافُ عَلَيْهِمْ بِكَاْسٍ مِّنْ مَّعِيْنٍۭۙ۰۰۴۵﴾ ’’ان پر جاری چشمے سے شراب (طہور) کا بھرا جام پھرایا جائے گا۔‘‘ یعنی ایسی رواں دواں نہروں سے شراب پلائی جائے گی جن میں شراب کے ختم ہو جانے کا انہیں کوئی اندیشہ نہ ہو گا۔ امام مالک رحمہ اللہ نے زید بن اسلم رحمہ اللہ سے روایت کیا ہے کہ جنت کی شراب کا رنگ سفید، خوبصورت اور چمک دار ہو گا، دنیا کی شراب کی طرح وہ سرخ یا سیاہ یا پیلی یا میلی اور گندی رنگت کی نہ ہو گی کہ جس سے طبع سلیم نفرت کرتی ہو۔ ﴿لَذَّةٍ لِّلشّٰرِبِيْنَۚۖ۰۰۴۶﴾ ’’اور پینے والوں کے لیے (سراسر) لذت ہو گی۔‘‘ یعنی اس کے رنگ کی طرح اس کا ذائقہ بھی پاکیزہ ہو گا اور ذائقے کا پاکیزہ ہونا اس بات کی دلیل ہے کہ اس کی خوشبو بھی پاک ہے جبکہ دنیا کی شراب ان تمام باتوں میں اس کے برعکس ہوتی ہے، ﴿لَا فِيْهَا غَوْلٌ ﴾ ’’نہ اس سے سر چکرائے گا۔‘‘ ابن عباس رضی اللہ عنہما، مجاہد، قتادہ اور ابن زید رحمہ اللہ کا قول ہے کہ غول سے مراد پیٹ کا درد ہے۔ (تفسیر الطبری:64/23) جیسا کہ دنیا کی شراب سے اس کی کثرت مائیات کی وجہ سے پیٹ میں قولنج پیدا ہو جاتا ہے۔ ﴿وَّ لَا هُمْ عَنْهَا يُنْزَفُوْنَ۰۰۴۷﴾ ’’اور نہ وہ اس سے مدہوش ہوں گے۔‘‘ مجاہد رحمہ اللہ کہتے ہیں کہ اس کے پینے سے ان کی عقلیں زائل نہیں ہوں گی۔ (تفسیر الطبری:66/23) اور اسی طرح ابن عباس رضی اللہ عنہما، محمد بن کعب، حسن، عطاء بن ابو مسلم خراسانی اور سدّی رحمہ اللہ وغیرہ کا بھی یہی قول ہے۔ (تفسیر الطبری: 66/23) ضحاک رحمہ اللہ نے ابن عباس رضی اللہ عنہما سے روایت کیا ہے کہ شراب میں چار خرابیاں ہوتی ہیں: (1) اس سے نشہ پیدا ہوتا ہے۔ (2) سر درد ہوتا ہے۔ (3) قے آتی ہے (4) اور پیشاب زیادہ آتا ہے۔ (تفسیر ابن أبی حاتم:3211/10) اللہ تعالیٰ نے جنت کی شراب کا ذکر فرماتے ہوئے اسے ان تمام خرابیوں سے پاک قرار دیا ہے، جیسا کہ سورۂ صافات میں ذکر فرمایا ہے۔\nارشاد باری تعالیٰ ہے: ﴿وَ عِنْدَهُمْ قٰصِرٰتُ الطَّرْفِ ﴾ ’’اور ان کے پاس نیچی نگاہوں والی (حوریں) ہوں گی۔‘‘ یعنی وہ پاک دامن ہوں گی اور اپنے شوہروں کے علاوہ اور کسی کی طرف نہیں دیکھیں گی۔ ابن عباس رضی اللہ عنہما، مجاہد، زید بن اسلم، قتادہ اور سدی رحمہ اللہ وغیرہ کا بھی یہی قول ہے۔ (تفسیر الطبری:67/23) ﴿عِيْنٌۙ۰۰۴۸﴾ ’’اور بڑی بڑی آنکھو والی (غزال چشم۔)‘‘ یعنی وہ خوبصورت آنکھوں والی ہوں گی اور یہ بھی کہا گیا ہے کہ ان کی آنکھیں بڑی بڑی ہوں گی اور خوبصورت آنکھوں سے مراد بھی یہی ہے، یعنی ان کی آنکھیں بڑی بڑی اور خوبصورت ہوں گی، اللہ تعالیٰ نے ان کی آنکھوں کے حسن اور عفت کی تعریف فرمائی ہے: ﴿وَ عِنْدَهُمْ قٰصِرٰتُ الطَّرْفِ عِيْنٌۙ۰۰۴۸﴾ ’’اور ان کے پاس نیچی نگاہوں والی (اور) بڑی بڑی آنکھوں والی (حوریں) ہوں گی۔‘‘\nنیز فرمایا:﴿كَاَنَّهُنَّ بَيْضٌ مَّكْنُوْنٌ۰۰۴۹﴾ ’’گویا وہ پردوں میں چھپائے ہوئے (شتر مرغ کے) انڈے ہیں۔‘‘ اللہ تعالیٰ نے ان کے جسموں کی لطافت کو خوبصورت رنگ کے ساتھ بیان فرمایا ہے۔ علی بن ابو طلحہ رحمہ اللہ نے ابن عباس رضی اللہ عنہما سے روایت کیا ہے کہ ﴿كَاَنَّهُنَّ بَيْضٌ مَّكْنُوْنٌ۰۰۴۹﴾ کے معنی یہ ہیں گویا وہ محفوظ موتی ہیں۔ (تفسیر الطبری:68/23) حسن رحمہ اللہ نے اس کے معنی یہ بیان کیے ہیں کہ وہ ہاتھوں کے لمس سے بھی محفوظ ہیں۔ (تفسیر ابن أبی حاتم: 3212/10) سدّی رحمہ اللہ نے کہا کہ وہ ایسے ہیں جیسے اپنے گھونسلے میں انڈا محفوظ ہوتا ہے۔ (تفسیر ابن أبی حاتم:3212/10) سعید بن جبیر رحمہ اللہ کہتے ہیں کہ اس سے مراد انڈے کے اندر والا حصہ ہے۔ (تفسیر الطبری:68/23) اور عطاء خراسانی رحمہ اللہ کہتے ہیں کہ اس سے مراد وہ باریک جھلی ہے جو اوپر کے چھلکے اور مغز انڈا کے درمیان ہوتی ہے۔ (تفسیر ابن أبی حاتم: 3212/10) سدّی رحمہ اللہ کہتے ہیں کہ وہ اس انڈے کی طرح ہوں گی جس کا اوپر سے چھلکا اتار دیا گیا ہو۔ (تفسیر ابن أبی حاتم: 3212/10) ابن جریر رحمہ اللہ نے بھی اس قول کو پسند کیا ہے کہ اوپر کے چھلکے کو تو پرندے کے پروں، گھونسلے کے تنکوں اور لوگوں کے ہاتھوں نے چھوا ہوتا ہے جبکہ انڈے کے اندر کے حصے کو کسی چیز نے چھوا نہیں ہوتا۔ (تفسیر الطبری:69/23) وَاللہُ أَعْلَمُ.\nمذکورہ بالا عذاب ِ نار سے اللہ تعالیٰ نے اپنے ان مومن بندوں کو مستثنیٰ قرار دیا ہے جو صرف اسی کی عبادت کرتے ہیں۔ انہیں ان کا رب جنت میں داخل کردےگا اور بے شمار نعمتوں سے نوازے گا، ان نعمتوں میں سے یہ بھی ہے کہ انہیں بغیر انقطاع کے صبح و شام عمدہ اور پاکیزہ روزی ملتی رہے گی، جیسا کہ اللہ تعالیٰ نے سورۂ مریم آیت (62)میں فرمایاہے:﴿وَ لَهُمْ رِزْقُهُمْ فِيْهَا بُكْرَةً وَّ عَشِيًّا۰۰۶۲﴾ ’’وہاں انہیں صبح و شام روزی ملتی رہے گی۔‘‘\nمفسرین لکھتے ہیں کہ آیت (42)میں ’’فواکہ‘‘سے اس طرف اشارہ مقصود ہے کہ اہل جنت کا کھانا پینا بھوک اور پیاس کی وجہ سے نہیں، بلکہ محض لذت حاصل کرنے کے لیے ہوگا اور وہاں وہ بہت ہی باعزت زندگی گزاریں گے اور وہ آمنے سامنے آرام دہ کرسیوں پر بیٹھے ہوں گے اور انہیں شراب کی جاری نہروں سے پیالے بھر کر پیش کیے جائیں گے، ایسی شراب جس سے انہیں نہ کوئی بیماری ہوگی نہ ہی دردِ سر اور نہ اس کے زیر اثر ان کی عقل ہی ماری جائے گی۔"],[6130,"§فواکہ کیسے پھل ہیں؟\nیہاں فواکہ کا لفظ آیا ہے اور فواکہ ایسے پھلوں کو کہتے ہیں جن سے لذت و سرور حاصل ہو۔ (مقاییس اللغۃ) اور اس لفظ کا اطلاق عموماً خشک پھلوں پر ہوتا ہے۔ اس سے بھی یہ معلوم ہوتا ہے کہ اہل جنت کو جور زق دیاجائے گا وہ بطورغذا نہیں بلکہ لذت کے حصول کے لیے دیاجائے گا۔"],[6131,"§کأسکالغوی مفہوم\nکَأسٌ کالفظ صرف شراب سے بھرے ہوئے پیالہ یا گلاس کے لیے مستعمل ہے، جسے ہماری زبان میں جام یا ساغر کہتے ہیں۔ دودھ یاپانی سے بھرے ہوئے پیالہ کو کَأسٌ نہیں کہہ سکتے اور اگر یہ پیالہ خالی ہو اور شیشے کا ہو تو اسے قَدْحٌ کہتے ہیں، چمڑے کا ہو تو عَلْبۃٌ اور مٹی کا ہو تو مُوْکِنْ اور مَعِیْنٌ دراصل صاف شفاف نتھرے، خوش ذائقہ، میٹھے اور ٹھنڈے پانی کو کہتے ہیں۔ مگرجب معین کے ساتھ کأس کا لفظ آئے تو معین سے مراد یہی صفات رکھنے والی شراب ہوگی۔ کیونکہ کأس کا لفظ شراب کے بھرے ہوئے پیالہ کے لیے ہی مخصوص ہے۔"],[6132,"§شراب کے تین نقصان اور ایک فائدہ\nدنیا میں جو شراب تیار کی جاتی ہے۔ وہ کچھ مخصوص پھلوں یا غلوں کو گلا سڑا کر اور ان میں خمیر اُٹھا کر بنائی جاتی ہے۔ اور ایسی شراب میں تین نقص ہوتے ہیں اور ایک فائدہ ہوتا ہے۔ نقص یہ ہیں کہ وہ پینے کے بعد کڑوی محسوس ہوتی ہے، دوسرا یہ کہ وہ سر کو چڑھ جاتا ہے جس سے بعض دفعہ سر چکرانے لگتا ہے اور تیسرا یہ کہ اسی وجہ سے انسان بہکی بہکی باتیں کرنے لگتا ہے۔ اور نشہ زیادہ چڑھ جائے تو کئی طرح کے غلط کام بھی کر بیٹھتا ہے۔ شراب کے ساتھ اول فول بکنا اور فحاشی کے کام عموماً لازم وملزوم بن جاتے ہیں اور اس کا فائدہ یہ ہے کہ پینے والے کو وقتی طور پر کچھ سرور حاصل ہوتاہے۔ جنت میں اہل جنت کو جو شراب دی جائے گی وہ مندرجہ بالا تمام نقائص سے تو پاک ہوگی۔ مگر اپنی لطافت، پاکیزگی اور لذت کے لحاظ سے دنیا کی شرابوں سے بہت افضل ہوگی۔"],[6133,"§قصر کا لغوی مفہوم\nقَصَرَ کے معنی کسی چیز کی لمبائی یا اس کی انتہا کو نہ پہنچنا۔ نیز کم کرنا، چھوٹا کرنا، یا کوئی کام جتنا کرنا تھا اتنا نہ کرنا اور قصر الطوف یعنی جتنی دور نگاہ جا سکتی ہے اتنی دور تک نہ دیکھنا، یا نظر بھر کر نہ دیکھنا بلکہ صرف نیچے نظر رکھنا۔ اللہ تعالیٰ نے اہل جنت کی اشیاء خوردو نوش کے بعد ان کی عائلی زندگی کا ذکر فرمایا کہ انہیں عورتیں ایسی دی جائیں گی جو اپنے خاوندوں کے سوا کسی کو دیکھنے کی بھی روادار نہ ہوں گی۔\nعین بمعنی آنکھ اور عیناء اس عورت کوکہتے ہیں جس کی آنکھیں بڑی اور موٹی موٹی ہوں اور عیناء کی جمع عین آتی ہے۔ موٹی آنکھیں چہرے کی خوبصورتی کو دوبالا کر دیتی ہیں۔ گویا اہل جنت کی عورتوں میں دوسری صفت یہ ہوگی کہ ان کی آنکھیں موٹی اور خوبصورت ہوں گی۔"],[6134,"§بیض کی مختلف تعبیریں\nاس آیت کی کئی تعبیریں کی گئی ہیں۔ ایک یہ کہ ان کی رنگت سفید ہوگی یعنی گورے رنگ کی ہوں گی اور جلد بالکل بے داغ ہوگی۔ دوسری یہ کہ یہاں انڈوں سے مراد شتر مرغ کے انڈے ہیں جو نہایت خوش رنگ ہوتے ہیں۔ اور اس تعبیر کی تائید اس آیت سے بھی ہوجاتی ہے :﴿كَاَنَّهُنَّ الْيَاقُوْتُ وَ الْمَرْجَانُۚ۰۰۵۸﴾ (الرحمٰن:58) ’’یعنی اہل جنت کی عورتیں یا قوت اور مرجان کی طرح ہوں گی ‘‘ اور تیسری تعبیروہ ہے جو ماثور ہے۔ چنانچہ سیدہ اُم سلمہ رضی اللہ عنہا نے جب اسی آیت کی تفسیر رسول اللہ صلی اللہ علیہ وسلم سے پوچھی تو آپ صلی اللہ علیہ وسلم نے فرمایا:کہ ان کی نرمی و نزاکت اس جھلی جیسی ہوگی جو انڈے کے چھلکے اور اس کے گودے کے درمیان ہوتی ہے۔ (ابن جریر) اسی تعبیر کو معتبر سمجھ کر ترجمہ اس کے مطابق درج کیا گیا ہے۔ یہ اہل جنت کی عورتوں کی تیسری صفت ہوئی۔\nیعنی تم ہمارے پیغمبر کو شاعر اور مجنون کہتے ہو، جب کہ واقعہ یہ ہے کہ وہ جو کچھ لایا اور پیش کر رہا ہے، وہ سچ ہے اور وہی چیز ہے جو اس سے قبل تمام انبیاء بھی پیش کرتے رہے ہیں۔ کیا یہ کام کسی دیوانے کا یا کسی شاعر کے تخیلات کا نتیجہ ہو سکتا ہے؟\nلیکن اللہ کے بندے جو مخلص اور موحد ہیں وہ ہرگز عذاب کو نہ چکھیں گے اور جب ان کا محاسبہ کیا جائے گا تو محاسبہ میں مناقشہ کی کیفیت نہ ہوگی ان سے کرید کر نہ پوچھاجائے گا معمول کا اندازہ ہوگا ہرگز حیرت دامن کو نہ تھامے گی بلکہ اللہ ان کی برائیوں کو محو کردیں گے اور ایک نیکی کا بدلہ دس گنا سے لے کر ساٹھ گنا تک کردیا جائے گا۔\nاُولٰٓىِٕكَ لَهُمْ رِزْقٌ مَّعْلُوْمٌ: یہ پاکباز بہترین اخلاق کے لوگ انھیں جنت میں صبح شام بہترین خوراک سے نوازا جائے گا ارشاد ربانی ہے ﴿وَ لَهُمْ رِزْقُهُمْ فِيْهَا بُكْرَةً وَّ عَشِيًّا۰۰۶۲﴾ (مریم:62)صبح شام کے کھانوں میں جو کھانے ان کے سامنے پیش کیے جائیں گے ان کھانوں کا بظاہر منظر دل کش ہوگا کھانے لذت کے لحاظ سے دل کشی کا سامان مہیا کریں گے جب کہ ان کی مہلک بھی بہت عمدہ ہوگی صبح شام کے کھانوں میں فروٹ بھی متنوع قسم کے ان کے سامنے از خود ان کی خواہش کے مطابق آئیں گے بہرحال وہ جنت میں نہایت معزز حیثیت میں شاداں وفرحان رہیں گے۔ذہن نشین کریں کہ پھلوں کا خصوصیت کے ساتھ ذکر کیا گیا ہے مقصود یہ کہ وہ پھلوں کے تناول سے عمدہ قسم کی لذات سے شاد کام ہوں گے باغات میں، تَنَـعُّم کی زندگی بسر کریں گے ایسے پلنگوں پر جلوہ افروز ہوں گے جن پر موتیوں اور یاقوت کا جڑاؤ کیا گیا ہوگا ان کے پلنگ آٹومیٹیکلی (Automatically Bed) ان کی جانب گردش کریں گے ہرگز کسی سوئچ کو دبانے کی ضرورت نہ ہوگی وہ جنت میں ایک دوسرے کے سامنے جلوہ افروز ہوں گے کسی کی پشت کسی دوسرے کے چہرے کی جانب نہیں ہوگی سب آمنے سامنے ہوں گے۔ مطعومات کے تذکرہ کے بعد مشروبات کا ذکر ہو رہا ہے کہ جنت میں خدام شراب کی جاری نہروں سے شراب چھلکتے ہوئے جام جنتیوں کی خدمت میں پیش کریں گے جب کہ شراب کا رنگ سفید ہوگا جیسا کہ چشمہ کے پانی کا رنگ ہوتا ہے اس کو نوش کرنے والاجنتی ناقابل بیان لذت محسوس کرے گا نام کے لحاظ سے شراب جب کہ اس کا رنگ دودھ سے زیادہ سفید ہوگا، شراب کے پینے سے عقل بدستور موجود رہے گی اس میں ہرگز فتور لاحق نہیں ہوگا نہ اس کے استعمال سے سر میں درد ہوگا اور نہ پیٹ میں تکلیف ہوگی شراب کے پینے سے مزاج کا نہ صرف یہ کہ تکدر ختم ہوگا بلکہ کسی قسم کا جوش اور اعصابی تناؤ کا ظہور نہ ہوگا۔\nوَ عِنْدَهُمْ قٰصِرٰتُ الطَّرْفِ : اور ان کی خدمت کے لیے ایسی خوبصورت پاکدامن عورتیں ہوں گی جنہوں نے اپنی نظر کو صرف اپنے خاوندوں تک محدود رکھا ہوگا اور پاکدامنی کے ساتھ ساتھ ان کے دیگر حسن و جمال کے ساتھ ان کی آنکھیں موٹی ہوں گی اور ان کی آنکھوں کا سیاہ حصہ نہایت سیاہ اور سفید حصہ مبالغہ کی حدتک نہایت سفید پرکشش ہوگا گویا کہ وہ عورتیں ان موتیوں کی طرح ان کا جسم چمک رہا ہوگا جنہیں سیپ میں چھپا کررکھا ہوا ہے، نیز المکنون سے مقصود یہ بھی ہوسکتا ہے کہ ان کا جسم ہاتھوں کے چھونے سے محفوظ رہا کہ جہاں ان کا حسن و جمال حیرت افزا ہوگا وہاں انھیں موتیوں کی طرح سیپ میں رکھا گیا ہوگا ان کے جسم تک نہ کسی کا ہاتھ پہنچا ہوگا نہ انھیں کسی آنکھ نے کبھی دیکھا ہوگا ان کے جسم میں نعومت، لطافت اور رقت کاملاجلا، انداز ہوگا گویا کہ وہ نظروں سے اوجھل اس قدر پردوں میں ہوں گی کہ ان تک نہ کسی کے ہاتھ کو رسائی ہوگی اور نہ کسی کی ان پر نظر پڑی ہوئی گی۔\nابوحیان رحمہ اللہ کی وضاحت: اللہ تعالیٰ ان آیات میں اوّلا ان کی خوراک کا ذکر کیا ہے جس کے تناول سے جسم لطف اندوز ہوتا ہے اس کے بعد انھیں کس قدر عزت اور اکرام سے ٹھہرایا گیا ہے اس پر انسان کا نفس مطمئنہ خوشی سے جھومنے لگتا ہے پھر انھیں کہاں بطور مہمان نوازی کے رکھا گیا ہے تو اس کا جواب نہایت واضح ہے کہ انھیں ایسی جنات میں فروکش کیا جائے گا جہاں آرام و اطمینان کے ساتھ انھیں اپنی خواہش کے مطابق کھانے پینے اور لذت اندوزی کے لیے سامان فراہم کیے جائیں گے مزید برآں تنہائی کا ہرگز کسی لمحہ بھی خدشہ نہیں ہوگا ہمیشہ ہمیشہ میلے کا سماں رہے گا آمنے سامنے خودورمتحرک پلنگوں پر مسرت اور انس ومودت کے جانفراجھونکوں کے ساتھ شادم کام رہیں گے۔\nفَاَقْبَلَ بَعْضُهُمْ عَلٰى بَعْضٍ يَّتَسَآءَلُوْنَ۰۰۵۰ قَالَ قَآىِٕلٌ مِّنْهُمْ اِنِّيْ كَانَ لِيْ\nقَرِيْنٌۙ۰۰۵۱ يَّقُوْلُ اَىِٕنَّكَ لَمِنَ الْمُصَدِّقِيْنَ۠۰۰۵۲ ءَاِذَا مِتْنَا وَ كُنَّا تُرَابًا وَّ عِظَامًا\nءَاِنَّا لَمَدِيْنُوْنَ۰۰۵۳ قَالَ هَلْ اَنْتُمْ مُّطَّلِعُوْنَ۰۰۵۴ فَاطَّلَعَ فَرَاٰهُ فِيْ سَوَآءِ\nالْجَحِيْمِ۰۰۵۵ قَالَ تَاللّٰهِ اِنْ كِدْتَّ لَتُرْدِيْنِۙ۰۰۵۶ وَ لَوْ لَا نِعْمَةُ رَبِّيْ لَكُنْتُ مِنَ\nالْمُحْضَرِيْنَ۰۰۵۷ اَفَمَا نَحْنُ بِمَيِّتِيْنَۙ۰۰۵۸ اِلَّا مَوْتَتَنَا الْاُوْلٰى وَ مَا نَحْنُ\nبِمُعَذَّبِيْنَ۰۰۵۹ اِنَّ هٰذَا لَهُوَ الْفَوْزُ الْعَظِيْمُ۰۰۶۰ لِمِثْلِ هٰذَا فَلْيَعْمَلِ الْعٰمِلُوْنَ۰۰۶۱\nوہ (جنتی) ایک دوسرے کی طرف متوجہ ہو کر باہم پوچھیں گے } ان میں سے ایک کہنے والا کہے گا : بے شک میں (اوردنیا میں) میرا ایک ہم نشین تھا \\ جو کہتا تھا:کیا بھلا تو بھی (قیامت کی) تصدیق کرنے والوں میں سے ہے ؟| کیا جب ہم مرجائیں گے اور مٹی اور ہڈیاں ہو جائیں گے تو کیا واقعی ہم (اُٹھا کر) بدلہ دیے جائیں گے ؟ رحمہ اللہ وہ (جنتی ساتھیوں سے) کہے گا: کیا تم (جہنم میں) جھانک کر دیکھو گے؟ رحمہ اللہ پھر وہ جھانکے گا تو اسے جہنم کے درمیان میں دیکھے گا وہ (اس سے) کہے گا : اللہ کی قسم ! یقیناً قریب تھا کہ تو مجھے ہلاک کر ڈالتا اور اگر میرے رب کا فضل نہ ہوتا تو میں ضرور حاضر کیے ہوئوں (مجرموں) میں سے ہوتا (جنتی ساتھیوں سے کہے گا :)تو کیا پس (اب) ہم مرنے والے نہیں اپنے پہلی بار مرنے کے سوا اور نہ ہمیں\nعذاب ہی ہوگا بلاشبہ یہ تو بہت بڑی کامیابی ہے عمل کرنے والوں کو تو ایسی ہی (کامیابی) کے لیے عمل کرنے چاہئیں"],[6135,"§اہل جنت کی باہمی میل ملاقات\nاللہ تعالیٰ نے اہل جنت کے بارے میں فرمایا ہے کہ وہ ایک دوسرے کی طرف رخ کر کے باہم احوال پوچھیں گے کہ وہ دنیا میں کس حال میں تھے اور کن شدائد ومشکلات کو برداشت کرتے تھے۔ جب وہ اپنے تختوں پر جلوہ افروز ہو کر ایک دوسرے کے سامنے بیٹھیں گے اور شراب کے دور چل رہے ہوں گے تو وہ آپس میں اسی طرح کی باتیں کریں گے اور خدام ان کے پاس انواع واقسام کے کھانے پینے اور پہننے کی ایسی نفیس ترین چیزیں جلدی جلدی لا رہے ہوں گے جنہیں نہ کسی آنکھ نے دیکھا ہو گا، نہ کسی کان نے سنا ہو گا اور نہ کسی انسان کے دل میں ان کا وہم وگمان گزرا ہو گا۔ ﴿قَالَ قَآىِٕلٌ مِّنْهُمْ اِنِّيْ كَانَ لِيْ قَرِيْنٌۙ۰۰۵۱﴾ ’’ایک کہنے والا ان میں سے کہے گا کہ بے شک میں (اور دنیا میں) میرا ایک ہم نشیں تھا۔‘‘ عوفی رحمہ اللہ نے ابن عباس رضی اللہ عنہما سے روایت کیا ہے کہ اس سے مراد وہ مشرک آدمی ہے جو دنیا میں اہل ایمان میں سے کسی کا ساتھی تھا۔ (تفسیر الطبری:70/23) ﴿يَّقُوْلُ اَىِٕنَّكَ لَمِنَ الْمُصَدِّقِيْنَ۠۰۰۵۲﴾ ’’(جو) کہتا تھا کہ بھلا تو بھی (قیامت کی) تصدیق کرنے والوں میں سے ہے؟‘‘ یعنی کیا تم بھی بعث، دوبارہ جی اٹھنے، حساب اور جزا وسزا کو مانتے ہو؟ وہ یہ بات تعجب، تکذیب، کفر، سرکشی اور بعید از قیاس سمجھتے ہوئے کہتا تھا، ﴿ءَاِذَا مِتْنَا وَ كُنَّا تُرَابًا وَّ عِظَامًا ءَاِنَّا لَمَدِيْنُوْنَ۰۰۵۳﴾ ’’بھلا جب ہم مر جائیں گے اور مٹی اور ہڈیاں ہو جائیں گے تو کیا واقعی ہم (اٹھا کر) بدلہ دیے جائیں گے؟‘‘\nمجاہد اور سدّی رحمہم اللہ نے کہا ہے کہ کیا ہم سے اس وقت حساب لیا جائے گا۔ (تفسیر الطبری:71/23) ابن عباس رضی اللہ عنہما اور محمد بن کعب قرظی رحمہ اللہ نے اس کے یہ معنی بیان کیے ہیں: کیا ہمیں ہمارے اعمال کا بدلہ ملے گا؟ (تفسیر الطبری71/23) اور دونوں معنی ہی صحیح ہیں۔\nارشاد باری تعالیٰ ہے: ﴿قَالَ هَلْ اَنْتُمْ مُّطَّلِعُوْنَ۰۰۵۴﴾ ’’(پھر) کہے گا کہ بھلا تم (اسے) جھانک کر دیکھنا چاہتے ہو؟‘‘ یعنی جنتی جنت کے اپنے ساتھیوں اور ہم نشینوں سے یہ کہے گا، ﴿فَاطَّلَعَ فَرَاٰهُ فِيْ سَوَآءِ الْجَحِيْمِ۰۰۵۵﴾ ’’پھر (اتنے میں) وہ (خود) جھانکے گا تو اسے وسط دوزخ میں دیکھے گا۔‘‘ ابن عباس رضی اللہ عنہما، سعید بن جبیر، خلیدعصری، قتادہ، سدی اور عطاء خراسانی رحمہ اللہ نے کہا ہے کہ اسے جہنم کے وسط میں دیکھے گا۔ (تفسیر الطبری:72/23،73) اور حسن بصری رحمہ اللہ فرماتے ہیں کہ جہنم کے وسط میں اسے دیکھے گا گویا وہ آگ کا انگارا ہے جو جل رہا ہے۔ (تفسیر الطبری:72/23) ﴿قَالَ تَاللّٰهِ اِنْ كِدْتَّ لَتُرْدِيْنِۙ۰۰۵۶﴾ ’’وہ کہے گا: اللہ کی قسم! تو مجھے ہلاک کر ہی چکا تھا۔‘‘ مومن اس کافر سے مخاطب ہو کر کہے گا کہ اگر میں تمہاری بات مان لیتا تو تم نے مجھے بھی ہلاک کر دینا تھا۔ ﴿وَ لَوْ لَا نِعْمَةُ رَبِّيْ لَكُنْتُ مِنَ الْمُحْضَرِيْنَ۰۰۵۷﴾ ’’اور اگر میرے پروردگار کی مہربانی نہ ہوتی تو میں بھی ان میں ہوتا جو (عذاب میں) حاضر کیے گئے ہیں۔‘‘ یعنی اگر مجھ پر اللہ تعالیٰ کا فضل وکرم نہ ہوتا تو میں بھی آج جہنم کے وسط میں اسی جگہ ہوتا جہاں تو ہے اور تیری طرح آج میں بھی عذاب میں حاضر کیا جاتا لیکن اللہ تعالیٰ نے مجھ پر اپنا فضل وکرم فرمایا اور مجھے ایمان کی ہدایت بخشی اور اس نے اپنی توحید کی طرف میری راہنمائی فرمائی: ﴿وَ مَا كُنَّا لِنَهْتَدِيَ لَوْ لَاۤ اَنْ هَدٰىنَا اللّٰهُ١ۚ ﴾ (الأعراف:43) ’’اور اگر یہ بات نہ ہوتی کہ اللہ نے ہمیں ہدایت دی تو ہم ہرگز ایسے نہ تھے کہ ہدایت پاتے۔‘‘\nارشاد باری تعالیٰ ہے: ﴿اَفَمَا نَحْنُ بِمَيِّتِيْنَۙ۰۰۵۸اِلَّا مَوْتَتَنَا الْاُوْلٰى وَ مَا نَحْنُ بِمُعَذَّبِيْنَ۰۰۵۹﴾ ’’تو کیا پس (اب) ہم مرنے والے نہیں، اپنے پہلی بار مرنے کے سوا اور نہ ہمیں عذاب ہی ہو گا۔‘‘ یہ مومن کی بات ہے جو خود پر رشک کر رہا ہو گا کیونکہ اللہ تعالیٰ نے اسے جنت میں ہمیشہ کی زندگی عطا کی ہو گی اور اپنے اس عزت کے گھر میں اقامت عطا فرمائی ہو گی جس میں موت ہو گی نہ عذاب، اس پر وہ خوشی کا اظہار کرے گا، اس لیے اللہ عزوجل نے فرمایا: ﴿اِنَّ هٰذَا لَهُوَ الْفَوْزُ الْعَظِيْمُ۰۰۶۰﴾ ’’یقیناً یہی تو بہت بڑی کامیابی ہے۔‘‘\nحسن بصری رحمہ اللہ فرماتے ہیں کہ انہوں نے اس حقیقت کو معلوم کر لیا تھا کہ موت ہر نعمت کو ختم کر دے گی، اس لیے وہ کہیں گے: ﴿اَفَمَا نَحْنُ بِمَيِّتِيْنَۙ۰۰۵۸اِلَّا مَوْتَتَنَا الْاُوْلٰى وَ مَا نَحْنُ بِمُعَذَّبِيْنَ۰۰۵۹﴾ ’’تو کیا پس (اب) ہم مرنے والے نہیں، اپنے پہلی بار مرنے کے سوا اور نہ ہمیں عذاب ہی ہو گا۔‘‘ کہا جائے گا: نہیں، تو وہ کہیں گے: ﴿اِنَّ هٰذَا لَهُوَ الْفَوْزُ الْعَظِيْمُ۰۰۶۰ ﴾ ’’بے شک یہ تو بہت بڑی کامیابی ہے۔‘‘ ارشاد باری تعالیٰ: ﴿لِمِثْلِ هٰذَا فَلْيَعْمَلِ الْعٰمِلُوْنَ۰۰۶۱﴾ ’’ایسی ہی کامیابی کے لیے عمل کرنے والوں کو عمل کرنے چاہئیں۔‘‘ کے بارے میں ابن جریر رحمہ اللہ نے فرمایا ہے کہ یہ اللہ تعالیٰ کا کلام ہے اور اس کے معنی یہ ہیں کہ اس طرح کی نعمتوں اور اس طرح کی کامیابیوں کے لیے عمل کرنے والوں کو چاہیے کہ دنیا میں ایسے عمل کریں تا کہ آخرت میں وہ ان سے شاد کام ہوں۔(تفسیر الطبری:74/23)"],[6136,"§دو اسرائیلیوں کا قصہ\nعلمائے تفسیر نے یہاں بنی اسرائیل کے ان دو آدمیوں کا قصہ ذکر کیا ہے جو آپس میں شریک تھے اور ان کا قصہ اس آیت کریمہ کے عموم میں داخل ہے، ابو جعفر بن جریر رحمہ اللہ نے فرات بن ثعلبہ بہرانی رحمہ اللہ سے ارشاد باری تعالیٰ: ﴿اِنِّيْ كَانَ لِيْ قَرِيْنٌۙ۰۰۵۱﴾ ’’بے شک میں (اور دنیا میں) میرا ایک ہم نشین تھا۔‘‘ کے بارے میں روایت کیا ہے کہ بنی اسرائیل کے دو آدمی آپس میں شریک تھے، ان کے پاس آٹھ ہزار دینار جمع ہو گئے، ان میں سے ایک شخص کام جانتا تھا اور دوسرا کام نہیں جانتا تھا، جو شخص کام جانتا تھا اس نے دوسرے سے کہا کہ تو کام نہیں جانتا، اس لیے میں چاہتا ہوں کہ تجھے چھوڑ دوں اور ہم اپنا سرمایہ آپس میں تقسیم کر لیں، پس اس نے سرمایہ تقسیم کر کے اسے چھوڑ دیا، پھر اس شخص نے ایک ہزار دینار کا ایک گھر خریدا جو کسی بادشاہ کی ملکیت تھا اور وہ فوت ہو گیا تھا، پھر اس نے اپنے ساتھی کو بلا کر گھر دکھایا اور کہا کہ یہ کیسا گھر ہے، میں نے اسے ایک ہزار دینار میں خریدا ہے؟ اس نے جواب دیا کہ یہ بہت خوبصورت گھر ہے اور جب وہ اس گھر سے باہر نکل گیا تو اس نے دعا کی کہ اے اللہ! میرے اس ساتھی نے ایک ہزار دینار میں یہ گھر خریدا ہے اور میں تجھ سے جنت کے ایک گھر کا سوال کرتا ہوں اور پھر اس نے ایک ہزار دینار صدقہ کر دیا، پھر اس کے ساتھی نے کچھ عرصہ بعد ایک ہزار دینار خرچ کر کے ایک عورت سے شادی کی اور اسے کھانے پر بلایا جب وہ آیا تو اس نے اسے بتایا کہ میں نے ایک ہزار دینار خرچ کر کے اس عورت سے شادی کی ہے، اس نے کہا: بہت خوب اور جب وہ اس کے پاس سے گیا تو کہا کہ اے میرے رب! میرے ساتھی نے ایک ہزار دینار خرچ کر کے شادی کی ہے اور میں تجھ سے حورعین کا سوال کرتا ہوں اور پھر اس نے ایک ہزار دینار صدقہ کر دیا۔\nپھر کچھ عرصے بعد اس نے دو ہزار دینار کے ساتھ دو باغ خریدے اور پھر اپنے ساتھی کو بلایا اور اسے یہ دو باغ دکھائے، اس نے کہا: یہ بہت خوبصورت باغ ہیں۔ اور جب اس کے پاس سے گیا تو اس نے دعا کی کہ اے میرے رب! میرے اس ساتھی نے دو ہزار کے دو باغ خریدے ہیں اور میں تجھ سے جنت میں دو باغوں کا سوال کرتا ہوں، یہ کہہ کر اس نے دو ہزار دینار صدقہ کر دیے، پھر فرشتہ آیا اور اس نے دونوں کی روح کو قبض کر لیا اور اس صدقہ کرنے والے کو اس نے ایک بے حد خوشنما اور خوبصورت گھر میں داخل کر دیا، جس میں ایک ایسی حسین وجمیل عورت تھی جب وہ نیچے کی طرف دیکھتی تو اس کے نیچے جو کچھ ہوتا اس کے حسن کی وجہ سے چمک اٹھتا اور پھر اسے ایسے دو باغوں میں داخل کر دیا جن کی نعمتوں کو اللہ تعالیٰ ہی جانتا ہے، یہ دیکھ کر اس شخص نے کہا کہ یہ صورتحال اس شخص کے حالات سے کس قدر مطابقت رکھتی ہے جس کا یہ معاملہ تھا تو فرشتہ اس سے کہے گا کہ اس کے لیے بس وہی کچھ تھا اور تیرے لیے یہ گھر، یہ دو باغ اور یہ عورت ہے، وہ کہے گا کہ میرا ایک ساتھی تھا ﴿يَّقُوْلُ اَىِٕنَّكَ لَمِنَ الْمُصَدِّقِيْنَ۠۰۰۵۲﴾ ’’(جو) کہتا تھا کہ بھلا تو بھی (قیامت کی) تصدیق کرنے والوں میں سے ؟‘‘ اسے بتایا جائے گا کہ وہ تو جہنم میں ہے تو﴿قَالَ هَلْ اَنْتُمْ مُّطَّلِعُوْنَ۰۰۵۴فَاطَّلَعَ فَرَاٰهُ فِيْ سَوَآءِ الْجَحِيْمِ۰۰۵۵﴾ ’’وہ کہے گا: بھلا تم (اسے) جھانک کر دیکھنا چاہتے ہو؟ اتنے میں وہ (خود) جھانکے گا تو اسے وسط دوزخ میں دیکھے گا۔‘‘ اور اس وقت وہ کہے گا: ﴿قَالَ تَاللّٰهِ اِنْ كِدْتَّ لَتُرْدِيْنِۙ۰۰۵۶وَ لَوْ لَا نِعْمَةُ رَبِّيْ لَكُنْتُ مِنَ الْمُحْضَرِيْنَ۰۰۵۷﴾ ’’اللہ کی قسم! تو تو مجھے ہلاک کر ہی چکا تھا اور اگر میرے پروردگار کی مہربانی نہ ہوتی تو میں بھی ان میں ہوتا جو (عذاب میں) حاضر کیے گئے ہیں۔‘‘ (تفسیر الطبری:70/23،71)\nاہل جنت آمنے سامنے کرسیوں پر بیٹھ کر شراب پئیں گے، باتیں کریں گے اور دنیا میں ان پر جو بیتی تھی ایک دوسرے سے بیان کریں گے۔ خدام جنت ان کے سامنے آجا رہے ہوں گے اور انواع و اقسام کی ایسی نعمتیں پیش کر رہے ہوں گے جنہیں دنیا میں نہ کسی آنکھ نے دیکھا تھا، نہ کسی کان نے سنا تھا، اورنہ کسی دل میں ان کا خیال تک گزرا تھا۔\nاُس وقت اُن میں سے ایک جنتی کہے گا کہ ایک مشرک میرے ساتھ دنیا میں کبھی کبھار بیٹھتا تھا، وہ آخرت کی تکذیب کرتے ہوئے کہتا تھا کہ کیا تم اس بات کو مانتے ہو کہ ہم جب مر کر گل سڑ جائیں گے اور مٹی میں مل جائیں گے، تو ہم دوبارہ زندہ کیے جائیں گے اور ہمیں ہمارے اعمال کا بدلہ چکایا جائے گا؟! تو آج ہمارے رب نے اپنا وعدہ سچ کر دکھایا ہے، ہمیں جنت میں داخل کر دیاہے اور میرے اس ساتھی کو جہنم میں دھکیل دیا ہے۔ کیا تم لوگ اُسے جہنم میں دیکھنا چاہتے ہو؟ پھر وہ جنتی جہنم میں جھانکے گا، تو اُسے بیچ جہنم میں دیکھے گا اور حیرت و دہشت کے ملے جلے جذبات سے متاثر ہو کر اس جہنمی کوپکارے گا اور اس سے کہے گا کہ اللہ کی قسم ! قریب تھا کہ تم مجھے بھی جہنم میں پہنچا دیتے اور اگر مجھ پر اللہ کا فضل و کرم نہ ہوتا تو آج میں بھی تمہارے ساتھ جہنم کی کھائی میں نظر آتا۔"],[6137,"§عالم آخرت میں سمعی اور بصری قوتوں میں بے پناہ اضافہ\nاس آیت سے معلوم ہوتا ہے کہ عالم آخرت میں جو سمعی و بصری قوتیں عطا کی جائیں گی وہ اس دنیا کے مقابلہ میں بہت زیادہ ہوں گی۔ ہم اس دنیا میں بھی ہزاروں میل دو ر بیٹھے آدمیوں کی آوازیں سنتے اور انہیں دیکھتے ہیں۔مگر صرف ان لوگوں کو جو ٹیلی ویژن سنٹر میں ہوتے ہیں اور براڈکاسٹ کرتے ہیں۔ عالم آخرت میں ہر شخص دوسرے سے گفتگو کرسکے گا اور اسے دیکھ بھی سکے گا۔ خواہ یہ فاصلہ ہزاروں بلکہ لاکھوں میل کا ہو۔ اور کسی آلہ کے واسطہ کے بغیر سن اور دیکھ سکے گا۔"],[6138,"§افضل اعمال کون سے ہیں؟\nدرج ذیل دو احادیث میں ان اعمال کا ذکر ہے جنہیں رسول اللہ صلی اللہ علیہ وسلم نے افضل الاعمال بتایاہے :\n(1)سیدنا ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ صحابہ رضی اللہ عنہم نے آپ صلی اللہ علیہ وسلم سے پوچھا :’’کون سا عمل افضل ہے ؟ فرمایا:’’اللہ اور اس کے رسول صلی اللہ علیہ وسلم پر ایمان لانا۔‘‘ صحابہ نے پوچھا :’’پھر کون سا ؟‘‘ فرمایا:’’اللہ کی راہ میں جہاد کرنا ‘‘ پھر پوچھا :’’اس کے بعد کون سا؟‘‘ فرمایا:’’ حج مبرور‘‘ (صحیح بخاری)\n(2)سیدنا عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ میں نے آپ صلی اللہ علیہ وسلم سے پوچھا :’’اللہ تعالیٰ کو کون ساکام سب سے زیادہ پسند ہے؟‘‘ فرمایا:’’نماز کو اپنے وقت پر ادا کرنا ‘‘ میں نے پوچھا ’’پھر کون سا کام ؟‘‘ فرمایا:’’ماں باپ سے اچھا سلوک کرنا ‘‘ میں نے پوچھا :’’ پھر کون سا ؟‘‘ فرمایا:’’ اللہ کی راہ میں جہاد کرنا ‘‘ آپ صلی اللہ علیہ وسلم نے یہ تین باتیں بیان کیں اگر میں اور پوچھتا تو آپ صلی اللہ علیہ وسلم اور زیادہ بیان فرماتے ‘‘(صحیح بخاری)\nجہنمیوں کا حشر دیکھ کر جنتی کے دل میں رشک کا جذبہ مزید بیدار ہو جائے گا اور کہے گا کہ ہمیں جو جنت کی زندگی اور اس کی نعمتیں ملی ہیں، کیا یہ دائمی نہیں؟ اور اب ہمیں موت آنے والی نہیں ہے؟ یہ استفہام تقریری ہے یعنی اب یہ زندگیاں دائمی ہیں، جنتی ہمیشہ جنت میں اور جہنمی ہمیشہ جہنم میں رہیں گے، نہ انہیں موت آئے گی کہ جہنم کے عذاب سے چھوٹ جائیں اور نہ ہمیں، کہ جنت کی نعمتوں سے محروم ہو جائیں، جس طرح حدیث میں آتا ہے کہ موت کو ایک مینڈھے کی شکل میں جنت اور دوزخ کے درمیان لا کر ذبح کر دیا جائے گا کہ اب کسی کو موت نہیں آئے گی۔\nفَاَقْبَلَ بَعْضُهُمْ عَلٰى بَعْضٍ يَّتَسَآءَلُوْنَ: جنتی لوگ جب آپس میں مل جل کربیٹھیں گے وہ دنیوی واقعات کو بھی دہرائیں گے اور ایمان کے نتائج سے مسر ت محسوس کریں گے ان میں سے ایک شخص کہے گا، میرا ایک ساتھی تھا جو قیامت کا انکار کیا کرتا تھا وہ مجھے کہا کرتا تھا تعجب ہے کہ تو قیامت کے واقع ہونے کو درست قرار دیتا ہے کیا جب ہم موت سے ہم کنار ہوں گے اور ہم مٹی کے ذرات کی شکل میں ہوں گے اور ہماری ہڈیاں بوسیدہ ہوجائیں گی تو ہمارا محاسبہ ہوگا اور ہمیں ہمارے اعمال کی جزا سزا سے گزارا جائے گا اس کی یہ گفتگو بطورتعجب کے ہوگی چنانچہ یہ ایماندار شخص جنت میں اپنے بھائیوں سے کہے گا کیا تم دوزخ کا ملاحظہ کرنا چاہتے ہو کہ تاکہ ہم اپنے ساتھی کا حال معلوم کریں ؟ چنانچہ وہ اپنے ساتھی کو دیکھے گا کہ وہ دوزخ کے درمیان میں گرا ہوا ہے دوزخ میں جل رہا ہے تو ایماندار شخص اپنے ساتھی مخاطب کرکے کہے گا اللہ کی قسم قریب تھا کہ تو مجھے گمراہ کردیتا ہے اور مجھے تباہ و برباد کردیتا ہے اگر مجھ پر میرے پروردگار کا فضل و کرم نہ ہوتا کہ اس نے مجھے ایمان پر استقامت عطا کی تو میں دوزخ میں تیرے ساتھ جکڑا ہواہوتا اور مجھے دوزخ میں عذاب میں گرفتار کیا جاتا۔\nاس کے بعد کافر شخص استہزاء کی کیفیت میں مخاطب ہو کررہے گا، جیسا کہ دنیوی زندگی میں استہزاء کرتے ہوئے کہا کرتا تھا کیا توا سے اپنے اسی اعتقاد پر قائم نہیں ہے کہ ہم پر ایک ہی بار موت طاری ہوگی اور موت کے بعد اٹھایا جانا جزاوحساب وغیرہ نہیں ہے، دراصل یہ مزاحیہ انداز ہے لیکن ساتھ ساتھ ناقدانہ انداز دردانگیز بھی ہے اس صورت میں کافر ساتھی سے کچھ تکلیف میں کمی کا انداز بھی ہے اس کی نعمت کا تذکرہ ہے کہ جس نعمت سے جنتی شخص مالا مال ہواوہ تو بہت بڑی کامیابی ہے اس قسم کے عمدہ بدلہ کے لیے ضروری ہے کہ عمل کرنے والے عمل کرتے رہیں اور اس میں کوشاں رہیں گے جب کہ دنیوی سامان کے حصول کے لیے جس نے جلدی ہی ختم ہوجانا ہے مبالغہ کی حدتک کوشش نہ کی جائے جس میں مسلسل آلام و مصائب سے گزرنا پڑے۔\nاَذٰلِكَ خَيْرٌ نُّزُلًا اَمْ شَجَرَةُ الزَّقُّوْمِ۰۰۶۲ اِنَّا جَعَلْنٰهَا فِتْنَةً لِّلظّٰلِمِيْنَ۰۰۶۳ اِنَّهَا\nشَجَرَةٌ تَخْرُجُ فِيْۤ اَصْلِ الْجَحِيْمِۙ۰۰۶۴ طَلْعُهَا كَاَنَّهٗ رُءُوْسُ الشَّيٰطِيْنِ۰۰۶۵ فَاِنَّهُمْ\nلَاٰكِلُوْنَ مِنْهَا فَمَالِـُٔوْنَ مِنْهَا الْبُطُوْنَؕ۰۰۶۶ ثُمَّ اِنَّ لَهُمْ عَلَيْهَا لَشَوْبًا مِّنْ\nحَمِيْمٍۚ۰۰۶۷ ثُمَّ اِنَّ مَرْجِعَهُمْ لَاۡاِلَى الْجَحِيْمِ۰۰۶۸ اِنَّهُمْ اَلْفَوْا اٰبَآءَهُمْ\nضَآلِّيْنَۙ۰۰۶۹ فَهُمْ عَلٰۤى اٰثٰرِهِمْ يُهْرَعُوْنَ۰۰۷۰\nکیا یہ مہمانی بہتر ہے یا (دوزخ میں) تھوہر کا درخت؟; بلاشبہ ہم نے اسے ظالموںکے لیے آزمائش بنایا ہے ' بے شک وہ ایک درخت ہے جو دوزخ کی تہ میں اُگتا ہے اس کا پھل گویا کہ وہ شیطانوں کے سر ہیں رحمہم اللہ تو بلاشبہ وہ (دوزخی) اس میں سے کھائیں گے، پھر اس سے (اپنے) پیٹ بھریں گے پھر اس پر بے شک ان کے لیے (پینے کو) گرم کھولتے پانی کا آمیزہ ہوگا پھر یقیناً ان کی واپسی بھڑکتی آگ کی طرف ہوگی بلاشبہ انھوں نے اپنے باپ دادوں کو گمراہ پایا تو وہ انھی کے نقش\nقدم پر دوڑے جاتے ہیں"],[6139,"§تھوہر کا درخت\nاللہ تعالیٰ نے بیان فرمایا ہے کہ کیا جنت کی کھانے پینے اور نکاح کی یہ نعمتیں اور دیگر لذتیں بہتر ضیافت اور عطیہ ہیں ﴿اَمْ شَجَرَةُ الزَّقُّوْمِ۰۰۶۲﴾ ’’یا تھوہر کا درخت؟‘‘ جو جہنم میں ہو گا اور اس سے مراد جنس درخت ہے جسے زقوم (تھوہر) کہا جاتا ہے جیسا کہ ارشاد باری تعالیٰ ہے: ﴿وَ شَجَرَةً تَخْرُجُ مِنْ طُوْرِ سَيْنَآءَ تَنْۢبُتُ بِالدُّهْنِ وَ صِبْغٍ لِّلْاٰكِلِيْنَ۰۰۲۰﴾ (المؤمنون:20) ’’اور درخت بھی (ہم ہی نے پیدا کیا) جو طور سینا میں پیدا ہوتا ہے۔ (زیتون کا درخت) کہ کھانے والوں کے لیے روغن اور سالن اگاتا ہے۔‘‘\nارشاد باری تعالیٰ ہے: ﴿اِنَّهَا شَجَرَةٌ تَخْرُجُ فِيْۤ اَصْلِ الْجَحِيْمِۙ۰۰۶۴﴾ ’’بے شک وہ ایک درخت ہے جو جہنم کی تہ میں اگتا ہے۔‘‘ یعنی اس کے اگنے کی اصل جگہ جہنم کا پیندہ ہے، ﴿طَلْعُهَا كَاَنَّهٗ رُءُوْسُ الشَّيٰطِيْنِ۰۰۶۵﴾ ’’اس کا پھل گویا کہ وہ شیطانوں کے سر ہیں۔‘‘ اس سے اس کے قبیح المنظر اور اس کے قابل نفرت ہونے کی طرف اشارہ ہے اور اسے شیطانوں کے سروں کے ساتھ تشبیہ دی گئی گو وہ مخاطب لوگوں کے ہاں معروف نہ تھے لیکن یہ بات تو دلوں میں بیٹھی ہوئی ہے کہ شیطانوں کی شکلیں بہت بری ہیں۔ ﴿فَاِنَّهُمْ لَاٰكِلُوْنَ مِنْهَا فَمَالِـُٔوْنَ مِنْهَا الْبُطُوْنَؕ۰۰۶۶﴾ ’’پس بے شک وہ (دوزخی) اسی میں سے کھائیں گے، پھر اسی سے (اپنے) پیٹ بھریں گے۔‘‘\nاللہ تعالیٰ نے ذکر فرمایا ہے کہ وہ اس درخت سے کھائیں گے،حالانکہ اس جیسا بد ترین اور بد شکل کوئی درخت نہ ہو گا اور اس پر مستزاد یہ کہ اس کا ذائقہ، اس کی بدبو اور اس کی طبیعت بد ترین ہو گی لیکن وہ اسے کھانے کے لیے مجبور ہوں گے کیونکہ اس کے سوا یا اس جیسی اور کسی چیز کے سوا ان کو کھانے کے لیے کچھ نہیں ملے گا، جیسا کہ اللہ تعالیٰ نے فرمایا ہے: ﴿لَيْسَ لَهُمْ طَعَامٌ اِلَّا مِنْ ضَرِيْعٍۙ۰۰۶لَّا يُسْمِنُ وَ لَا يُغْنِيْ مِنْ جُوْعٍؕ۰۰۷﴾ (الغاشیة:6،7) ’’اور خاردار جھاڑی کے سوا ان کے لیے کوئی کھانا نہیں ہو گا جو نہ موٹا کرے گا نہ بھوک مٹائے گا۔‘‘\nارشاد باری تعالیٰ ہے: ﴿ثُمَّ اِنَّ لَهُمْ عَلَيْهَا لَشَوْبًا مِّنْ حَمِيْمٍۚ۰۰۶۷﴾ ’’پھر بلاشبہ اس پر ان (کے پینے) کے لیے کھولتے پانی کا آمیزہ ہو گا۔‘‘ ابن عباس رضی اللہ عنہما نے فرمایا ہے کہ تھوہر کھانے کے بعد پینے کے لیے انہیں گرم پانی دیا جائے گا۔ (تفسیر الطبری:77/23) اور آپ رضی اللہ عنہما سے ایک دوسری روایت میں ہے کہ تھوہر میں انہیں گرم پانی ملا کر دیا جائے گا۔ (تفسیر الطبری:77/23) آپ رضی اللہ عنہما کے علاوہ دیگر ائمہ تفسیر نے فرمایا ہے کہ ان کے لیے گرم پانی میں لہو اور پیپ کو ملایا جائے گا، پیپ بھی وہ جو جہنمیوں کی شرمگاہوں اور آنکھوں سے بہ رہی ہو گی۔ (تفسیر الطبری:77/23)\nامام ابن ابو حاتم رحمہ اللہ نے سعید بن جبیر رحمہ اللہ سے روایت کیا ہے کہ جب دوزخیوں کو بھوک لگے گی تو وہ تھوہر کے درخت کو کھائیں گے جس سے ان کے چہروں کی کھالیں جھلس جائیں گی، ان کے پاس سے اگر کوئی گزرے گا تو وہ ان کے چہروں کی بدبو سے انہیں پہچانے گا، پھر ان پر پیاس طاری کر دی جائے گی، وہ پانی طلب کریں گے تو انہیں ایسا پانی دیا جائے گا جو پگھلے ہوئے تانبے کی طرح ہو گا اور انتہائی گرم، جب وہ اسے اپنے مونہوں کے قریب کریں گے تو اس کی شدید حرارت کی وجہ سے ان کے چہروں کا گوشت بھن جائے گا، کھالیں جل جائیں گی اور پیٹ کی انتڑیاں باہر نکل آئیں گی اور جب وہ چلیں گے تو ان کی انتڑیاں بہ رہی ہوں گی اور کھالیں گر رہی ہوں گی اور پھر انہیں لوہے کے ہتھوڑوں کے ساتھ مارا جائے گا جس سے ایک ایک عضو ٹوٹ جائے گا اور وہ موت مانگنے لگیں گے۔ (تفسیر ابن أبی حاتم:3217/10)\nارشاد باری تعالیٰ ہے: ﴿ثُمَّ اِنَّ مَرْجِعَهُمْ لَاۡاِلَى الْجَحِيْمِ۰۰۶۸﴾ ’’یقیناً ان کو دوزخ کی طرف لوٹایا جائے گا۔‘‘ یعنی پھر اس فیصلے کے بعد ان سب کو شعلے مارتی ہوئی آگ، بھڑکتے ہوئے جہنم اور دہکتے ہوئے دوزخ کی طرف لوٹایا جائے گا، کبھی ایک قسم کی آگ میں جلایا جائے گا اور کبھی دوسری قسم کی آگ میں جیسا کہ اللہ جل شانہٗ نے فرمایا ہے: ﴿يَطُوْفُوْنَ بَيْنَهَا وَ بَيْنَ حَمِيْمٍ اٰنٍۚ۰۰۴۴﴾ (الرحمٰن:44) ’’وہ دوزخ اور کھولتے ہوئے گرم پانی کے درمیان گھومتے پھریں گے۔‘‘\nاسی طرح امام قتادہ نے بھی اس آیت کی تفسیر بیان کرتے ہوئے سورۂ رحمٰن کی اس آیت کی تلاوت کی تھی۔ (تفسیر الطبری:77/23) اور یہ بہت خوبصورت اور قوی تفسیر ہے، سدی نے کہا ہے کہ سیدنا عبداللہ رضی اللہ عنہ کی قراءت کے مطابق یہ آیت اس طرح ہے: (ثُمَّ إِنَّ مُنْقَلَبَھُمْ لَإِلَی الْجَحِیمِ)(ابن کثیر میں مَقِیلَھُمْ کے الفاظ ہیں جبکہ ابن جریر میں مُنْقَلَبَھُمْ ہیں) اور سیّدنا عبداللہ بن مسعود رضی اللہ عنہ فرمایا کرتے تھے کہ اس ذات کی قسم! جس کے ہاتھ میں میری جان ہے کہ قیامت کے دن ابھی نصف النہار کا وقت بھی نہیں ہو گا کہ اہل جنت، جنت میں قیلولہ کریں گے اور اہل دوزخ، دوزخ میں، پھر انہوں نے اس آیت کو پڑھا: ﴿اَصْحٰبُ الْجَنَّةِ يَوْمَىِٕذٍ خَيْرٌ مُّسْتَقَرًّا وَّ اَحْسَنُ مَقِيْلًا۰۰۲۴﴾ (الفرقان:24) ’’اس دن اہل جنت باعتبار ٹھکانے کے بہت بہتر ہوں گے اور باعتبار آرام گاہ کے بہت اچھے ہوں گے۔‘‘ (تفسیر الطبری:77/23،78) ارشاد باری تعالیٰ ہے: ﴿اِنَّهُمْ اَلْفَوْا اٰبَآءَهُمْ ضَآلِّيْنَۙ۰۰۶۹﴾ ’’یقیناً انہوں نے اپنے باپ دادا کو گمراہ پایا۔‘‘ یعنی ہم نے انہیں یہ سزا اس لیے دی کہ انہوں نے اپنے آباء و اجداد کو گمراہ پایا تو بغیر کسی دلیل وبرہان کے ان کی پیروی شروع کر دی، اس لیے فرمایا: ﴿فَهُمْ عَلٰۤى اٰثٰرِهِمْ يُهْرَعُوْنَ۰۰۷۰﴾ ’’سو وہ انہی کے پیچھے دوڑے چلے جاتے ہیں۔‘‘ مجاہد کہتے ہیں کہ اس سے مراد ایسی چال ہے جو تیز دوڑنے کے مشابہ ہو۔ (تفسیر ابن أبی حاتم: 3217/10) اور سعید بن جبیر کہتے ہیں کہ ان کے پیچھے وہ بھی بے وقوف بنے جاتے ہیں۔\nاہل جنت کی خوش بختیوں کا ذکر کرنے کے بعد، اللہ تعالیٰ نے اہل جہنم کی بدبختیوں کا ذکر کیا ہے، کہ اوپر اہل جنت کے لیے جن نعمتوں کا ذکرہواہے وہ بہترین نعمت ہے، یابدترین کڑوے زقوم کا درخت، جسے ہم نے ظالم کفارِ قریش کی آزمائش کا سبب بنا دیا ہے، جو کہتے ہیں کہ بھلا یہ بھی عقل میں آنے والی بات ہے کہ کوئی ایسا بھی درخت ہے جو آگ میں پیدا ہوتاہے۔ اللہ تعالیٰ نے فرمایا: ہاں زقوم ایسا درخت ہے جو جہنم کی تہہ میں پیدا ہوتا ہے، جس کی شاخیں آگ میں لہلہاتی ہیں اور جس کے پھل شیطانوں کے سروں کے مانند بڑے اور قبیح المنظر ہوتے ہیں، جہنمی جب بھوک کی شدت سے تڑپیں گے تو اپنے آگے سوائے شجر زقوم کے کچھ بھی کھانے کے لیے نہ پائیں گے، ناچاراسی کو کھائیں گے اور اپنے پیٹ بھریں گے۔ اور کھانے کے بعد جب انہیں پیاس لگے گی تو پینے کے لیے پیپ اور گندگی ملا ہوا شدید گرم پانی ملے گا،جو ان کی آنتوں کوکاٹ کر باہر نکال دےگا۔ اور ہر حال میں ان کا ٹھکانا جہنم ہی ہوگا، جہاں بھڑکتی آگ کے شعلے ان کے ناتواں جسموں کو جلاتے رہیں گے، جیسا کہ سورۃ الرحمٰن آیات (43/44)میں آیا ہے : ﴿هٰذِهٖ جَهَنَّمُ الَّتِيْ يُكَذِّبُ بِهَا الْمُجْرِمُوْنَۘ۰۰۴۳يَطُوْفُوْنَ بَيْنَهَا وَ بَيْنَ حَمِيْمٍ اٰنٍۚ۰۰۴۴﴾ ’’یہ ہے وہ جہنم جسے مجرم جھوٹا جانتے تھے، مجرمین اس کے اور کھولتے ہوئے گرم پانی کے درمیان چکر کھائیں گے۔‘‘\nاللہ تعالیٰ نے فرمایا کہ اہل جہنم مذکورہ بالا عذابِ شدید سے اس لیے دو چار ہوئے کہ انہوں نے اپنے آباء و اجداد کو راہِ ہدایت سے بھٹکا ہوا پایا تو انہی کے پیچھے ہو لیے اور شرک و کفر اور ضلالت وگمراہی میں ان کی تقلید کرنے لگے۔ صاحب محاسن التنزیل لکھتے ہیں کہ آیات (69/70) میں یہ بات بیان کی گئی ہے کہ مشرکین مکہ نے بغیر غور وفکر اور محض اندھی تقلید کی بنیاد پر اپنے باپ دادوں کی پیروی میں تیزی کی۔ فخر الدین رازی رحمہ اللہ لکھتے ہیں کہ اگر قرآنِ کریم میں اس ایک آیت کے سواذمِّ تقلید میں کوئی دوسری آیت نہ ہوتی تو بھی کافی ہوتی۔"],[6140,"§اللہ کی محیر العقول مخلوق\nجب یہ آیت نازل ہوئی تو کافروں نے خوب مذاق اُڑایا کہ بھلاآگ میں درخت کیسے پیدا ہو سکتا ہے یا برقرار رہ سکتا ہے۔ اوریہ اعتراض محض ان کی کم عقلی اور کم عملی کی بنا پر تھا۔ کیونکہ اللہ تعالیٰ کی تخلیق کی صورتیں بعض دفعہ بڑی نرالی اور حیران کن ہوتی ہیں۔ مثلاً جس فصل کے اوپر سے پانی گزر جائے۔ خواہ وہ پانی سیلاب کا ہو اور زیادہ بارش کا وہ فصل برباد ہو جاتی ہے۔ پودوں اور درختوں کا بھی یہی حال ہے مگر سمندر کی تہہ میں درخت اُگتے ہیں۔ پھر ایسی جمادات بھی ہیں جو درختوں کی طرح پھلتی پھولتی ہیں۔ اور ان کی نشوونما پانی میں ہوتی ہے۔ جیسے مرجان۔ اور یہاں تو آگ میں صرف تھوہر کا درخت یعنی نباتات اُگنے کا ذکر ہے۔ جبکہ آگ میں جاندار بھی پیدا ہو سکتے ہیں۔ جیسے آگ کا کیڑا سمندر جو آگ میں ہی زندہ رہ سکتا ہے۔"],[6141,"§شیطان کے مختلف مفہوم\nشیطان دراصل ہر بدروح کو کہتے ہیں جو اپنی سرکشی اور نافرمانی کی بنا پر حق سے دور ہو چکا ہو۔ اور جنوں میں سے جو خبیث، موذی اور بدکردار قسم کے جن ہوں انہیں ہی شیطان کہاجاتا ہے۔ پھر اس کا اطلاق ہر ایسی صفات رکھنے والی چیز پر ہونے لگا۔ خواہ وہ جن ہو یا انسان ہو یا کوئی جانور ہو۔ اور سانپ کو اس کی ایذا ہی کی وجہ سے شیطان کہتے ہیں۔ (منجد) اور اس معنی کی تائید اس حدیث سے بھی ہوتی ہے کہ جب تم گھر میں کوئی سانپ دیکھو تو اسے مارنے سے پہلے یہ کہہ دو کہ اگر وہ کوئی جن یا شیطان ہے تو چلا جائے۔ اگر پھر بھی نہ جائے تو اسے مار ڈالو۔ (صحیح مسلم،صحیح بخاری)\nگویا اس آیت میں شیطان کے سر سے مراد سانپوں کے سریاناگ پھن ہیں۔ اور اس پودے کے شگوفے ایسے ہی ہوں گے اور یہ بھی ممکن ہے یہ تشبیہ محض بدصورتی کی بنا پر ہو جیسے ہم اپنی زبان میں بعض ان دیکھی چیزوں سے تشبیہ دے دیتے ہیں۔ جیسے وہ عورت ایسی خوبصورت ہے جیسے پری یا وہ ایسی بدصورت ہے جیسے چڑیل یا بھوتنی یا ڈائن۔ حالانکہ پَری، چڑیل، بھوتنی یا ڈائن کو کسی نے بھی دیکھا نہیں ہوتا۔\nآزمائش، اس لیے کہ اس کا پھل کھانا بجائے خود ایک بہت بڑی آزمائش ہے۔ بعض نے اسے اس اعتبار سے آزمائش کہا کہ اس کے وجود کا انہوں نے انکار کیا کہ جہنم میں جب ہر طرف آگ ہی آگ ہوگی تو وہاں درخت کس طرح موجود رہ سکتا ہے؟ یہاں ظالمین سے مراد وہ اہل جہنم ہیں جن پر جہنم واجب ہوگی۔\nکیا اُخروی زندگی میں جنت کی نعمتیں بطور ضیافت اور عطیہ کے بہتر ہیں یا تھوہر کا درخت جو دوزخ میں ہے جس سے ہم دوزخیوں کو خوراک دی جائے گی ؟ ذہن نشین کریں کہ استفہام میں کفار کو ڈانٹ پلانے کا تکلیف دہ انداز ہے اور یہ حقیقت ہے کہ ہم نے تھوہر کے درخت کی مہمانی سے کفار کو فتنے میں مبتلا کردیا ہے چنانچہ جب کفار نے تھوہر کے درخت کا تذکرہ سناتو انھوں نے اعتراض کیا دوزخ میں درخت کا وجود تو ممکن ہی نہیں اس لیے کہ آگ تو دوزخ کو جلاکربھسم کردیتی ہے مزید برآں ابوجہل نے اس پر پھبتی کسی اور کہا ساتھیو تم جانتے ہو کہ زقوم کیا چیز ہے ؟ کسی بھول میں نہ رہنا اس سے مقصود تو کھجور اور مکھن ہے جو بطور مہمان نوازی کے پیش کی جائے گی، بعدازاں وہ اسے ان کے پاس لایا اور ان سے کہا یہ زقوم ہے اس کو تناول کروتعجب ہے کہ محمد صلی اللہ علیہ وسلم تمہیں اس سے خوف زدہ کررہا تھا۔\nاِنَّهَا شَجَرَةٌ تَخْرُجُ فِيْۤ اَصْلِ الْجَحِيْمِ: یہ درخت دوزخ کی گہرائی میں اُگتا ہے بعدازاں اس کی شاخیں پھیلتی رہتی ہیں اس کا پھل چونکہ انتہادرجہ کا قبیح ہے تو اس کی شیطان کے سروں کے ساتھ تشبیہ دی گئی ہے۔"],[6142,"§علامہ ابن کثیر رحمہ اللہ کی وضاحت\nتھوہر کے درخت کے خوشوں کو شیطانوں کے سروں سے تشبیہ دینے میں ان کی قباحت کی جانب اشارہ ہے کہ اگرچہ اہل عرب کے ہاں یہ درخت ہرگز مشہور نہ تھا جب کہ تشبیہ سے مقصود لوگوں کے ذہن میں اس حقیقت کو داخل کرنا تھا، کہ شیاطین کی شکل و صورت میں بنیادی طور پر قباحت موجود ہوتی ہے چنانچہ بھوک کی شدت اور المناکی کے سبب مجبور ہوں گے کہ اس کے تناول سے بھوک کو دور کریں اور ان کے پیٹ اس سے بھرجائیں چنانچہ جنت کے رزق کے مقابلہ میں دوزخیوں کا یہی پھل اور کھانا ہوگا اور اگر تھوہر درخت کا ایک قطرہ دنیا میں موجود سمندروں میں گرادیا جائے توروئے زمین کے سبھی لوگوں کی معیشت کے سامان میں بگاڑ رونما ہوجائے وہ تناول کے لائق نہ رہے گی۔\nتو غور کریں ان لوگوں کا کیا حال ہوگا جن کی معیشت کا نظام تھوہر کے درخت کے ساتھ وابستہ ہوگا، بعدازاں جب وہ اس کے تناول کرنے سے سیراب ہوجائیں گے اور انہیں پانی کی ضرورت پیش آئے گی تو انھیں شدید گرم پانی کے ساتھ تھوہر درخت کے ملغوبہ کو ملادیا جائے گا تاکہ انھیں پہلے سے زیادہ شدید قسم کے عذاب میں مبتلا کیا جائے گا بعدازاں انھیں دوزخ کے نچلے طبقہ کے جانب لوٹادیا جائے گا جہاں انھیں پینے کے لیے گرم پانی دیا جائے گا ایک وضاحت کے مطابق تھوہر اور گرم پانی کو ان کے سامنے بطور مہمان نوازی کے پیش کیا جائے گا (نعوذ باللہ من ذلک) بلاشبہ وہ لوگ ہیں جنہوں نے اپنے آباء و اجداد کو گمراہی میں پایاتو انھوں نے خود کو ان کی پیروی میں چلایا بلکہ وہ بلادلیل ان کے نقوش پر دوڑ لگاتے رہے۔\nوَ لَقَدْ ضَلَّ قَبْلَهُمْ اَكْثَرُ الْاَوَّلِيْنَۙ۰۰۷۱ وَ لَقَدْ اَرْسَلْنَا فِيْهِمْ مُّنْذِرِيْنَ۰۰۷۲ فَانْظُرْ\nكَيْفَ كَانَ عَاقِبَةُ الْمُنْذَرِيْنَۙ۰۰۷۳ اِلَّا عِبَادَ اللّٰهِ الْمُخْلَصِيْنَؒ۰۰۷۴ وَ لَقَدْ نَادٰىنَا نُوْحٌ\nفَلَنِعْمَ الْمُجِيْبُوْنَٞۖ۰۰۷۵ وَ نَجَّيْنٰهُ وَ اَهْلَهٗ مِنَ الْكَرْبِ الْعَظِيْمِٞۖ۰۰۷۶ وَ جَعَلْنَا ذُرِّيَّتَهٗ\nهُمُ الْبٰقِيْنَٞۖ۰۰۷۷ وَ تَرَكْنَا عَلَيْهِ فِي الْاٰخِرِيْنَٞۖ۰۰۷۸ سَلٰمٌ عَلٰى نُوْحٍ فِي الْعٰلَمِيْنَ۰۰۷۹ اِنَّا\nكَذٰلِكَ نَجْزِي الْمُحْسِنِيْنَ۰۰۸۰ اِنَّهٗ مِنْ عِبَادِنَا الْمُؤْمِنِيْنَ۰۰۸۱ ثُمَّ اَغْرَقْنَا\nالْاٰخَرِيْنَ۰۰۸۲\nاور بلاشبہ ان سے پہلے بہت سے اگلے لوگ گمراہ ہوئے اور یقیناً ہم نے ان میں ڈرانے والے بھیجے تھے پھر دیکھ لیجئے ان کا انجام کیسا ہوا؟ جنھیں ڈرایا گیا تھا ؟: سوائے اللہ کے چنے ہوئے بندوں کے \" اور یقیناً نوح نے ہمیں پکارا تھا تو (دیکھو!) ہم کیا ہی خوب جواب دینے والے ہیں اور ہم نے اسے اور اس کے اہل کو بہت بڑی پریشانی سے نجات دی اورہم نے اس کی اولاد کو باقی رہنے والے بنا دیا اور ہم نے اس (کے ذکر خیر) کو پیچھے آنے والوں میں باقی رکھا نوح پر تمام جہانوں میں سلام ہو بلاشبہ ہم نیکوکاروں کو اسی طرح جزا دیتے ہیںبے شک وہ ہمارے مومن بندوں میں سے تھا\nپھر ہم نے دوسروں کو غرق کر دیا,"],[6143,"§ڈرائے گئے لوگوں کا انجام؟\nاللہ جل شانہٗ نے بیان فرمایا ہے کہ سابقہ امتوں میں سے اکثر لوگ گمراہ تھے اور اللہ تعالیٰ کے ساتھ وہ دیگر معبودان باطلہ کی بھی عبادت کرتے تھے۔ اللہ تعالیٰ نے ذکر فرمایا ہے کہ اس نے ان امتوں میں رسول بھیجے جو اللہ تعالیٰ کے ساتھ کفر کرنے والوں کو اور اس کے ساتھ غیروں کی پوجا کرنے والوں کو اس (اللہ تعالیٰ) کی گرفت، اس کی سزا اور اس کے عذاب سے ڈراتے تھے مگر ان لوگوں نے سرکشی کا مظاہرہ کرتے ہوئے اپنے رسولوں کی مخالفت اور تکذیب کی تو اللہ تعالیٰ نے ان تکذیب کرنے والوں کو تباہ وبرباد کر دیا اور مومنوں کو نجات دی اور انہیں فتح ونصرت سے سر فراز فرمایا، اسی لیے ارشاد ربانی ہے: ﴿فَانْظُرْ كَيْفَ كَانَ عَاقِبَةُ الْمُنْذَرِيْنَۙ۰۰۷۳اِلَّا عِبَادَ اللّٰهِ الْمُخْلَصِيْنَؒ۰۰۷۴﴾ ’’سو دیکھ لیں جنہیں ڈرایا گیا تھا ان کا انجام کیسا ہوا؟ سوائے اللہ کے چنے ہوئے بندوں کے۔‘‘"],[6144,"§سیّدنا نوح علیہ السلام اور آپ کی قوم کا ذکر\nاللہ تعالیٰ نے پہلے یہ ذکر فرمایا کہ پہلے اکثر لوگ راہِ نجات سے بھٹک گئے تھے اور اب اس نے اس کی تفصیل کو بیان کرنا شروع فرمایا ہے اور اسی سلسلے میں سب سے پہلے نوح علیہ السلام کا ذکر فرمایا کہ ان کی قوم نے اس کی تکذیب کی اور طویل مدت تک رہنے کے باوجود ان میں سے بہت تھوڑے لوگ ایمان لائے تھے، آپ ان میں ساڑھے نو سو سال تک رہے تھے، جب ان کی مخالفت طویل اور تکذیب بہت شدید ہو گئی اور انہوں نے اپنی قوم کو جب بھی اللہ تعالیٰ کے دین کی طرف دعوت دی ان کی نفرت میں اضافہ ہی ہوتا گیا۔ ﴿فَدَعَا رَبَّهٗۤ اَنِّيْ مَغْلُوْبٌ فَانْتَصِرْ۰۰۱۰﴾ (القمر:10) ’’تو انہوں نے اپنے پروردگار سے دعا کی کہ بے شک میں بے بس ہوں، (اب) تو ہی ان سے بدلہ لے۔‘‘ تو نوح علیہ السلام کے قوم سے ناراض ہونے کی وجہ سے اللہ تعالیٰ بھی ان کی قوم سے شدید ناراض ہو گیا، اسی لیے اس نے فرمایا ہے: ﴿وَلَقَدْ نَادٰىنَا نُوْحٌ فَلَنِعْمَ الْمُجِيْبُوْنَٞۖ۰۰۷۵﴾ ’’اور البتہ تحقیق نوح نے ہمیں پکارا سو (دیکھ لو کہ ہم دعا کو) کیسے اچھے قبول کرنے والے ہیں۔‘‘ یعنی ہم نے ان کی دعا کو بہت اچھے طریقے سے قبول کیا ﴿وَ نَجَّيْنٰهُ وَ اَهْلَهٗ مِنَ الْكَرْبِ الْعَظِيْمِٞۖ۰۰۷۶﴾ ’’اور ہم نے اسے اور اس کے گھر والوں کو بہت بڑی پریشانی سے نجات دی۔‘‘ بڑی پریشانی سے مراد تکذیب اور اذیت ہے۔ ﴿وَجَعَلْنَا ذُرِّيَّتَهٗ هُمُ الْبٰقِيْنَٞۖ۰۰۷۷﴾ ’’اور ہم نے اس کی اولاد کو ہی باقی رہنے والے کر دیا۔‘‘\nعلی بن ابو طلحہ رحمہ اللہ نے ابن عباس رضی اللہ عنہما سے روایت کیا ہے کہ نوح علیہ السلام کی اولاد ہی باقی رہی تھی۔ (تفسیر الطبری: 80/23) اور سعید بن ابو عروبہ رحمہ اللہ نے قتادہ رحمہ اللہ سے اس آیت کریمہ کی تفسیر میں روایت کیا ہے کہ سب لوگ نوح علیہ السلام ہی کی اولاد میں سے ہیں۔ (تفسیر الطبری: 80/23) امام ترمذی، ابن جریر اور ابن ابو حاتم رحمہ اللہ نے سمرہ رضی اللہ عنہ سے روایت کیا ہے کہ نبی صلی اللہ علیہ وسلم نے اس آیت کے بارے میں فرمایا: ’’(اولاد سے مراد) حام، سام اور یافث ہیں۔‘‘ (جامع الترمذی، حدیث:3230) اور امام احمد رحمہ اللہ نے سمرہ رضی اللہ عنہ سے روایت کیا ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ’’سام عربوں کے باپ حام حبشیوں کے باپ اور یافث رومیوں کے باپ ہیں۔‘‘ (مسند أحمد) اور اسے امام ترمذی رحمہ اللہ نے بھی روایت کیا ہے۔ (جامع الترمذی، حدیث:3931) رومیوں سے مراد پہلے رومی، یعنی یونانی ہیں جو رومابن لیطی بن یونان بن یافث بن نوح علیہ السلام کی طرف منسوب ہیں۔\nارشاد باری تعالیٰ: ﴿وَ تَرَكْنَا عَلَيْهِ فِي الْاٰخِرِيْنَٞۖ۰۰۷۸﴾ ’’اور ہم نے پیچھے آنے والوں میں اس (کے ذکر جمیل) کو باقی چھوڑ دیا۔‘‘ کے بارے میں ابن عباس رضی اللہ عنہما فرماتے ہیں کہ انہیں ہمیشہ اچھے الفاظ میں یاد کیا جاتا رہے گا۔ (تفسیر الطبری:81/23) اور مجاہد رحمہ اللہ کہتے ہیں کہ اس کے معنی یہ ہیں کہ تمام انبیائے کرام ان کا ذکر خیر اور تعریف کریں گے۔ (تفسیر الطبری: 81/23) امام قتادہ وسدی رحمہم اللہ کا قول ہے کہ پیچھے آنے والوں میں اللہ تعالیٰ نے ان کے لیے اچھی تعریف کو باقی رکھا ہے۔ (تفسیر الطبری:81/23) ضحاک رحمہ اللہ کہتے ہیں کہ اس سے مراد سلام اور ثنائے حسن ہے۔ ﴿سَلٰمٌ عَلٰى نُوْحٍ فِي الْعٰلَمِيْنَ۰۰۷۹﴾ ’’تمام جہانوں میں نوح پر سلام ہو۔‘‘ یہ اس ذکر جمیل اور ثنائے حسن کی تفسیر ہے جو اللہ تعالیٰ نے باقی رکھی ہے کہ تمام جماعتیں اور امتیں ان پر سلام بھیجتی رہیں گی، ﴿اِنَّا كَذٰلِكَ نَجْزِي الْمُحْسِنِيْنَ۰۰۸۰﴾ ’’بے شک ہم نیکوکاروں کو اسی طرح بدلہ دیا کرتے ہیں۔‘‘ یعنی بندگان الٰہی میں سے جو شخص احسن انداز میں اللہ تعالیٰ کی اطاعت بجا لائے تو ہم اسی طرح اسے اچھا بدلہ دیا کرتے ہیں کہ بعد میں آنے والے لوگوں میں حسب مرتبہ اس کا ذکر جمیل جاری کر دیتے ہیں﴿اِنَّهٗ مِنْ عِبَادِنَا الْمُؤْمِنِيْنَ۰۰۸۱﴾ ’’بے شک وہ ہمارے مومن بندوں میں سے تھے۔‘‘ یعنی تصدیق کرنے والوں، توحید کو اختیار کرنے والوں اور ایمان ویقین رکھنے والوں میں سے تھے: ﴿ثُمَّ اَغْرَقْنَا الْاٰخَرِيْنَ۰۰۸۲﴾ ’’پھر ہم نے دوسروں کو غرق کر دیا۔‘‘ یعنی ہم نے انہیں ہلاک کر دیا، ان میں سے کوئی فرد بشر باقی نہ بچا، ان کا کوئی ذکر اور نشان بھی نہ رہنے دیا اور اگر انہیں یاد کیا بھی جاتا ہے تو اسی بد ترین صفت کے ساتھ کہ انہوں نے اللہ تعالیٰ اور اس کے رسول کی نافرمانی کی تو انہیں غرق کر کے تباہ وبرباد کر دیاگیا تھا۔\nاللہ تعالیٰ اپنے بندے اور اوّلین رسول، سیّدنا نوح علیہ السلام کے بارے میں آگاہ کرتا ہے کہ وہ ایک طویل عرصے تک اپنی قوم کو اللہ تعالیٰ کی طرف دعوت دیتے رہے، مگر ان کی دعوت نے اس سے زیادہ کچھ نہ کیا کہ لوگ اس دعوت سے دور بھاگتے رہے۔ تب سیّدنا نوح علیہ السلام نے اپنے رب کو پکارتے ہوئے دعا کی : ﴿رَّبِّ لَا تَذَرْ عَلَى الْاَرْضِ مِنَ الْكٰفِرِيْنَ دَيَّارًا۰۰۲۶﴾ (نوح:26) ’’اے میرے رب! زمین پر کوئی کافر بستا نہ چھوڑ۔‘‘ اور فرمایا:﴿رَبِّ انْصُرْنِيْ بِمَا كَذَّبُوْنِ۰۰۲۶﴾ (المؤمنون: 26) ’’اے میرے رب! ان کے جھٹلانے پر تو میری مدد فرما۔‘‘\nاللہ تعالیٰ نے سیّدنا نوح علیہ السلام کی دعا قبول فرمائی اور اپنی مدح و ثنا بیان کرتے ہوئے فرمایا:﴿ فَلَنِعْمَ الْمُجِيْبُوْنَٞۖ۰۰۷۵﴾ ہم پکارنے والے کی پکار اور اس کی آہ وزاری کو سنتے ہیں اور خوب جواب دیتے ہیں، چنانچہ اللہ تعالیٰ نے نوح علیہ السلام کی دعا قبول فرمائی۔ یہ قبولیت نوح علیہ السلام کی درخواست سے مطابقت رکھتی تھی۔ اللہ تعالیٰ نے نوح علیہ السلام اور آپ کے گھر والوں کو اس کرب عظیم سے نجات دی اور تمام کفار کو سیلاب میں غرق کر دیا۔ آپ کی نسل اور اولاد کو تسلسل سے باقی رکھا، چنانچہ تمام انسان سیّدنا نوح علیہ السلام کی نسل سے ہیں۔ اللہ تعالیٰ نے قیامت تک کے لیے آپ کو دائمی ثنائے حسن سے سرفراز فرمایا، کیونکہ آپ نے نہایت احسن طریقے سے اللہ تعالیٰ کی عبادت کی اور مخلوق کے ساتھ احسان کیا اور محسنین کے بارے میںاللہ تعالیٰ کی یہی سنت ہے۔ اللہ تعالیٰ محسنین کے احسان کے مطابق دنیا میںان کی ثنائے حسن کو پھیلاتا ہے۔\nسرکش و نافرمان قوموں کی ہلاکت کاذکر آنے کے بعد مناسب معلوم ہوا کہ ان میں سے بعض قوموں کے حالات کچھ تفصیل کے ساتھ بیان کیے جائیں۔ چنانچہ اس ضمن میں یہاں سات انبیائے کرام علیہم السلام اور ان کی قوموں کے واقعات بیان کیے گئے ہیں۔ سب سے پہلا واقعہ نوح علیہ السلام اور ان کی قوم ہے۔\nاللہ تعالیٰ نے فرمایا کہ نوح علیہ السلام نے ہمیں اپنی قوم کے خلاف مدد کے لیے پکارا (جیسا کہ سورۃ المومنون آیات (26/اور 39) میں آیا ہے : ﴿قَالَ رَبِّ انْصُرْنِيْ بِمَا كَذَّبُوْنِ۰۰۲۶﴾ ’’نوح نے دعا کی، اے میرے رب ! ان کے جھٹلانے پر تو میری مدد کر۔‘‘ اور سورۃ القمر آیت(10)میں آیا ہے :﴿فَدَعَا رَبَّهٗۤ اَنِّيْ مَغْلُوْبٌ فَانْتَصِرْ۰۰۱۰﴾ ’’نوح نے اپنے رب سے دعا کی کہ میں مغلوب ہوں، تو میری مدد فرما۔‘‘ تو ہم نے ان کی دعا قبول کرلی (اس لیے کہ ہمارے سوا کون کسی پریشان حال کی پکار سن سکتا ہے) اور انہیں اور ان کے خاندان والوں کو (ان کی بیوی اور بیٹے کنعان کے سوا) طوفانِ عظیم سے بچالیا اور اُن کی نسلوں کو دنیا میں باقی رکھا۔ چنانچہ قوم نوح کی ہلاکت کے بعد دوبارہ پوری دنیا نوح کے تین بیٹوں، سام، حام اور یافث کی اولاد سے آباد ہوئی۔"],[6145,"§تقلید آباء کی مذمت\nانہوں نے یہ سوچنے کی زحمت گوارا ہی نہ کی جو کچھ ان کے آباء و اجداد کرتے آرہے ہیں۔ وہ درست ہے یاغلط ہے۔ جس راہ پر انہیں چلتے دیکھا اسی پر دوڑنے لگے، کنواں کھائی کچھ نہ دیکھا اور اگر ان کے پاس رسول آئے تو انہیں بھی جھٹلا دیا۔ اور اپنی آبائی رسوم کی حمایت میں رسولوں علیہم السلام کی مخالفت پر اُتر آئے حالانکہ اگر وہ سابقہ اقوام کی روش سے اور ان کے انجام سے کچھ سبق حاصل کرنا چاہتے تو کر سکتے تھے۔"],[6146,"§نوح علیہ السلام کی بددعا اور اس کی قبولیت\nبولیت : سیدنا نوح علیہ السلام نے ساڑھے نو سو سال اپنی قوم سے سر کھپایا۔ ان کو دلائل سے سمجھایا اور مختلف پیرایوں میں سمجھانے میں کوئی کسر اُٹھا نہ رکھی۔ مگر ان لوگوں نے ان کی ایک نہ مانی۔ اُلٹا ان کا مذاق اُڑاتے اور ایذائیں پہنچاتے رہے۔ اس طویل عرصہ میں معدودے چند آدمی آپ پر ایمان لائے۔ پھر جب آپ اپنی قوم سے قطعی طور پر مایوس ہو گئے کہ اب باقی لوگوں میں سے کوئی بھی ایمان لانے والا نظر نہیں آتا اور سب میرے اور میرے ساتھیوں کے درپے آزار ہیں تو اس وقت آپ علیہ السلام نے اللہ کے حضور فریاد کی کہ یا اللہ ! مجھے ان لوگوں نے دبالیا ہے اب تو ہی ان سے بدلہ لے اور مجھے ان ظالموں سے نجات دے۔"],[6147,"§کیا نوح آدم ثانی ہیں؟\nلسلام آدم ثانی ہیں؟ : یہاں صرف اتنا ہی مذکور ہے کہ طوفان نوح علیہ السلام کے بعد نسل انسانی صرف نوح کے تین بیٹوں(حام۔ سام اور یافث) سے چلی (اور چوتھا بیٹا یام کافر تھا جو طوفان میں غرق ہو گیا تھا) اور اس کی تائید ترمذی کی درج ذیل حدیث سے بھی ہوتی ہے۔ سیدناسمرہ سے روایت ہے کہ آپ نے اس آیت کی تفسیر میں فرمایا کہ نوح کے تین بیٹے تھے۔ حام، سام یافث، حام حبش کا باپ، سام عرب کا اور یافث روم کا۔ (صحیح ترمذی)مگربعض دوسری آیات سے معلوم ہوتا ہے کہ طوفان نوح کے بعد نسل سیدنا نوح علیہ السلام کی اولاد اور ان لوگوں کی اولاد سے چلی تھی جو کشتی میں آپ کے ساتھ سوار تھے۔ (سورۂ بنی اسرائیل آیت نمبر 3)اس سے یہی معلوم ہوتا ہے کہ پہلی آیت میں اجمال اور دوسری میں تفصیل ہے۔\nیعنی ساڑھے نو سو سال کی تبلیغ کے باوجود جب قوم کی اکثریت نے ان کی تکذیب ہی کی اور انہوں نے محسوس کر لیا کہ ایمان لانے کی کوئی امید نہیں ہے تو اپنے رب کو پکارا۔ ﴿فَدَعَا رَبَّهٗۤ اَنِّيْ مَغْلُوْبٌ فَانْتَصِرْ۰۰۱۰﴾ (القمر:10) ’’یا اللہ میں مغلوب ہوں، میری مدد فرما۔‘‘ چنانچہ ہم نے نوح کی دعا قبول کی اور ان کی قوم کو طوفان بھیج کر ہلاک کر دیا۔\nاکثر مفسرین کے قول کے مطابق سیّدنا نوح علیہ السلام کے تین بیٹے تھے۔حام، سام، یافث۔ انہی سے بعد کی نسل انسانی چلی۔ اسی لیے سیّدنا نوح کو آدم ثانی بھی کہا جاتا ہے یعنی آدم کی طرح، آدم کے بعد یہ دوسرے ابوالبشر ہیں۔ سام کی نسل سے عرب، فارس، روم اور یہود و نصاریٰ ہیں۔ حام کی نسل سے سودان (مشرق سے مغرب تک) یعنی سندھ، ہند، نوب، زنج، حبشہ، قبط اور بربر وغیرہم ہیں اور یافث کی نسل سے صقالبہ، ترک، خزرج اور یاجوج و ماجوج وغیرہم ہیں۔ (فتح القدیر) واللہ اعلم\nوَ لَقَدْ اَرْسَلْنَا فِيْهِمْ مُّنْذِرِيْنَ: آپ کی قوم سے پہلے اکثر قومیں گمراہی کے گڑھے میں گرتی رہیں جب کہ ہم نے ان میں کثرت کے ساتھ انبیاء علیہم الصلوۃ والسلام کو بھیجا تاکہ وہ انھیں اللہ کے عذاب سے خوف زدہ کریں جب کہ وہ گمراہی میں آگے بڑھتے چلے گئے انھوں نے ادھر سے رخ نہ موڑا آپ غور کریں ان ڈرائے گئے لوگوں کا انجام کیسا ہوا ؟ ہم نے انھیں تباہ و برباد کردیا انھیں عبرت کا سامان بنایا البتہ اللہ تعالیٰ کے مومن مخلص بندوں کو اللہ نے اپنی اطاعت کے لیے خاص کیا وہ عذاب سے محفوظ رہے۔ جب نوح علیہ السلام نے مسئلہ توحید کو لوگوں کے سامنے پیش کیا تو اس کی امت نے ان کی مخالفت کی انھیں جھوٹا قرار دیا ان کی قوم سے چند لوگ ہی ایمان لائے حالانکہ نوح علیہ السلام اپنی قوم میں طویل عرصہ تک رہے قوم نے انھیں اذیتوں میں مبتلا کیا بلکہ ان کے قتل کا ارادہ کیا تو انھوں نے اپنی قوم کے خلاف ہماری جانب دعا کے لیے ہاتھ اٹھائے تو ہم نے ان کی دعا کو قبول کیا۔"],[6148,"§علامہ صاوی رحمہ اللہ کی وضاحت\nاللہ تعالیٰ نے اس سورت میں آٹھ پیغمبروں، نوح، ابراہیم، اسماعیل ذبیح، موسیٰ، ہارون، الیاس، لوط اور یونس علیہم السلام کے واقعات بیان کیے ہیں، مقصود نبی کو صبر دلانا ہے اور ان لوگوں کو خوف زدہ کرنا ہے جنہوں نے آپ صلی اللہ علیہ وسلم کی نبوت کو تسلیم نہ کیا۔\nوَ نَجَّيْنٰهُ وَ اَهْلَهٗ مِنَ الْكَرْبِ الْعَظِيْمِ: اور ہم نے اس کو اور ان کی جو ان پر ایمان لائے مقصود اہل و عیال اور دیگر متبعین ہیں انھیں غرق ہونے سے تحفظ عطا کیا، مفسرین کے بیان کے مطابق ان کی تعداد اَسّی (80) بیان کی گئی ہے اور ان میں کچھ مرد اور عورتیں تھیں جب کہ ہم نے نوح علیہ السلام کی اولاد اور متبعین کو قوم کی تباہی کے بعد باقی رکھا، حقیقت یہ ہے کہ جب لوگ طوفان میں غرق ہو کر مرگئے اور نوح علیہ السلام اور ان کی کشتی میں سوار لوگ طوفان کی زد میں محفوظ رہے تو نوح علیہ السلام کی اولاد ہام، سام، یافث، تینوں سے سلسلہ نسل چلا اور ہم نے نوح علیہ السلام کے بارے میں ہر امت میں قیامت کے دن تک کے لیے تعریف کے کلمات کو چھوڑا نوح علیہ السلام پر اللہ اور تمام مخلوق کی جانب سے ہمیشہ ہمیشہ کے لیے بلاکسی انقطاع کے سلامتی قائم دائم رہے۔\nاور ہم اسی طرح ان لوگوں کو بدلہ عطا کرتے ہیں، جو اچھے اعمال کرنے والے ہیں قیامت تک ان کا اچھا تذکرہ ہمیشہ باقی رہنے والا ہے اور یقیناً نوح علیہ السلام کا شمار ہمارے ان بندوں میں سے ہے جو کامل ایمان اور یقین کے ساتھ موصوف ہیں ذہن نشین کریں کہ اہل عرب کے باپ سام اور حبشیوں کے باپ ہام اور رومیوں کے باپ یافث ہیں۔\nسَلٰمٌ عَلٰى نُوْحٍ فِي الْعٰلَمِيْنَ: نوح علیہ السلام نے اپنا اچھا تذکرہ پیچھے چھوڑا کہ ان کی سبھی لوگ تعریف کرتے ہیں اور سلام کہتے ہیں ہم اس طرح ان لوگوں کو بدلہ عطا کرتے ہیں جو عمدگی کے ساتھ اللہ کی اطاعت میں مصروف رہتے ہیں اور ان کی وفات کے بعد ان کا تذکرہ خیرہوتا رہتا ہے یقیناان کا شمار ہمارے موحد بندوں سے ہوتا ہے بعدازاں ہم نے باقی لوگوں کو ڈبو دیا اور تباہ و برباد کردیا ان سے کوئی باقی نہ رہا۔\nوَ اِنَّ مِنْ شِيْعَتِهٖ لَاِبْرٰهِيْمَۘ۰۰۸۳ اِذْ جَآءَ رَبَّهٗ بِقَلْبٍ سَلِيْمٍ۰۰۸۴ اِذْ قَالَ لِاَبِيْهِ\nوَقَوْمِهٖ مَا ذَا تَعْبُدُوْنَۚ۰۰۸۵ اَىِٕفْكًا اٰلِهَةً دُوْنَ اللّٰهِ تُرِيْدُوْنَؕ۰۰۸۶ فَمَا ظَنُّكُمْ بِرَبِّ\nالْعٰلَمِيْنَ۰۰۸۷\nاور بے شک ابراہیم بھی اسی (نوح علیہ السلام)کے گروہ سے ہے. جب وہ اپنے رب کے پاس پاک صاف دل کے ساتھ آیا / جب اس نے اپنے باپ اور اپنی قوم سے کہا: تم کس چیز کی عبادت کرتے ہو ؟ کیا تم اللہ کو چھوڑ کر جھوٹے گھڑے ہوئے\nمعبودوں کو چاہتے ہو؟ پھر رب العالمین کی نسبت تمھار ا کیا خیال ہے؟"],[6149,"§سیّدنا ابراہیم علیہ السلام اور آپ کی قوم کا قصہ\nعلی بن ابو طلحہ رحمہ اللہ نے ابن عباس رضی اللہ عنہما سے روایت کیا ہے کہ ﴿وَ اِنَّ مِنْ شِيْعَتِهٖ لَاِبْرٰهِيْمَ﴾ ’’اور بے شک اسی (نوح) کی جماعت سے البتہ ابراہیم بھی ہے۔‘‘ سے مراد یہ ہے کہ سیّدنا ابراہیم علیہ السلام بھی انہی کے دین (پرکار بند رہنے) والوں میں سے تھے۔ (تفسیر الطبری:82/23) اور مجاہد رحمہ اللہ کہتے ہیں کہ اس کے معنی یہ ہیں کہ وہ انہی کے طریقے اور سنت پر تھے۔(تفسیر الطبری:82/23) ﴿اِذْ جَآءَ رَبَّهٗ بِقَلْبٍ سَلِيْمٍ۰۰۸۴﴾ ’’جب وہ اپنے پروردگار کے پاس (عیب سے) پاک دل لے کر آئے۔‘‘ ابن عباس رضی اللہ عنہما فرماتے ہیں کہ اس سے مراد لا الٰہ الا اللہ کی شہادت ہے۔\nابن ابو حاتم رحمہ اللہ نے عوف رحمہ اللہ سے روایت کیا ہے کہ میں نے محمد بن سیرین رحمہ اللہ سے پوچھا کہ قلب سلیم سے کیا مراد ہے؟ انہوں نے فرمایا: انسان جانتا ہو کہ اللہ تعالیٰ حق ہے، قیامت کے آنے میں کوئی شک نہیں اور اللہ تعالیٰ قبروں والوں کو ضرور اٹھائے گا۔ (تفسیر القرطبی:91/15) اور حسن فرماتے ہیں کہ ﴿بِقَلْبٍ سَلِيْمٍ۰۰۸۴﴾ سے مراد وہ دل ہے جو شرک سے پاک ہو۔ (تفسیر الطبری:83/23) عروہ رحمہ اللہ کہتے ہیں کہ اس سے مراد وہ دل ہے جو کسی پر لعنت نہ کرے۔ (تفسیر الطبری:83/23) ارشاد باری تعالیٰ ہے: ﴿ا ِذْ قَالَ لِاَبِيْهِ وَ قَوْمِهٖ مَا ذَا تَعْبُدُوْنَۚ۰۰۸۵﴾ ’’جب اس نے اپنے باپ سے اور اپنی قوم سے کہا کہ تم کس چیز کو پوجتے ہو؟‘‘ یعنی انہوں نے اپنی قوم کے بتوں کو پوجنے کی روش کا انکار کیا،اس لیے اللہ عزوجل نے بیان فرمایا ہے کہ انہوں نے کہا: ﴿اَىِٕفْكًا اٰلِهَةً دُوْنَ اللّٰهِ تُرِيْدُوْنَؕ۰۰۸۶فَمَا ظَنُّكُمْ بِرَبِّ الْعٰلَمِيْنَ۰۰۸۷﴾ ’’کیا تم اللہ کو چھوڑ کر جھوٹے گھڑے ہوئے معبودوں کو چاہتے ہو، بھلا پروردگار عالم کے بارے میں تمہارا کیا خیال ہے؟‘‘ امام قتادہ رحمہ اللہ فرماتے ہیں کہ اس کا مطلب یہ ہے کہ جب تم اللہ کے سوا اوروں کو بھی پوجتے ہو تو تمہارا کیا خیال ہے جب تم اس سے ملاقات کروں گے تو وہ تم سے کیا سلوک کرے گا؟ (تفسیر الطبری:83/23)"],[6150,"§شیعہ کا لغوی مفہوم\nیہاں لفظ شیعہ استعمال ہوا ہے۔ شیعہ ایسے فرقہ یا پارٹی کو کہتے ہیں جن کے عقائد آپس میں ملتے جلتے ہوں مگر دوسروں سے مختلف ہوں۔ مطلب یہ ہے کہ توحید اور معاد کے بارے میں سیدنا ابراہیم علیہ السلام کے بھی وہی عقائد تھےجو سیدنا نوح علیہ السلام کے تھے۔ اوریہ تو واضح سی بات ہے کہ تمام انبیاء علیہم السلام کی اُصولی تعلیم ایک ہی جیسی رہی ہے۔ اور اسی اُصولی تعلیم کا نام دین ہے۔"],[6151,"§سیدنا ابراہیم علیہ السلام کی ستارہ پرست قوم\nسیدنا ابراہیم علیہ السلام کا اصل وطن عراق کا شہر بابل تھا۔ یہ لوگ ستارہ پرست تھے۔ اور بالخصوص سات مشہور سیاروں سورج، چاند، زہرہ، عطارد، مشتری، مریخ اور زحل کی چال سے خوب واقف تھے۔ علاوہ ازیں یہ لوگ ان سیاروں کے انسانی زندگی پر اثرات کے بھی سختی سے قائل تھے۔ انہیں سیاروں کے الگ الگ مندر تعمیر کر رکھے تھے، جن میں ان سیاروں کے خیالی مجسّمے یابت رکھے جاتے تھے۔ وہ خود ہی زائچے تیار کرتے اور اس کے مطابق ان سیاروں کی خوشنودی حاصل کرنے کے لیے ان کے مجسّموں کے سامنے نذریں نیازیں پیش کی جاتی تھیں۔ انہیں زائچوں کے ذریعہ وہ آئندہ سے متعلق اپنی اپنی قسمت کا حال معلوم کرتے تھے۔ ان کے ستاروں کے اثرات پر اعتقاد کا یہ حال تھا کہ ان میں ہر شخص زائچہ تیار کرنے کے بغیر بھی سیاروں کی چال پر غور کرکے اپنا پروگرام بناتا تھا۔ اس قدر مشترک تھا یہ قوم جس میں سیدنا ابراہیم علیہ السلام مبعوث ہوئے تھے۔ انہوں نے جب بالکل خالی الذہن ہو کر اور یکسو ہو کر اپنے آپ کو اپنے پروردگار کے حوالہ کر دیا تو اللہ تعالیٰ نے آپ صلی اللہ علیہ وسلم کو نبوت عطا فرمائی۔ اور سیدنا ابراہیم علیہ السلام کو اپنی مکمل فرمانروائی اور ان سیاروں اور ان کے مجسّموں کے بالکل بے اختیار اور مجبور محض ہونے کی حقیقت واضح کر دی۔"],[6152,"§دعوت ِ توحید کاآغاز اپنے باپ سے\nچنانچہ آپ علیہ السلام نے توحید کی دعوت کا آغاز اپنے گھر سے کیا۔ سب سے پہلے باپ کو اس حقیقت سے روشناس کرایا وہ خود شاہی مند رکا پروہت، بت تراش اور بت فروش تھا وہ آپ کی اس نصیحت پر بگڑ بیٹھا تو آپ اپنی قوم کی طرف متوجہ ہوئے۔ آپ کا اپنے باپ اور اپنی قوم سے سوال یہ تھا کہ تم یہ بت اپنے ہاتھوں سے بناتے ہو پھر خود ہی انہیں خدائی اختیارات بانٹ دیتے ہو کہ فلاں سیارہ کی روح یا مجسمہ اگر ہم سے خوش رہے تو ہمیں مال و دولت زیادہ ملے گا۔ فلاں کی عبادت کی جائے تو علم نصیب ہوگا۔ اور فلاں کو خوش کیاجائے تو فصل بہت اچھی ہوگی۔ یہ سب اختیارات تو تم نے ان میں تقسیم کر دیے۔ اب بتاؤ کہ جس ہستی نے اس کائنات اور ان سیاروں کو پید اکیا ہے اور اس کا ان پر کنٹرول ہے اس کے پاس بھی کوئی اختیار تم نے چھوڑا ہے یا نہیں ؟کیا اب وہ بالکل بے بس ہو چکا ہے؟ آخر اس کے متعلق تم کیا سمجھتے ہو؟\nاللہ پاک ابراہیم علیہ السلام کے واقعہ کا آغاز فرماتے ہوئے اس حقیقت سے پردہ کشائی فرما رہے ہیں کہ نوح علیہ السلام کے معاونین اور مددگاروں سے جوان کے راہ پر گامزن رہے ابراہیم خلیل علیہ السلام بھی ہیں ذہن نشین کریں کہ نوح اور ابراہیم علیہ السلام پیغمبر کے درمیان دوہزارچھ سو چالیس سال کا عرصہ ہے اور ان کے درمیان ہود اور صالح علیہما السلام پیغمبر بھی گزرے ہیں جب وہ اپنے پروردگار حقیقی کی بارگاہ میں ایسے دل کے ساتھ حاضر ہوئے جو ہر قسم کی آلائشوں سے پاک صاف تھا شکوک و شبہات اور شرک سے منزہ تھا جب اس نے اپنے باپ آزر اور اپنی قوم کو ڈانٹ پلاتے ہوئے جھنجھوڑا اور ان سے استفسار کیا تم نے بتوں کی عبادت میں خود کو کیوں لگا رکھا ہے کیا تم اللہ کی ذات کے سوا جھوٹ کے ساتھ بتوں کی عبادت کررہے ہو ؟ خیال کریں اور انتہائی درجہ کے برے جھوٹ کو عربی زبان میں لفظ اِفْــکٌ سے تعبیر کیا جاتا ہے جس میں ہمیشہ اضطرابی کیفیت موجزن رہتی ہے اور شک وشبہ بھی موجود رہتا ہے۔\nفَمَا ظَنُّكُمْ بِرَبِّ الْعٰلَمِيْنَ: اس آیت کے استفہام میں زبردست ڈانٹ کا داعیہ موجزن ہے انھیں زبردست خوف زدہ کرتے ہوئے ان سے دریافت کیا جارہا ہے کہ تم جہانوں کے پروردگار کے بارے میں کیا خیال رکھتے ہو کہ وہ تمہارے ساتھ کیا سلوک کرے گا جب اس کے ساتھ تمہاری ملاقات ہوگئی کیا تم سمجھتے ہو کہ وہ تمہیں تمہارے حال پر چھوڑ دے گا، تمہیں عذاب میں مبتلا نہیں کرے گا جب کہ تم نے اللہ پاک کے سوا کو اپنا معبود بنائے رکھا ہے۔\nفَنَظَرَ نَظْرَةً فِي النُّجُوْمِۙ۰۰۸۸ فَقَالَ اِنِّيْ سَقِيْمٌ۰۰۸۹ فَتَوَلَّوْا عَنْهُ مُدْبِرِيْنَ۰۰۹۰ فَرَاغَ\nاِلٰۤى اٰلِهَتِهِمْ فَقَالَ اَلَا تَاْكُلُوْنَۚ۰۰۹۱ مَا لَكُمْ لَا تَنْطِقُوْنَ۰۰۹۲ فَرَاغَ عَلَيْهِمْ ضَرْبًۢا\nبِالْيَمِيْنِ۰۰۹۳ فَاَقْبَلُوْۤا اِلَيْهِ يَزِفُّوْنَ۰۰۹۴ قَالَ اَتَعْبُدُوْنَ مَا تَنْحِتُوْنَۙ۰۰۹۵ وَ اللّٰهُ\nخَلَقَكُمْ وَ مَا تَعْمَلُوْنَ۰۰۹۶ قَالُوا ابْنُوْا لَهٗ بُنْيَانًا فَاَلْقُوْهُ فِي الْجَحِيْمِ۰۰۹۷ فَاَرَادُوْا بِهٖ\nكَيْدًا فَجَعَلْنٰهُمُ الْاَسْفَلِيْنَ۰۰۹۸\nتب اس نے ایک نگاہ ستاروں میں ڈالی صلی اللہ علیہ وسلم پھر کہا: بے شک میں تو بیمار ہوں رضی اللہ عنہ چنانچہ وہ اس سے پیٹھ پھیر کر لوٹ گئے پھر وہ ان کے معبودوں کی طرف متوجہ ہوا اور کہا: کیا تم کھاتے نہیں ؟ تمھیں کیا ہے کہ تم بولتے نہیں ؟< پھر وہ انھیں دائیں ہاتھ سے مارتا ہوا متوجہ ہوا > پھر وہ لوگ دوڑتے ہوئے اس کی طرف آئے ? اس نے کہا: کیا تم ان کی عبادت کرتے ہو جنھیں تم خود تراشتے ہو؟\nحالانکہ اللہ ہی نے تمھیں اور تمھارے اعمال کو پید اکیا ہے\nوہ کہنے لگے : اس کے لیے ایک مکان بنائو (اس میں آگ جلائو) اور اسے دہکتی آگ میں ڈال دو\nپھر انھوں نے اس کے ساتھ ایک چال چلنے کا ارادہ کیا تو ہم نے انھیں ہی نیچا\nدکھا دیا"],[6153,"§بت شکن؟\nسیّدنا ابراہیم علیہ السلام نے اپنی قوم سے یہ (بیمار ہونے کا ذکر) اس لیے فرمایا تھا تا کہ قوم کے اپنے میلے پر چلے جانے کے بعد آپ شہر میں رہ سکیں کیونکہ قوم کے لوگوں کا اپنے میلے کے لیے شہر سے باہر چلے جانے کا وقت قریب آگیا تو آپ نے پروگرام بنایا تھا کہ ان کے معبودوں کو خالی پا کر ان کو توڑ پھوڑ ڈالیں گے، اس لیے آپ نے ان سے اس انداز میں گفتگو کی جوفی نفسہ حق تھی مگر لوگوں نے اس سے اپنے خیال کے مطابق یہ سمجھا کہ آپ بیمار ہیں ﴿فَتَوَلَّوْا عَنْهُ مُدْبِرِيْنَ۰۰۹۰﴾ ’’تب وہ اس سے پیٹھ پھیرتے ہوئے لوٹ گئے۔‘‘ قتادہ رحمہ اللہ کہتے ہیں کہ جو شخص غوروفکر کر رہا ہو تو عرب اس کے لیے ’’اس نے ستارں کی طرف دیکھا۔‘‘ کے الفاظ استعمال کرتے ہیں۔ (تفسیر ابن أبی حاتم:3219/10) قتادہ رحمہ اللہ کے کہنے کے معنی یہ ہیں کہ سیّدنا ابراہیم علیہ السلام نے اس بات پر غوروفکر کرتے ہوئے آسمان کی طرف دیکھا کہ وہ انہیں کسی طرح غافل کر دیں، پس آپ نے فرمایا: ﴿اِنِّيْ سَقِيْمٌ۰۰۸۹﴾ ’’میں تو بیمار ہوں۔‘‘ یعنی کمزور ہوں۔‘‘\nاور وہ حدیث جسے امام ابن جریر نے یہاں سیّدنا ابو ہریرہ رضی اللہ عنہ سے روایت کیا ہے اور جس میں یہ ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ﴿اِنِّيْ سَقِيْمٌ۰۰۸۹﴾، ﴿بَلْ فَعَلَهٗ١ۖۗ كَبِيْرُهُمْ هٰذَا ﴾ (الأنبیاء:63) ’’سیّدنا ابراہیم علیہ السلام نے تین باتوں کے سوا کبھی خلاف واقع بات نہیں کی، ان میں سے دو باتیں تو اللہ تعالیٰ کی ذات پاک کے لیے تھیں: (1) آپ کی یہ بات کہ ﴿اِنِّيْ سَقِيْمٌ۰۰۸۹﴾ ’’بے شک میں تو بیمار ہوں۔‘‘ اور (2)﴿بَلْ فَعَلَهٗ١ۖۗ كَبِيْرُهُمْ هٰذَا﴾ (الأنبیاء:63) ’’بلکہ یہ ان کے اس بڑے (بت) نے کیا ہے۔‘‘ اور تیسری بات یہ تھی کہ انہوں نے سیّدنا سارہ[ کے بارے میں کہا:’’میری بہن ہے۔‘‘ (تفسیر الطبری: 84/23) یہ حدیث کتب صحاح اور سنن میں کئی سندوں سے بیان کی گئی ہے۔ (صحیح البخاری، حدیث:5084) ان باتوں سے مراد وہ حقیقی جھوٹ نہیں جس کے بولنے والے کو مذموم قرار دیا جاتا ہے، حاشاوکلا سیدنا ابراہیم علیہ السلام کی طرف کذب حقیقی کی نسبت کی جائے بلکہ آپ کی نسبت کذب کا لفظ مجازی طور پر استعمال کیا گیا ہے اور یہ شرعی ودینی مقصد کی خاطر کلام میں معاریض (توریہ) کے قبیل سے ہے، یہ بھی کہا گیا ہے کہ آپ نے جو یہ فرمایا: ﴿اِنِّيْ سَقِيْمٌ۰۰۸۹ ﴾ ’’بے شک میں تو بیمار ہوں۔‘‘ اس سے آپ کا مقصود یہ تھا کہ تم اللہ تعالیٰ کے سوا بتوں کی جو پوجا کرتے ہو تو اس وجہ سے میرا دل بیمار ہے۔ امام حسن بصری رحمہ اللہ نے کہا ہے کہ جب ابراہیم علیہ السلام کی قوم کے لوگ میلے کی طرف جانے لگے تو انہوں نے ابراہیم علیہ السلام سے بھی چلنے کے لیے کہا تو آپ پشت کے بل لیٹ گئے، فرمانے لگے: ﴿اِنِّيْ سَقِيْمٌ۰۰۸۹﴾ اور پھر آسمان کی طرف دیکھنے لگے اور جب سب لوگ شہر سے باہر نکل گئے تو آپ ان کے بتوں کے پاس چلے گئے اور انہیں توڑ دیا۔ اسے ابن ابو حاتم رحمہ اللہ نے روایت کیا ہے۔ (تفسیر ابن أبی حاتم: 3220/10)\nاللہ تعالیٰ نے فرمایا ہے: ﴿فَتَوَلَّوْا عَنْهُ مُدْبِرِيْنَ۰۰۹۰﴾ ’’تب وہ اس سے پیٹھ پھیرتے ہوئے لوٹ گئے۔‘‘ اور جب وہ چلے گئے تو آپ جلدی سے اور مخفی طور پر بتوں کے پاس چلے گئے ﴿فَقَالَ اَلَا تَاْكُلُوْنَۚ۰۰۹۱﴾ ’’اور کہنے لگے کہ تم کھاتے کیوں نہیں؟‘‘ اس لیے کہ ان لوگوں نے ان بتوں کے سامنے نذرونیاز کے طور پر کھانے رکھے ہوئے تھے تا کہ اس سے ان کے رزق میں برکت ہو جائے، جب سیّدنا ابراہیم علیہ السلام نے ان کے سامنے کھانوں کو دیکھا تو فرمایا: ﴿اَلَا تَاْكُلُوْنَۚ۰۰۹۱مَا لَكُمْ لَا تَنْطِقُوْنَ۰۰۹۲﴾ ’’تم کھاتے کیوں نہیں؟ تمہیں کیا ہوا ہے، تم بولتے بھی نہیں؟‘‘ ارشاد باری تعالیٰ ہے: ﴿فَرَاغَ عَلَيْهِمْ ضَرْبًۢا بِالْيَمِيْنِ۰۰۹۳﴾ ’’پھر وہ انہیں دائیں ہاتھ سے مارتا ہوا متوجہ ہوا۔‘‘ فراء کہتے ہیں کہ اس کے معنی مَالَ یعنی ٹوٹ پڑے اور پل پڑے کے ہیں، یعنی دائیں ہاتھ سے ضربیں لگاتے ہوئے ان پر ٹوٹ پڑے۔ قتادہ اور جوہری کہتے ہیں کہ اس کے معنی ہیں: أَقْبَلَیعنی آگے بڑھے۔(تفسیر الطبری:86/23) دائیں ہاتھ سے آپ نے اس لیے ضرب لگائی کہ اس سے ضرب کاری اور شدید لگتی ہے، آپ نے بتوں کو توڑ پھوڑ کر ریزہ ریزہ کر دیا مگر ایک بڑے بت کو نہ توڑا تا کہ وہ اس کی طرف رجوع کریں، جیسا کہ قبل ازیں سورۂ انبیاء میں اس کی تفسیر بیان کی جا چکی ہے۔ (دیکھیے الأنبیآء آیات:52-67 کے ذیل میں۔) اور یہاں فرمایا ہے: ﴿فَاَقْبَلُوْۤا اِلَيْهِ يَزِفُّوْنَ۰۰۹۴﴾ ’’تو وہ اس کی طرف دوڑتے ہوئے آئے۔‘‘\nمجاہد اور دیگر کئی ائمہ تفسیر رحمہ اللہ نے کہا ہے کہ اس کے معنی یہ ہیں کہ وہ لوگ ان کے پاس دوڑتے بھاگتے ہوئے آئے۔ (تفسیر الطبری:88/23) یہاں یہ قصہ مختصر مگر سورۂ انبیاء میں مفصل بیان کیا گیا ہے۔ (دیکھیے الأنبیآء آیات:59-67) بہر حال جب وہ واپس آئے تو فوراً یہ جان سکے کہ یہ کام کس نے کیا ہے؟ حتیٰ کہ جب انہوں نے تحقیق کی اور معلومات حاصل کیں تو انھوں معلوم ہوا کہ یہ کام تو سیّدنا ابراہیم علیہ السلام نے کیا ہے اور جب وہ آپ کے پاس سرزنش کے لیے آئے تو آپ نے ان کی توبیخ کی اور ان کی خرابیاں بیان فرمائیں: ﴿اَتَعْبُدُوْنَ مَا تَنْحِتُوْنَۙ۰۰۹۵﴾ ’’کیا تم ایسی چیزوں کو پوجتے ہو، جنہیں تم خود تراشتے ہو؟‘‘ یعنی اللہ تعالیٰ کے سوا تم ایسے بتوں کی پوجا کیوں کرتے ہو، جنہیں تم خود اپنے ہاتھوں سے تراشتے اور بناتے ہو؟﴿وَ اللّٰهُ خَلَقَكُمْ وَ مَا تَعْمَلُوْنَ۰۰۹۶﴾ ’’حالانکہ تمہیں اور جو تم کرتے ہو اسے اللہ ہی نے پیدا کیا ہے۔‘‘ یہاں مامصدر یہ بھی ہو سکتا ہے، اس صورت میں معنی یہ ہوں گے کہ اللہ تعالیٰ نے تمہیں اور تمہارے عمل کو پیدا فرمایا ہے اور یہ بھی احتمال ہے کہ ما الذی کے معنی میں ہو اور اس صورت میں معنی یہ ہوں گے کہ اللہ تعالیٰ نے تمہیں اور جو تم بناتے ہو، (بت وغیرہ) اس کو پیدا فرمایا ہے لیکن دونوں معنی متلازم ہیں اور ایک کے ساتھ دوسرا معنی لازم ہے۔ لیکن ان میں سے پہلا معنی زیادہ ظاہر ہے کیونکہ امام بخاری رحمہ اللہ نے کتاب خلق افعال العباد میں سیّدنا حذیفہ رضی اللہ عنہ کی مرفوع روایت بیان کی ہے کہ ’’بے شک اللہ ہی ہر کام کرنے والے اور اس کے کام کو پیدا فرماتا ہے۔‘‘ (السلسة الصحیحیة:181/4) اور بعض راویوں نے (اس کے بعد) ﴿وَ اللّٰهُ خَلَقَكُمْ وَ مَا تَعْمَلُوْنَ۰۰۹۶﴾ پڑھا۔ بہر حال جب ان پر حجت قائم ہو گئی تو وہ بات کرنے کے بجائے آپ کو ہاتھوں سے پکڑنے کی طرف پھرے اور زبردستی کرتے ہوئے کہنے لگے: ﴿ابْنُوْا لَهٗ بُنْيَانًا فَاَلْقُوْهُ فِي الْجَحِيْمِ۰۰۹۷﴾ ’’اس کے لیے ایک مکان (مقام) بنائو، (اس میں آگ جلائو) اور اسے دہکتی آگ میں ڈال دو۔‘‘ اس واقعے کی ساری تفصیل قبل ازیں سورۂ انبیاء میں بیان کی جا چکی ہے۔ (دیکھیے الأنبیآء آیات:68-70 کے ذیل میں) جس کا خلاصہ یہ ہے کہ اللہ تعالیٰ نے آپ کو آگ سے محفوظ رکھا، ان پر غالب کر دیا، اپنی حجت کو بلند کر دیا اور اپنے پیغمبر کو فتح ونصرت سے سرفراز فرمایا، اس لیے اس نے ارشاد فرمایا ہے: ﴿فَاَرَادُوْا بِهٖ كَيْدًا فَجَعَلْنٰهُمُ الْاَسْفَلِيْنَ۰۰۹۸﴾ ’’پھر انہوں نے اس کے ساتھ ایک چال چلنی چاہی تو ہم نے انہی کو نیچا دکھا دیا۔‘‘\nشوکانی رحمہ اللہ نے مفسر واحدی کے حوالے سے مفسرین کا قول نقل کیا ہے کہ وہ لوگ علم نجوم کے قائل تھے، اسی لیے ابراہیم علیہ السلام نے ستاروں کی طرف دیکھ کر کہاکہ مجھے ایسا لگتا ہے کہ اگر میں تمہارے ساتھ میلے میں شریک ہوں گا تو بیمار پڑجاؤں گا، تاکہ لوگ انہیں میلہ میں شرکت سے معذور سمجھیں۔ چنانچہ ایسا ہی ہوا، لوگوں نے انہیں ان کے حال پر چھوڑ دیا اور میلے میں شرکت کے لیے چلے گئے۔ ابراہیم علیہ السلام بتوں کے پاس پہنچے اور ان کامذاق اُڑاتے ہوئے کہا کہ اگر تم عبادت کے مستحق ہوتو تمہارے سامنے اتنے سارے کھانے رکھے ہیں انہیں کیوں نہیں کھاتے ہو، لیکن بتوں نے نہ کھانا کھایا اور نہ ان کی بات کا جواب دیا تو ابراہیم علیہ السلام کہنے لگے کہ اے بتو! تم بولتے کیوں نہیں ہو؟ ! پھر اپنے دائیں ہاتھ میں موجود کلہاڑی سے انہیں مار مار کر ان کے ٹکڑے ٹکڑے کر دیے۔ مشرکین جب شام کواپس آئے اور اپنے معبودوں کا حالِ زار دیکھا تو فوراً ابراہیم علیہ السلام کے پاس پہنچے اور ان سے پوچھ تاچھ کرنے لگے۔ ابراہیم علیہ السلام نے اپنے دفاع میں کہا کہ یہ کیسی تمہاری کور مغزی ہے کہ جن بتوں کو تم اپنے ہاتھوں سے تراشتے ہو انہی کی پوجا کرتے ہو، حالانکہ تمہارا اور تمہارے معبودوں کا خالق اللہ ہے، اس لیے عبادت کا مستحق بھی صرف وہی ہے۔"],[6154,"§قوم ابراہیم اور جشن نوروز\nجب سورج برج حمل میں داخل ہوتا تو اس دن یہ قوم جشنِ نو روز مناتی تھی۔ اس پکنک کے لیے زور شور سے تیاریاں شروع ہو گئیں۔ علی الصبح لوگوں نے اچھے اچھے کھانے پکائے کچھ کھائے کچھ مندروں میںبتوں کے سامنے نیاز کے طور پر رکھ دیے۔ اور نور کے تڑکے میلہ میں شمولیت کے لیے روانہ ہونے لگے تو سیدنا ابراہیم علیہ السلام کو اس میں شمولیت کی دعوت دی بلکہ ساتھ لے جانے پر اصرار کیا۔ سیدنا ابراہیم علیہ السلام ان کی بے ہودگیوں میں قطعاً شامل نہ ہونا چاہتے تھے۔ آپ کو فوراً ایک ترکیب سوجھی جو قوم کے مزاج کے موافق تھی۔ آپ نے ستاروں میں نظر ڈالی پھر کہنے لگے کہ میں تو آج بیمار ہونے والا ہوں۔ قوم نے اپنے اعتقاد کے مطابق اس عذر کو معقول سمجھا اور انہیں چھوڑنے پر رضا مند ہو گئے۔"],[6155,"§سیدنا براہیم علیہ السلام کا بتوں کوتوڑ پھوڑ دینا\nاللہ ہی بہتر جانتا ہے کہ سیدنا ابراہیم علیہ السلام کتنی مدت سے ایسے موقعہ کے منتظر تھے۔ ادھر قوم کے لوگ میلہ منانے چلے گئے ادھر آپ سب سے بڑے مندر کا دروازہ کھول کر اس میں داخل ہو گئے۔ بتوں کی طرف غصہ سے متوجہ ہوکر کہنے لگے۔ بدبختو!تمہارے سامنے مٹھائیاں اور کھانے پڑے ہیں انہیں کھاتے کیوں نہیں ؟ کچھ بولو تو سہی، کچھ جواب تو دو ؟ ان بے جان پتھروں نے کیا جواب دینا تھا۔ اس پر سیدنا ابراہیم علیہ السلام کو اور بھی زیادہ غصہ آیا۔ ایک کلہاڑا لیا۔ اور سب بتوں کو خوب جی بھر کے ضربیں لگانا شروع کیں۔ سب کو توڑ پھوڑ دیا۔ البتہ سب سے بڑے بت کو چھوڑدیا۔ اس کے کندھے پر کلہاڑا رکھ دیاتاکہ یہ معلوم ہو کہ یہ سب اس بڑے بت کی کارستانی ہے پھر مندر کا دروازہ بند کرکے باہر نکل آئے۔"],[6156,"§سیدنا ابراہیم علیہ السلام سے قوم کا سوال وجواب\nمیلہ سے واپسی پر قوم نے جب اپنے معبودوں کا یہ حشر دیکھا تو ان کا پارا بہت چڑھ گیا وہ پہلے ہی جانتے تھے کہ ہمارے بتوں کی مخالفت صرف ابراہیم علیہ السلام ہی کرتا رہتا تھا اور وہ پیچھے بھی رہ گیا تھا۔ لہٰذا یہ اسی کا کارنامہ ہو سکتا ہے۔ چنانچہ ان کے پاس دوڑتے آئے اور معبودوں سے اس طرح کی بدسلوکی کی وجہ پوچھی تو آپ علیہ السلام نے کہا کہ بڑے بت سے کیوں نہیں پوچھتے۔ جس کے کندھے پر کلہاڑا ہے۔ شاید اس نے ہی اپنے چھوٹوں سے ناراض ہو کر ان کا یہ حشر کر دیا ہو۔ پھر ساتھ ہی کہہ دیا کہ یہ پتھر کے بے جان بت جو اپنی حفاظت نہیں کر سکتے تمہارا کیا سنوار سکتے ہیں اور تم لوگ جو ان کی عبادت کرتے ہو اس کا فائدہ کیا ہے۔ پھر یہ بت تم نے خود ہی تراش رکھے ہیں علاوہ ازیں تم کو اور اس پتھر کو بھی اللہ نے پیدا کیا ہے اور یہ بت تو مخلوق درمخلوق کی حیثیت رکھتے ہیں۔ اور عبادت کی مستحق تو وہ ہستی ہو سکتی ہے جو خالق ہو۔ یہ مخلوق درمخلوق کیسے مستحق ہوسکتی ہے ؟"],[6157,"§سیدنا ابراہیم علیہ السلام کو آگ کے الاؤ میں پھینکنا\nسیدنا ابراہیم علیہ السلام کے دلائل کا جواب تو کسی کے پاس تھانہیں۔ لہٰذا وہ اوچھے ہتھیاروں پر اُتر آئے اور کہنے لگے، اپنے معبودوں کے گستاخ کو ایسی قرار واقعی سزا دو جس سے دوسروں کو عبرت حاصل ہو۔ چنانچہ بالاتفاق طے ہو اکہ ایک بہت بڑا الاؤ تیار کیا جائے اور اس میں سیدنا ابراہیم علیہ السلام کو پھینک کر زندہ جلا دیا جائے۔ چنانچہ ان لوگوں نے حسب تجویز بہت بڑا الاؤ تیار کیا اور سیدنا ابراہیم علیہ السلام کو اس میں پھینک دیا۔ اللہ نے آگ کو حکم دیا کہ ابراہیم علیہ السلام کو کسی قسم کا گزند نہ پہنچنے پائے۔ چنانچہ آپ صحیح سلامت اس آگ سے باہر نکل آئے۔ اس طرح آپ تو اس بھاری آزمائش میں پوری طرح کامیاب ہو گئے اور قوم کو پہلے سے بھی زیادہ رسوا ہونا پڑا۔\nآسمان پر غوروفکر کے لیے دیکھا جیسا کہ بعض لوگ ایسا کرتے ہیں۔ یا اپنی قوم کے لوگوں کو مغالطے میں ڈالنے کے لیے ایسا کیا، جو کہ ستاروں کی گردش کو حوادث زمانہ میں مؤثر مانتے تھے۔ یہ واقعہ اس وقت کا ہے کہ جب ان کی قوم کا وہ دن آیا، جسے وہ باہر جا کر بطور عید اور قومی تہوار منایا کرتی تھی۔ قوم نے سیّدنا ابراہیم علیہ السلام کو بھی ساتھ چلنے کی دعوت دی۔ لیکن ابراہیم تنہائی اور موقعے کی تلاش میں تھے، تاکہ ان کے بتوں کا تیاپانچہ کیا جا سکے۔ چنانچہ انہوں نے یہ موقع غنیمت جانا کہ کل ساری قوم باہر میلے میں چلی جائے گی تو میں اپنا منصوبہ بروئے کار لے آئوں گا۔ اور کہہ دیا کہ میں بیمار ہوں یا آسمانوں کی گردش بتلاتی ہے کہ میں بیمار ہونے والا ہوں۔ یہ بات بالکل جھوٹی تو نہیں تھی، ہر انسان کچھ نہ کچھ بیمار ہوتا ہی ہے، علاوہ ازیں قوم کا شرک سیّدنا ابراہیم علیہ السلام کے دل کا ایک مستقل روگ تھا، جسے دیکھ کر وہ کڑھتے رہتے تھے۔ یوں سیّدنا ابراہیم علیہ السلام نے تعریض اور توریہ کا اظہار فرمایا جو اگرچہ جھوٹ نہیں ہوتا لیکن مخاطب اس کے متبادر مفہوم سے مغالطے کا شکار ہو جاتا ہے۔ اس لیے حدیث ثلاث کذبات میں اسے جھوٹ سے تعبیر کیا گیا ہے، جیسا کہ اس کی ضروری تفصیل سورئہ انبیاء-63 میں گزر چکی ہے۔\nفَنَظَرَ نَظْرَةً فِي النُّجُوْمِ: انھیں اس لیے ڈانٹ پلائی کہ انھوں نے اللہ پاک کے سو اکواپنا معبود بنا رکھا ہے جب کہ وہ بت جن کی وہ عبادت کررہے ہیں وہ نفع و نقصان کا اختیار نہیں رکھتے ہیں اس کے ساتھ ساتھ انھوں نے ارادہ کیا کہ وہ بت خانہ میں تنہائی میں جائے اور سب بتوں کو توڑ پھوڑ دے چنانچہ اس پروگرام میں خود کو کامیاب بنانے کے لیے اس نے حیلہ کیا کہ ان کے عید کے دن ان کے ساتھ خود کو شریک نہ کرے چنانچہ ابراہیم علیہ السلام نے ان کی عادت کے مطابق آسمان کی جانب دیکھا جب کہ قوم علم نجو م کے ساتھ وابستہ تھی تو ابراہیم علیہ السلام نے ان کے ساتھ عید میں شرکت کے لیے حیلہ اختیار کیا ستارے بتا رہے ہیں کہ میں مستقبل میں بیماری کی زد میں آجاؤں گا اگر میں تمہارے ساتھ چلوں گا اور یہ جھوٹ نہ تھا تعریض کی ایک شکل تھی جو کسی شرعی مقصود کے پیش نظر اختیار کی جاتی ہے اس میں ہرگز گناہ نہیں ہے جیسا کہ وارد ہے، اِنَّ فِی الْمَعَارِضِ لَمَنْدُوْحَـۃٌ مِنَ الْـکَـذِبِ، تعریض کی صورت میں جھوٹ سے بچائو ہے یا ان کا مقصود یہ تھا کہ بتوں کی عبادت کے باعث ان کے دل بیمار ہیں چنانچہ اس وجہ سے انھوں نے اس کو وہاں چھوڑ دیا اور خود عید کی جانب روانہ ہوگئے تو جب وہ عید منانے چلے گئے اور ابراہیم علیہ السلام کو وہیں چھوڑ گئے تو وہ درپردہ بتوں کی جانب متوجہ ہوئے ان کے قریب جاکر ان سے کہاتم ان کھانوں کو تناول کیوں نہیں کرتے ہو ؟ جب کہ بتوں کے پجاریوں کے ان کے سامنے تقریب کے لیے کھانے رکھے ہوئے تھے اور تمہیں کیا ہوگیا ہے کہ تم میرے سوالات کے جواب نہیں دے رہے ہو؟ یہ سب کچھ استہزاء کی کیفیت تھی کہ یہ تمہارے خدا تو تمہارے مقام سے بھی نیچے ہیں جب کہ تم گفتگو کررہے ہوخوردونوش کو تناول کررہے ہو جب کہ یہ تو ان سب باتوں سے بیخبر ہیں انھیں کچھ معلوم نہیں۔\nفَرَاغَ اِلٰۤى اٰلِهَتِهِمْ فَقَالَ اَلَا تَاْكُلُوْنَ : چنانچہ ابراہیم علیہ السلام درپردہ بتوں کے قریب گئے دائیں ہاتھ کے ساتھ ان پر کلہاڑا چلا رہے تھے انھیں توڑ پھوڑ رہے تھے دائیں ہاتھ میں چونکہ بائیں ہاتھ سے قوت زیادہ ہوتی ہے اس لیے قرآن پاک میں دائیں ہاتھ کا ذکر ہے اور اس کی ضرب میں زور زیادہ ہوتا ہے اس کیفیت کا مشاہدہ کرتے ہی بتوں کے پجاری تیز رفتاری کے ساتھ ابراہیم علیہ السلام کی جانب متوجہ ہوئے ان کی کیفیت دیدنی تھی وہ بتوں کو تحفظ دینے کے لیے چلتے ہوئے ایک دوسرے کو دھکے دے رہے تھے کہ ہم جس قدر جلد ممکن ہو وہاں بجلی بن کر پہنچ جائیں جب وہاں پہنچے تو انھوں نے ابراہیم علیہ السلام کو اپنی جانب متوجہ کرتے ہوئے کہا تجھ پر سخت افسوس ہے کہ ہم تو ان کو اپنا معبود حاجت روا سمجھتے ہیں اور تو انھیں توڑ پھوڑ رہا ہے ان کے اس کہنے پر ابراہیم علیہ السلام نے انھیں ڈانٹ پلاتے ہوئے کہا تعجب ہے تم ان بتوں کی عبادت کررہے ہو جن کو تم نے پتھروں سے تراش تراش کرکے بنایا ہے ان کے بنانے میں تمہارے ہاتھوں کا دخل ہے جب کہ اللہ بزرگ و برتر نے تمہیں پیدا کیا ہے بلکہ تمہاری سب کاروائیوں کا خالق بھی وہی ہے اور یہ بھی حقیقت ہے کہ سب چیزوں کا خالق وہی ہے تو تم پر تعجب ہے اور حیرت دامن کو تھام لیتی ہے کہ تم کائنات کے خالق کی عبادت کو چھوڑ کر اس کی مخلوق کی عبادت کرتے ہو معلوم ہوتا ہے کہ تم سمجھ بوجھ سے بالکل عاری ہو۔ ذہن نشین کریں کہ اس آیت کے مفہوم سے یہ حقیقت اظہر من الشمس ہورہی ہے کہ بندوں کے افعال کا خالق بھی وہی ہے اگرچہ کام کرنے کے لحاظ سے لوگ فاعل ہیں جب کہ بعض اہل علم بیان کرتے ہیں کہ اللہ تعالیٰ تمہارا اور تمہارے بتوں کا خالق ہے جن کو تم بنا رہے ہو کلام کا سیاق اس کا متقاضی ہے نیز بتوں کی عبادت کرنے والوں کے خلاف دلیل کے لحاظ سے زیادہ مضبوط ہے۔\nقَالُوا ابْنُوْا لَهٗ بُنْيَانًا : بتوں کے پجاریوں نے کہا اس شخص کے لیے ایک عمارت تعمیر کرو اور اس میں آگ مشتعل کرو اور پھر اس بھڑکتی ہوئی آگ میں اس کو گراؤ مفسرین بیان کرتے ہیں جب دلیل کی روشنی میں ابراہیم علیہ السلام کو ان پر غلبہ حاصل ہوگیا تو انھوں نے جسمانی قوت کے ساتھ ان پر غلبہ کرنا چاہا کہ اس کو گرفت میں لیا جائے اور مشورہ کیا کہ اس کو بھڑکتی ہوئی آگ میں گرادیا جائے اس طرح کرنے سے شاید ہم اپنے بتوں پرا س کی ہرزہ سرائی کا بدلہ لے سکیں اور ایک گونہ ہمیں اطمینان حاصل ہوجائے انھوں نے ابراہیم علیہ السلام کے خلاف مکر کیا اس کو موت کے گھاٹ اتاردیا جائے لیکن ہم نے اس کو بھڑکتی ہوئی آگ سے تحفظ عطا کیا ہم نے ان پر آگ کو ٹھنڈ اور سلامتی والا بنادیا اور مخالفین کو مغلوب بلکہ ذلیل کیا جب وہ اپنے مکر میں کامیاب نہ ہوسکے۔\nوَ قَالَ اِنِّيْ ذَاهِبٌ اِلٰى رَبِّيْ سَيَهْدِيْنِ۰۰۹۹ رَبِّ هَبْ لِيْ مِنَ الصّٰلِحِيْنَ۰۰۱۰۰\nفَبَشَّرْنٰهُ بِغُلٰمٍ حَلِيْمٍ۰۰۱۰۱ فَلَمَّا بَلَغَ مَعَهُ السَّعْيَ قَالَ يٰبُنَيَّ اِنِّيْۤ اَرٰى فِي\nالْمَنَامِ اَنِّيْۤ اَذْبَحُكَ فَانْظُرْ مَا ذَا تَرٰى ١ؕ قَالَ يٰۤاَبَتِ افْعَلْ مَا تُؤْمَرُ١ٞ\nسَتَجِدُنِيْۤ اِنْ شَآءَ اللّٰهُ مِنَ الصّٰبِرِيْنَ۰۰۱۰۲ فَلَمَّاۤ اَسْلَمَا وَ تَلَّهٗ لِلْجَبِيْنِۚ۰۰۱۰۳\nوَنَادَيْنٰهُ اَنْ يّٰۤاِبْرٰهِيْمُ۠ۙ۰۰۱۰۴ قَدْ صَدَّقْتَ الرُّءْيَا١ۚ اِنَّا كَذٰلِكَ نَجْزِي\nالْمُحْسِنِيْنَ۰۰۱۰۵ اِنَّ هٰذَا لَهُوَ الْبَلٰٓؤُا الْمُبِيْنُ۰۰۱۰۶ وَ فَدَيْنٰهُ بِذِبْحٍ عَظِيْمٍ۰۰۱۰۷ وَ تَرَكْنَا\nعَلَيْهِ فِي الْاٰخِرِيْنَۖ۰۰۱۰۸ سَلٰمٌ عَلٰۤى اِبْرٰهِيْمَ۰۰۱۰۹ كَذٰلِكَ نَجْزِي الْمُحْسِنِيْنَ۰۰۱۱۰ اِنَّهٗ\nمِنْ عِبَادِنَا الْمُؤْمِنِيْنَ۰۰۱۱۱ وَ بَشَّرْنٰهُ بِاِسْحٰقَ نَبِيًّا مِّنَ الصّٰلِحِيْنَ۰۰۱۱۲ وَ بٰرَكْنَا عَلَيْهِ\nوَ عَلٰۤى اِسْحٰقَ١ؕ وَ مِنْ ذُرِّيَّتِهِمَا مُحْسِنٌ وَّ ظَالِمٌ لِّنَفْسِهٖ مُبِيْنٌؒ۰۰۱۱۳\nاوراس نے کہا: بے شک میں اپنے رب کی طرف جانے والا ہوں، یقیناً وہ میری رہنمائی فرمائے گا\nاے میرے رب ! مجھے (بیٹا) عطا فرما جو صالحین میں سے ہو\nچنانچہ ہم نے اسے بہت حلم والے لڑکے کی بشارت دی\nپھر جب وہ (لڑکا) اس کے ساتھ بھاگنے (کی عمر) کو پہنچا تو اس نے کہا: اے میرے پیارے بیٹے ! بے شک میں خواب میں دیکھتا ہوں کہ میں تجھے یقیناً ذبح کر رہا ہوں، اب تو دیکھ ! تیری کیا رائے ہے ؟ اس (بیٹے) نے کہا: اباجان! جو آپ کوحکم دیا گیا ہے کر گزریں، اگر اللہ نے چاہا تو عنقریب آپ مجھے صبر کرنے والوں میں سے پائیں گے\nپھر جب دونوں مطیع ہو گئے اور اس (باپ) نے اس (بیٹے) کو پیشانی کی ایک جانب لٹا دیا\nتو نے اپنا خواب یقیناً سچ کر دکھایا، بے شک ہم نیکوکاروں کو اسی طرح بدلہ دیتے ہیں\nاور ہم نے اس (اسمٰعیل علیہ السلام) کے بدلے میں ایک عظیم القدر (جانور) ذبح کرنے کو دیا\nاور ہم نے اس (کے ذکر خیر)کو پیچھے آنے والوں میں باقی رکھا\nاور ہم نے اس (ابراہیم علیہ السلام) کو اسحٰق (بیٹے) کی بشارت دی، جو صالح لوگوں میں سے نبی ہوگا\nاور ہم نے اس پر اسحٰق پر برکت نازل کی اور ان\nدونوں کی اولاد میں سے کوئی نیکی کرنے والا اور کوئی اپنے آپ پر کھلم کھلا ظلم کرنے والا ہے"],[6158,"§سیّدنا ابراہیم علیہ السلام کی ہجرت اور آزمائش\nاللہ تعالیٰ نے اپنے خلیل علیہ السلام کے بارے میں فرمایا ہے کہ جب اللہ تعالیٰ نے انہیں ان کی قوم کے مقابلے میں فتح ونصرت سے نوازا اور وہ اپنی قوم سے مایوس ہو گئے کہ وہ اتنی عظیم الشان نشانیوں کو دیکھنے کے بعد بھی ایمان نہیں لائی تو آپ نے ہجرت کا ارادہ کر لیا اور فرمایا: ﴿اِنِّيْ ذَاهِبٌ اِلٰى رَبِّيْ سَيَهْدِيْنِ۰۰۹۹رَبِّ هَبْ لِيْ مِنَ الصّٰلِحِيْنَ۰۰۱۰۰﴾ ’’بے شک میں اپنے پروردگار کی طرف جانے والا ہوں، یقیناً وہ میری رہنمائی فرمائے گا، اے پروردگار! مجھے نیکو کاروں میں سے (اولاد) عطا فرما۔‘‘ یعنی قوم اور اعزہ واقارب کو جو چھوڑا ہے تو ان کے بدلے میں مجھے اولاد عطا فرما جو تیری اطاعت گزار ہو، اللہ تعالیٰ نے فرمایا ہے: ﴿فَبَشَّرْنٰهُ بِغُلٰمٍ حَلِيْمٍ۰۰۱۰۱﴾ ’’پھر ہم نے اسے ایک بردبار لڑکے کی خوش خبری دی۔‘‘ اس لڑکے سے مراد اسماعیل علیہ السلام ہیں کیونکہ یہ پہلے بیٹے تھے جن کی ابراہیم علیہ السلام کو بشارت دی گئی تھی، تمام مسلمانوں اور اہل کتاب کا اتفاق ہے کہ یہ سیّدنا اسحاق سے بڑے تھے بلکہ اہل کتاب کی نص کے مطابق اسماعیل علیہ السلام کی ولادت کے وقت سیّدنا ابراہیم علیہ السلام کی عمر چھیاسی سال تھی اور جب اسحاق علیہ السلام پیدا ہوئے تو اس وقت سیّدنا ابراہیم علیہ السلام ننانوے برس کے تھے، اہل کتاب کی کتابوں میں یہ بھی لکھا ہوا ہے کہ اللہ تبارک وتعالیٰ نے ابراہیم علیہ السلام کو حکم دیا تھا کہ وہ اپنے اکلوتے بیٹے کو ذبح کر دیں اور ایک دوسرے نسخے میں ہے کہ اپنے پلوٹھے بیٹے کو ذبح کر دیں اور اس کے باوجود انہوں نے اس کے بعد کذب اور بہتان سے کام لیتے ہوئے یہاں اسحاق کا لفظ داخل کر دیا۔ (کتاب مقدس پیدائش، باب،22، آیت:2) اور یہ قطعاً درست نہیں کیونکہ یہ تو ان کی اپنی کتاب کی نص کے بھی خلاف ہے، انہوں نے یہاں اسحاق کے لفظ کو اس لیے داخل کیا کہ اسحاق علیہ السلام ان کے باپ تھے، جبکہ اسماعیل علیہ السلام عربوں کے باپ تھے۔ تو انہوں نے عربوں سے حسد سے کام لیتے ہوئے اس لفظ کا اضافہ کر دیا اور ’’اپنے اکلوتے‘‘ کی اس طرح تحریف کی کہ اپنے اس بیٹے کو ذبح کر دو جس کے سوا اور کوئی اس وقت تمہارے پاس موجود نہیں ہے کیونکہ اسماعیل اور ان کی والدہ کو آپ مکہ مکرمہ میں لے گئے تھے، مگر یہ ایک سراسر باطل تاویل اور تحریف ہے کیونکہ اکلوتا اسے کہا جاتا جس کے سوا کوئی اور نہ ہو اور پھرپہلا بیٹا جس قدر عزیز ہوتا ہے بعد والی اولاد اس قدر عزیز نہیں ہوتی، لہٰذا پہلے بیٹے کے ذبح کر دینے کے حکم میں زیادہ ابتلاء و آزمائش تھی۔\nارشاد باری تعالیٰ ہے: ﴿فَلَمَّا بَلَغَ مَعَهُ السَّعْيَ ﴾ ’’پھر جب وہ اس کے ساتھ بھاگنے دوڑنے (کی عمر) کو پہنچا۔‘‘ یعنی بڑا ہو گیا اور پروان چڑھ گیا اور اپنے باپ کے ساتھ آنے جانے اور چلنے لگا۔ سیّدنا ابراہیم علیہ السلام اپنے بیٹے اور اس کی والدہ کی خیریت معلوم کرنے کے لیے اکثر بلادِ فاران میں جاتے رہتے تھے اور ان کی ضروریات کا خیال رکھتے تھے۔ بیان کیا جاتا ہے کہ آپ براق پر سوار ہو کر تشریف لاتے اور یہاں بہت جلد پہنچ جایا کرتے تھے۔ واللہ اعلم۔ (تاریخ الیعقوبی، ابراہیم:25/1) ابن عباس رضی اللہ عنہما، مجاہد، عکرمہ، سعید بن جبیر، عطاء خراسانی، زید بن اسلم اور دیگر کئی ائمہ تفسیر رحمہ اللہ نے ﴿فَلَمَّا بَلَغَ مَعَهُ السَّعْيَ ﴾ کے بارے میں لکھا ہے کہ اس کا مفہوم یہ ہے کہ جب اسماعیل جوان ہو گئے اور اپنے باپ کی طرح سعی وعمل کے قابل ہوئے۔ (تفسیر الطبری:91/23) ﴿فَلَمَّا بَلَغَ مَعَهُ السَّعْيَ قَالَ يٰبُنَيَّ اِنِّيْۤ اَرٰى فِي الْمَنَامِ اَنِّيْۤ اَذْبَحُكَ فَانْظُرْ مَا ذَا تَرٰى ١ؕ ﴾ ’’جب وہ اس کے ساتھ بھاگنے دوڑنے (کی عمر) کو پہنچا تو اس نے کہا: اے میرے بیٹے! بے شک میں خواب میں دیکھتا ہوں کہ میں تجھے یقیناً ذبح کر رہا ہوں، اب تو دیکھ! تیری کیا رائے ہے؟ـ‘‘ عبید بن عمیر رحمہ اللہ کہتے ہیں کہ انبیائے کرام کے خواب وحی ہوتے ہیں اور پھر انہوں نے اپنی اس بات کی تائید میں اسی آیت کریمہ کی تلاوت کی۔ (تفسیر الطبری:93/23) آپ نے بیٹے کو اس لیے بتا دیا تا کہ اس کے لیے زیادہ آسانی ہو جائے، نیز آپ اس کے صبر وشجاعت اور صغرسنی کے باوجود اس کی اللہ تعالیٰ کی اطاعت اور اپنے والد کی اطاعت کے عزم وارادہ کی آزمائش کر سکیں۔ ﴿قَالَ يٰۤاَبَتِ افْعَلْ مَا تُؤْمَرُ١ٞ﴾ ’’اس نے کہا: اے میرے ابا جان! آپ کو جو حکم دیا گیا ہے کر گزریں۔‘‘ اس حکم الٰہی کی اطاعت بجا لائیں، ﴿سَتَجِدُنِيْۤ اِنْ شَآءَ اللّٰهُ مِنَ الصّٰبِرِيْنَ۰۰۱۰۲﴾ ’’اگر اللہ نے چاہا تو عنقریب آپ مجھے صبر کرنے والوں میں سے پائیں گے۔‘‘ یعنی میں صبر کروں گا اور اللہ تعالیٰ سے اس کے اجروثواب کا طلب گار ہوں گا اور انہوں نے جو وعدہ کیا اسے واقعی سچ ثابت کر دکھایا صَلَوَاَتُ اللہِ وَسَلَامُہٗ عَلَیْہِاسی لیے تو اللہ تعالیٰ نے ان کے بارے میں فرمایا ہے: ﴿وَ اذْكُرْ فِي الْكِتٰبِ اِسْمٰعِيْلَ١ٞ اِنَّهٗ كَانَ صَادِقَ الْوَعْدِ وَ كَانَ رَسُوْلًا نَّبِيًّاۚ۰۰۵۴وَ كَانَ يَاْمُرُ اَهْلَهٗ بِالصَّلٰوةِ وَ الزَّكٰوةِ١۪ وَ كَانَ عِنْدَ رَبِّهٖ مَرْضِيًّا۰۰۵۵﴾ (مریم:54،55) ’’اور کتاب میں اسماعیل کا ذکر کریں، وہ وعدے کے سچے اور رسول (اور) نبی تھے اور اپنے گھر والوں کو نماز اور زکاة کا حکم دیتے تھے اور اپنے پروردگار کے ہاں نہایت پسندیدہ (اور برگزیدہ) تھے۔‘‘\nارشاد باری تعالیٰ ہے: ﴿فَلَمَّاۤ اَسْلَمَا وَ تَلَّهٗ لِلْجَبِيْنِۚ۰۰۱۰۳﴾ ’’چنانچہ جب دونوں نے حکم مان لیا اور اس (باپ) نے اسے (بیٹے کو) ماتھے کی ایک جانب پر لٹا دیا۔‘‘ یعنی جب دونوں نے کلمہ شہادت پڑھا اور اللہ تعالیٰ کا ذکر کیا، سیّدنا ابراہیم علیہ السلام نے ذبح کرنے کے لیے اور سیّدنا اسماعیل علیہ السلام نے شہادت کی موت کے لیے۔ اور یہ بھی کہا گیا ہے کہ ﴿اَسْلَمَا ﴾ کے معنی یہ ہیں کہ جب دونوں مطیع وفرماں بردار ہو گئے، سیّدنا ابراہیم علیہ السلام اللہ تعالیٰ کا حکم بجا لانے کے لیے اور سیّدنا اسماعیل علیہ السلام اللہ تعالیٰ کے حکم کی اطاعت اور اپنے باپ کی فرماں برداری کے لیے، یہ امام مجاہد، عکرمہ، قتادہ، سدی، ابن اسحاق اور دیگر ائمہ تفسیر رحمہ اللہ کا قول ہے۔ (تفسیر الطبری:93/23،94) ﴿وَ تَلَّهٗ لِلْجَبِيْنِۚ۰۰۱۰۳﴾ ’’کے معنی یہ ہیں کہ ابراہیم علیہ السلام نے اسماعیل علیہ السلام کو چہرے کے بل لٹا دیا تا کہ گدی کی طرف سے ذبح کر دیں اور بوقت ذبح ان کے چہرے کو نہ دیکھیں تا کہ ان کے لیے ذبح کرنے میں آسانی ہو۔ ابن عباس رضی اللہ عنہما، مجاہد، سعید بن جبیر، ضحاک اور قتادہ رحمہ اللہ نے کہا ہے کہ سیّدنا ابراہیم علیہ السلام نے اسماعیل علیہ السلام کو چہرے کے بل لٹا دیا تھا۔ (تفسیر ابن أبی حاتم:3224/10)\nامام احمد رحمہ اللہ نے سیّدنا ابن عباس رضی اللہ عنہما سے روایت کیا ہے کہ جب سیّدنا ابراہیم علیہ السلام کو مناسک کا حکم دیا گیا تو شیطان سعی کرنے کی جگہ پر آپ کے سامنے آیا اور اس نے آپ سے سبقت لے جانے کی کوشش کی مگر ابراہیم علیہ السلام شیطان سے سبقت لے گئے، پھر جبریل علیہ السلام آپ کو جمرہ عقبہ کے پاس لے گئے تو شیطان آپ کے سامنے آیا تو آپ نے اسے سات کنکریاں ماریں حتیٰ کہ وہ چلا گیا، پھر وہ جمرہ وسطیٰ کے پاس آپ کے سامنے آیا تو آپ نے اسے سات کنکریاں ماریں، پھر آپ نے اسماعیل علیہ السلام کو ماتھے کی ایک جانب پر لٹا دیا، اسماعیل علیہ السلام نے سفید رنگ کی قمیص پہنی ہوئی تھی، انہوں نے عرض کی ابا جان! کوئی اور کپڑا نہیں ہے جس میں آپ مجھے کفن دیں، لہٰذا میری قمیص اتار لیں تا کہ اسے میرے کفن کے لیے استعمال کر سکیں، سیّدنا ابراہیم علیہ السلام جب ان کی قمیص اتارنے لگے تو پیچھے سے آواز آئی: ﴿اَنْ يّٰۤاِبْرٰهِيْمُ۠ۙ۰۰۱۰۴قَدْ صَدَّقْتَ الرُّءْيَا١ۚ ﴾ ’’اے ابراہیم! تحقیق تو نے (اپنا) خواب سچ کر دکھایا۔‘‘ ابراہیم نے پیچھے لپٹ کر دیکھا تو آپ کے پیچھے سینگوں والا، سفید رنگ اور موٹی موٹی آنکھوں والا ایک مینڈھا کھڑا تھا۔ ابن عباس رضی اللہ عنہما کہتے ہیں کہ میں نے دیکھا کہ ہم لوگ قربانی کے لیے اسی قسم کے مینڈھے تلاش کیا کرتے تھے۔ (مسند أحمد) مناسک کے باب میں اس حدیث کو مکمل طور پر بیان کیا گیا ہے۔ (السنن الکبریٰ:135/5،154) ﴿وَ نَادَيْنٰهُ اَنْ يّٰۤاِبْرٰهِيْمُ۠ۙ۰۰۱۰۴قَدْ صَدَّقْتَ الرُّءْيَا١ۚ ﴾ ’’اور ہم نے اسے پکارا کہ اے ابراہیم! تو نے (اپنا) خواب سچ کر دکھایا۔‘‘ کہ تم نے جب ذبح کرنے کے لیے اپنے بیٹے کو لٹا دیا تو اس سے تمہارے خواب کا مقصود حاصل ہو گیا۔ سدّی رحمہ اللہ وغیرہ نے ذکر کیا ہے کہ آپ نے اسماعیل علیہ السلام کی گردن پر چھری پھیری مگر چھری نے ایک بال بھی نہ کاٹا بلکہ چھری اور اسماعیل علیہ السلام کے درمیان پیتل کا ایک تختہ حائل ہو گیا اور اس وقت ابراہیم علیہ السلام کو یہ آواز دی گئی کہ تم نے خواب سچ کر دکھایا۔ ﴿اِنَّا كَذٰلِكَ نَجْزِي الْمُحْسِنِيْنَ۰۰۱۰۵﴾ ’’بے شک ہم نیکو کاروں کو ایسے ہی بدلہ دیا کرتے ہیں۔‘‘ یعنی جو لوگ ہماری اطاعت کریں شدائد ومشکلات کو ہم ان سے اسی طرح دور کر دیا کرتے اور ان کے لیے آسانی وسہولت پیدا کر دیا کرتے ہیں جیسا کہ اللہ جل جلالہٗ نے ارشاد فرمایا ہے: ﴿وَ مَنْ يَّتَّقِ اللّٰهَ يَجْعَلْ لَّهٗ مَخْرَجًاۙ۰۰۲وَّ يَرْزُقْهُ مِنْ حَيْثُ لَا يَحْتَسِبُ١ؕ وَ مَنْ يَّتَوَكَّلْ عَلَى اللّٰهِ فَهُوَ حَسْبُهٗ١ؕ اِنَّ اللّٰهَ بَالِغُ اَمْرِهٖ١ؕ قَدْ جَعَلَ اللّٰهُ لِكُلِّ شَيْءٍ قَدْرًا۰۰۳﴾ (الطلاق:2،3) ’’اور جو شخص اللہ سے ڈرے تو وہ اس کے لیے (رنج و حزن سے) نکلنے کا راستہ بنا دیتا ہے اور وہ اسے ایسی جگہ سے رزق دیتا ہے جہاں سے اسے گمان تک نہیں ہوتا۔ اور جو شخص اللہ پر بھروسا رکھے تو وہ اس کے لیے کافی ہے، بے شک اللہ اپنے کام کو (جو وہ کرنا چاہتا ہے) پورا کر کے رہتا ہے۔ یقینا اللہ نے ہر چیز کے لیے اندازہ مقرر کر رکھا ہے۔‘‘\nاس آیت کریمہ اور اس میں مذکور قصے سے علماء اصول کی ایک جماعت نے یہ استدلال کیا ہے کہ حکم عملی طور پر سر انجام دیے جانے سے قبل بھی منسوخ ہو سکتا ہے اور یہ آیت کریمہ اس بات کی واضح دلیل ہے جبکہ معتزلہ کی ایک جماعت کا موقف اس کے خلاف ہے، حالانکہ یہ صاف ظاہر ہے کہ اللہ تعالیٰ نے سیّدنا ابراہیم علیہ السلام کو اپنے بیٹے کو ذبح کر دینے کا حکم دیا اور پھر اسے منسوخ کر کے فدیے کے طور پر مینڈھا بھیج دیا اور اس حکم سے مقصود یہ تھا کہ اپنے بیٹے کو ذبح کر دینے کے سلسلے میں سیّدنا ابراہیم علیہ السلام کے صبر اور عزم کو پختہ تر کر دیا جائے، اسی لیے اللہ تعالیٰ نے ارشاد فرمایا: ﴿اِنَّ هٰذَا لَهُوَ الْبَلٰٓؤُا الْمُبِيْنُ۰۰۱۰۶﴾ ’’بلاشبہ یہ تو صریح آزمائش ہی تھی۔‘‘ یعنی یہ ایک بہت بڑی آزمائش تھی کہ آپ کو اپنے لخت جگر اور نور نظر کو ذبح کر دینے کا حکم دیا گیا تو آپ اپنے رب تعالیٰ کا حکم بجا لانے کے لیے فوراً تیار ہو گئے، اسی لیے تو اللہ تعالیٰ نے فرمایا ہے: ﴿وَ اِبْرٰهِيْمَ الَّذِيْ وَفّٰۤىۙ۰۰۳۷﴾ (النجم:37) ’’اور وہ ابراہیم جنہوں نے (حق طاعت ورسالت) پورا کیا۔‘‘ ارشاد باری تعالیٰ ہے: ﴿وَ فَدَيْنٰهُ بِذِبْحٍ عَظِيْمٍ۰۰۱۰۷﴾ ’’اور ہم نے اس کے بدلے میں ایک بڑی قربانی دی۔‘‘ سیّدنا ابن عباس رضی اللہ عنہما سے روایت ہے کہ یہ ایک ایسا مینڈھا تھا جو جنت میں چالیس سال تک چرتا رہا تھا۔ (تفسیر الطبری: 105/23)\nامام احمد رحمہ اللہ نے صفیہ بنت شیبہ رضی اللہ عنہا سے روایت کیا ہے، انہوں نے کہا کہ مجھے بنو سلیم کی ایک عورت نے خبر دی، جس نے ہمارے گھر کے اکثر لوگوں کو جنوایا تھا، کہ رسول اللہ صلی اللہ علیہ وسلم نے عثمان بن ابو طلحہ رضی اللہ عنہ کی طرف پیغام بھیجا۔ اور ایک بار انہوں نے یہ کہا کہ انہوں نے عثمان رضی اللہ عنہ سے پوچھا کہ نبی صلی اللہ علیہ وسلم نے تمہیں کیوں بلایا تھا؟ انہوں نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے مجھ سے فرمایا: ’’جب میں بیت اللہ میں داخل ہوا تو میں نے مینڈھے کے دونوں سینگوں کو دیکھا تو میں تمہیں یہ کہنا بھول گیا کہ ان دونوں سینگوں کو ڈھانپ دو، پس انہیں ڈھانپ دو کیونکہ بیت اللہ میں کوئی ایسی چیز نہیں ہونی چاہیے جو نمازی کو مشغول کر دے۔‘‘ (مسند أحمد) سفیان رحمہ اللہ کہتے ہیں کہ یہ دونوں سینگ بیت اللہ میں لٹکے رہے حتیٰ کہ ایک بار جب بیت اللہ کو آگ لگی تو یہ دونوں سینگ بھی جل گئے۔ یہ بھی اس بات کی مستقل دلیل ہے کہ ذبیح اللہ سیّدنا اسماعیل علیہ السلام ہیں کیونکہ قریش میں خلفا عن سلف یہ دونوں سینگ وراثت میں منتقل ہوتے چلے آئے ہیں حتیٰ کہ اللہ تعالیٰ نے اپنے رسول صلی اللہ علیہ وسلم کو مبعوث فرما دیا ہے اور یہ سینگ اس مینڈھے کے تھے جسے سیّدنا ابراہیم علیہ السلام نے بطور فدیہ قربان کیا تھا۔ وَاللہُ أَعْلَمُ."],[6159,"§ذبیح کون؟\nسعید بن جبیر، عامر شعبی، یوسف بن مہران، مجاہد، عطاء اور دیگر کئی مفسرین رحمہ اللہ نے سیّدنا ابن عباس رضی اللہ عنہما سے روایت کیا ہے کہ اسماعیل علیہ السلام ہی ذبیح ہیں۔ (تفسیر الطبری: 99/23،100) ابن جریر رحمہ اللہ نے ابن عباس رضی اللہ عنہما سے روایت کیا ہے کہ جن کا فدیہ دیا گیا تھا وہ اسماعیل علیہ السلام ہیں جبکہ یہودیوں کا کہنا ہے کہ وہ اسحاق علیہ السلام تھے مگر یہودی جھوٹ بولتے ہیں۔ (تفسیر الطبری:99/23) سیّدنا ابن عمر رضی اللہ عنہما سے روایت ہے کہ ذبیح سیّدنا اسماعیل علیہ السلام ہیں۔ (تفسیر الطبری:99/23) ابن ابو نجیح نے مجاہد رحمہ اللہ سے روایت کیا ہے کہ وہ اسماعیل علیہ السلام ہیں۔ (تفسیر الطبری:100/23) یوسف بن مہران کا بھی یہی قول ہے۔ (تفسیر الطبری:99/23،100) شعبی رحمہ اللہ کہتے ہیں کہ وہ اسماعیل علیہ السلام ہیں اور میں نے مینڈھے کے دونوں سینگوں کو کعبہ میں دیکھا تھا۔ (تفسیر الطبری:100/23)\nمحمد بن اسحاق رحمہ اللہ نے حسن بن دینار رحمہ اللہ اور عمرو بن عبید رحمہ اللہ سے اور انہوں نے حسن بصری رحمہ اللہ سے روایت کیا ہے کہ انہیں اس بات میں کوئی شک نہیں کہ سیّدنا ابراہیم علیہ السلام کے دونوں بیٹوں میں سے جس کے ذبح کرنے کا حکم دیا گیا تھا وہ اسماعیل علیہ السلام تھے۔ (تفسیر الطبری: 100/23،101) ابن اسحاق رحمہ اللہ نے کہا ہے کہ میں نے محمد بن کعب قرظی رحمہ اللہ سے سنا، وہ بیان کرتے تھے کہ اللہ تعالیٰ نے سیّدنا ابراہیم علیہ السلام کو اپنے دونوں بیٹوں میں سے اسماعیل علیہ السلام کے ذبح کرنے کا حکم دیا تھا اور کتاب اللہ سے بھی اس کی تائید ہوتی ہے اور وہ اس طرح کہ اللہ تعالیٰ نے اس بیٹے کے ذکر کے بعد جسے ذبح کرنے کا حکم دیا تھا، فرمایا ہے: ﴿وَ بَشَّرْنٰهُ بِاِسْحٰقَ نَبِيًّا مِّنَ الصّٰلِحِيْنَ۰۰۱۱۲﴾ ’’اور ہم نے اسے اسحاق کی بشارت دی جو صالح لوگوں میں سے نبی ہو گا۔‘‘ اور دوسری جگہ فرمایا ہے: ﴿وَ بَشَّرْنٰهُ بِاِسْحٰقَ١ۙ وَ مِنْ وَّرَآءِ اِسْحٰقَ يَعْقُوْبَ۰۰۷۱﴾ (ھود:71) ’’پھر ہم نے اسے اسحاق کی اور اسحاق کے بعد یعقوب کی خوش خبری دی۔‘‘ یعنی بیٹے اور پوتے کی خوشخبری دی اور یہ نہیں ہو سکتا کہ اللہ تعالیٰ اسحاق کے ذبح کرنے کا بھی حکم دے اور پھر اس سے اولاد کی بشارت بھی سنائے، لہٰذا یقینی اور حتمی بات یہ ہے کہ جس بیٹے کے ذبح کرنے کا اللہ تعالیٰ نے حکم دیا وہ اسماعیل علیہ السلام ہی تھے۔ (تفسیر الطبری:100/23) اور ابن اسحاق رحمہ اللہ کہتے ہیں کہ میں نے محمد بن کعب قرظی رحمہ اللہ سے یہ بات بکثرت سنی تھی۔ (تفسیر الطبری:101/23)\nابن اسحاق رحمہ اللہ نے بریدہ بن سفیان بن فروہ اسلمی رحمہ اللہ سے اور انہوں نے محمد بن کعب قرظی رحمہ اللہ سے روایت کیا ہے، انہوں نے بیان کیا کہ انہوں نے امیر المومنین سیّدنا عمر بن عبدالعزیز رحمہ اللہ سے یہ ذکر کیا جبکہ آپ ان کے ساتھ شام میں تھے تو سیّدنا عمر بن عبدالعزیز نے ان سے فرمایا کہ یہ بات مجھے پہلے معلوم نہ تھی اور میری رائے میں آپ صحیح کہہ رہے ہیں، پھر انہوں نے شام کے ایک شخص کو بلایا جو پہلے یہودی تھا پھر مسلمان ہو گیا اور وہ ایک اچھا مسلمان ثابت ہوا تھا، اس کا تعلق یہود کے علماء میں سے تھا، سیّدنا عمر بن عبدالعزیز رحمہ اللہ نے ان سے اس بارے میں پوچھا اور محمد بن کعب رحمہ اللہ کہتے ہیں کہ میں اس وقت سیّدنا عمر بن عبدالعزیز رحمہ اللہ کے پاس ہی تھا، سیّدنا عمر رضی اللہ عنہ نے ان سے پوچھا کہ سیّدنا ابراہیم علیہ السلام کے کون سے بیٹے کے بارے میں انہیں ذبح کرنے کا حکم دیا گیا تھا؟ اس نے جوا ب دیا: اسماعیل، اے امیر المومنین! اللہ کی قسم! یہودیوں کو بھی یہ بات معلوم ہے مگر وہ عربوں سے حسد کرتے ہیں کہ تمہارے باپ کو اللہ تعالیٰ نے یہ شرف عطا فرمایا ہو، حالانکہ انہیں یہ شرف وفضل اللہ تعالیٰ کے حکم پر صبر کرنے کی وجہ سے حاصل ہوا تھا مگر یہود اس کے منکر ہیں اور وہ کہتے ہیں کہ یہ شرف ابراہیم کے بیٹے اسحاق کو حاصل ہوا تھا کیونکہ سیّدنا اسحاق علیہ السلام ان کے باپ ہیں، حالانکہ اللہ تعالیٰ کو خوب معلوم ہے کہ وہ سیّدنا ابراہیم علیہ السلام کا کون سا بیٹا تھا، ہاں! البتہ سیّدنا ابراہیم علیہ السلام کے دونوں بیٹے ہی طاہر، طیب اور اللہ تعالیٰ کے اطاعت گزار تھے۔ (تفسیر الطبری:101/23)\nعبداللہ بن امام احمد بن حنبل رحمہ اللہ نے کہا ہے کہ میں نے اپنے والد گرامی (امام احمد رحمہ اللہ) سے پوچھا کہ ذبیح کون ہیں اسماعیل یا اسحاق؟ انہوں نے فرمایا: اسماعیل۔ انہوں نے اسے کتاب الزہد میں ذکر کیا ہے۔ (الزہد لابن حنبل، زہد عبید بن عمیر، رقم:2321) اور ابن ابو حاتم رحمہ اللہ کہتے ہیں کہ میں نے اپنے والد (امام ابو حاتم رحمہ اللہ) کو یہ فرماتے ہوئے سنا کہ صحیح بات یہ ہے کہ ذبیح سیّدنا اسماعیل علیہ السلام ہیں، انہوں نے یہ بھی کہا کہ سیّدنا علی، ابن عمر، ابو ہریرہ، ابو الطفیل رضی اللہ عنہم، سعید بن مسیب، سعید بن جبیر، حسن، مجاہد، شعبی، محمد بن کعب قرظی، ابو جعفر محمد بن علی اور ابو صالح رحمہم اللہ سے مروی ہے کہ ذبیح سیّدنا اسماعیل علیہ السلام ہیں۔ (تفسیر ابن أبی حاتم:3223/10) امام بغوی رحمہ اللہ نے اپنی تفسیر میں لکھا ہے کہ عبداللہ بن عمر رضی اللہ عنہما، سعید بن مسیب، سدّی، حسن بصری، مجاہد، ربیع بن انس، محمد بن کعب اور کلبی رحمہ اللہ کا بھی یہی مذہب ہے۔ (تفسیر البغوی:36/4) سیّدنا ابن عباس رضی اللہ عنہما سے بھی یہی روایت ہے، نیز ابو عمرو بن علاء رحمہ اللہ سے بھی اسی طرح مروی ہے۔ (تفسیر البغوی:36/4)\nامام ابن جریر رحمہ اللہ نے صنابحی رحمہ اللہ سے روایت کیا ہے کہ ہم سیّدنا معاویہ بن ابو سفیان رضی اللہ عنہما کے پاس بیٹھے ہوئے تھے کہ اس بات کا ذکر شروع ہو گیا کہ ذبیح سیّدنا اسماعیل علیہ السلام ہیں یا سیّدنا اسحاق علیہ السلام؟ انہوں نے فرمایا کہ تم نے باخبر شخص سے پوچھا ہے، ہم ایک بار رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر تھے، ایک شخص آیا اور اس نے عرض کی: اے اللہ کے رسول صلی اللہ علیہ وسلم ! اے دو ذبیحوں کے صاحبزادے! مجھے بھی اس مال سے دیجئے جو اللہ تعالیٰ نے آپ کو عطا فرمایا ہے، رسول اللہ صلی اللہ علیہ وسلم یہ بات سن کر ہنسنے لگے۔ امیر معاویہ رضی اللہ عنہ کی خدمت میں عرض کی گئی: امیر المومنین! دو ذبیحوں سے کیا مراد ہے؟ انہوں نے فرمایا کہ عبدالمطلب کو جب زمزم کے کھودنے کا حکم دیا گیا تو انہوں نے اللہ تعالیٰ کے لیے یہ نذر مانی تھی کہ اگر اللہ تعالیٰ ان کے لیے اس کام میں آسانی پیدا فرما دیں تو وہ اپنے ایک بیٹے کو ذبح کر دیں گے اور اس سلسلے میں جب قرعہ عبداللہ کے نام نکلا تو ان کے ماموئوں نے عبدالمطلب کو عبداللہ کو ذبح کرنے سے روک دیا اور کہا کہ اپنے بیٹے کے بجائے سو اونٹ فدیے کے طور پر قربان کر دو تو عبدالمطلب نے عبداللہ کے بجائے سو اونٹ فدیے کے طور پر قربان کر دیے تھے جس کی وجہ سے عبداللہ بچ گئے تو ایک ذبیح یہ ہیں اور دوسرے ذبیح سیّدنا اسماعیل علیہ السلام ہیں۔ (تفسیر الطبری:101/23،102)\nابراہیم علیہ السلام نے شام کی مقدس سرزمین میں پہنچنے کے بعد دعا کی کہ اے میرے رب! مجھے ایک نیک لڑکا عطا فرما جو غریب الدیاری میں میرے اُنس ودل بستگی کا سامان بنے اور تیری طاعت وبندگی میں میری مدد کرے۔ اللہ نے ان کی دعا قبول فرمالی اور ہاجرہ کے بطن سے اسماعیل علیہ السلام پیدا ہوئے۔ پھر اللہ کے حکم سے ماں اور بیٹے کو مکہ کی بے آب وگیاہ وادی میں پہنچا دیا، جہاں اللہ نے اپنے فضل و کرم سے آب زمزم مہیا کر دیا اور قبیلۂ جُرہم کو لا کر بسادیا۔ اسماعیل علیہ السلام جب جوان ہوئے تو اللہ نے ابراہیم علیہ السلام کو خواب میں بذریعہ وحی حکم دیا کہ وہ اپنے رب کی خوشنودی کے لیے اپنے چہیتے بیٹے کی قربانی دیں، انہوں نے اپنا خواب بیٹے سے بیان کیا اور ان سے مشورہ طلب کیا تو بیٹے نے کہا،ابا جان! آپ کو جو حکم ہوا ہے اسے کرگذرئیے، ان شاء اللہ آپ مجھے صبر کرنے والا پائیں گے۔ ابراہیم علیہ السلام بیٹے کو ساتھ لے کر منٰی کی طرف چل پڑے اور جمرات کی جگہ پہنچ کر انہیں پیشانی کے بل ڈال دیا اور چُھری ان کی گردن پر رکھ دی۔ اچانک دیکھتے کیا ہیں کہ وہاں ایک مینڈھا کھڑا ہے، ایک غیبی آواز آئی کہ آپ بیٹے کو چھوڑ دیجئے اور مینڈھے کو ذبح کیجئے۔ آیت (4)سے آگے تک یہی کچھ بیان کیا گیا ہے، اللہ تعالیٰ نے فرمایا کہ ہم نے ابراہیم علیہ السلام کو آواز دی اور کہا کہ آپ نے اپنا خواب سچ کر دکھایا، اورکمالِ طاعت اور عظیم ترین صبر و ثبات کی دلیل پیش کر دی۔ اب آپ بیٹے کو ذبح نہ کیجئے، ہم احسان اور عمل کرنے والوں کو ایسا ہی بدلہ دیتے ہیں، بے شک یہی وہ کھلی اور صریح آزمائش ہے جس کے ذریعہ مخلص وغیر مخلص کا امتیاز ہوجاتا ہے۔\nمفسرین لکھتے ہیں : آیت ِ کریمہ (106)میں اس طرف اشارہ کیا گیا ہے کہ خواب کی تعمیل میں ابراہیم علیہ السلام کا امتحان تھا تاکہ وہ اپنے عزیز بیٹے کی قربانی دے کر اللہ سے اپنی غایت محبت اور انتہائے طاعت و بندگی کا ثبوت بہم پہنچائیں۔ چنانچہ جب وہ اس امتحان میں کامیاب ہو گئے، تو اللہ نے ایک مینڈھا بھیج دیا تاکہ بیٹے کے بدلے اسے ذبح کریں۔"],[6160,"§شام کی طرف ہجرت\nجب آپ کا باپ اور آپ کی ساری قوم آپ کی جانی دشمن بن گئی تو آپ نے ترکِ وطن کا فیصلہ کر لیا کہ اب یہاں سے نکل جانا ہی بہتر ہے۔ نکلتے وقت یہ بھی معلوم نہ تھا کہ کہاں جانا ہے۔ فقط اتنا کہا کہ میں اللہ کی خاطر ہجرت پر روانہ ہوا ہوں۔ مجھے کہاں جانا چاہیے یہ بات میرا پروردگار مجھے خود ہی بتائے گا اور میری رہنمائی فرمائے گا۔ چنانچہ اللہ تعالیٰ کی طرف سے آپ کو شام کی طرف جانے کا حکم ہوا اور آپ اپنی بیوی اور بھتیجا یا چچا زاد بھائی سیدنا لوط علیہ السلام سمیت شام کی طرف چلے گئے اس وقت تک صرف سیدنا لوط علیہ السلام ہی آپ پر ایمان لائے تھے۔ اور آپ کی اس وقت تک کوئی اولاد بھی نہ تھی۔"],[6161,"§سیدنا اسماعیل علیہ السلام کی بشارت\nآپ گھر بار اور عزیز واقارب چھوڑ کر شام کے علاقہ میں آئے۔ کافی عمر ہونے کے باوجود ابھی تک اولاد نہ تھی لہٰذا اللہ سے دعا کی کہ مجھے ایک صالح بیٹا عطا فرما جو میرے گھر کی رونق بنے۔ اللہ تعالیٰ نے آپ کو جس بیٹے کی بشارت دی اس کی نمایاں صفت حلیم تھی اور اس صفت میں سیدنا اسماعیل علیہ السلام کے قربانی کے واقعہ اور اس موقع پر ان کے بردبار ہونے کی طرف لطیف اشارہ پایاجاتا ہے۔"],[6162,"§بیٹے کو ذبح کرنے کے متعلق خواب\nسیدنا اسماعیل علیہ السلام جب اس عمر کو پہنچے جب وہ اپنے باپ کے کاموں میں ان کا ہاتھ بٹا سکتے تھے تو سیدنا ابراہیم علیہ السلام کو ایک اور بہت بڑی آزمائش میں ڈالا گیا۔ آپ علیہ السلام کو تین راتیں مسلسل خواب آتا رہا جس میں آپ دیکھتے تھے کہ آپ اسی بیٹے کو جسے آپ نے اللہ سے دعا کرکے لیا تھا اور جو آپ کے بڑھاپے میں آپ کا سہارا بن رہاتھا، ذبح کر رہے ہیں چنانچہ آپ نے سمجھ لیا کہ یہ اللہ کی طرف سے حکم ہے۔"],[6163,"§بیٹے سے سوال\nچنانچہ سیدنا ابراہیم علیہ السلام نے اپنے نوجوان بیٹے کو یہ خواب بتا کر ان کی رائے دریافت کی۔ آپ علیہ السلام نے یہ رائے اس لیے دریافت نہیں کی تھی کہ اگر بیٹا اس بات پر آمادہ نہ ہو یا وہ انکار کر دے تو آپ علیہ السلام اللہ کے اس کے حکم کی تعمیل سے بازرہیںگے بلکہ اس لیے پوچھا تھا کہ آیا یہ فی الواقع بیٹا ثابت ہوتا ہے یا نہیں ؟ کیونکہ آپ علیہ السلام نے جو دعا کی تھی وہ صالح بیٹے کے لیے کی تھی۔"],[6164,"§نبی کا خواب وحی ہوتا ہے\nاس سے معلوم ہوا کہ خواب سن کر سیدنا اسماعیل علیہ السلام بھی اسی نتیجہ پر پہنچے تھے کہ اللہ کا حکم ہے جس سے یہ نتیجہ مستنبط ہوتا ہے کہ نبی کا خواب بھی وحی ہوتا ہے اور اس کی تائید بعض دوسری آیات اور احادیث سے بھی ہوجاتی ہے۔"],[6165,"§بیٹے کی بے مثال فرمانبرداری\nسیدنا اسماعیل علیہ السلام اس قدر خندہ پیشانی اور فراخ دلی سے قربان ہونے کو تیار ہوگئے جس کی دوسری کوئی مثال دنیا میں مل نہیں سکتی وہ ایک نہایت صالح اور انتہائی فرمانبردار بیٹے ثابت ہوئے۔ کیونکہ بیٹے کی قربانی دینے کا حکم تو باپ کو ہوا تھا۔ بیٹے کو قربان ہوجانے کا حکم نہیں ہو اتھا۔ بیٹے نے اپنے والد کا فرمان بلاچون و چرا تسلیم کرکے اپنے والد کی بھی انتہائی خوشنودی حاصل کر لی اور اپنے پروردگار کی بھی۔"],[6166,"§قربانی کامنظر\nسیدنا ابراہیم علیہ السلام نے اپنے بیٹے کو پیشانی کے بل اس لیے لٹایا کہ کہیں پدرانہ شفقت تعمیل حکم ِ الٰہی میں آڑے نہ آجائے۔ اور چھری چلاتے وقت ہاتھ میں لغزش نہ واقع ہو۔ منہ کے بل لٹانے سے نہ بیٹے کا چہرہ نظر آئے گا نہ پدرانہ جذبات برانگیختہ ہوں گے۔ کہتے ہیں کہ سیدنا اسماعیل علیہ السلام نے اسی مصلحت کے پیش نظر خود اپنے والد محترم کو ایسا مشورہ دیا۔"],[6167,"§باپ بیٹے کا امتحان میں سرفراز ہونا\nجب باپ اور بیٹا دونوں نے اللہ کی فرمانبرداری کی بے نظیر مثال قائم کر دی تو اس وقت رحمت ِ الٰہی جوش میں آگئی۔ اور فوراً سیدنا ابراہیم علیہ السلام پر وحی ہوئی کہ بس اس سے زیادہ کچھ نہ کرو۔ ہمیں تو صرف تمہارا امتحان لینا مقصود تھا۔ اور وہ وہ چکا جس میں تم پوری طرح کامیاب اُترے ہو۔ ہمارا یہ مقصود ہر گز نہ تھا کہ تم فی الواقع بیٹے کو ذبح کر ڈالو۔ واضح رہے کہ سیدنا ابراہیم علیہ السلام نے جو خواب دیکھا تو وہ یہ تھا کہ ’’میں ذبح کر رہا ہوں۔‘‘ یہ نہیں دیکھا تھاکہ ’’میں نے ذبح کر دیا ہے ‘‘اور جتنا خواب آپ نے دیکھا تھا اتنا کام ہو چکا تو آگے ذبح کر دینے سے اللہ تعالیٰ نے روک دیا۔"],[6168,"§بیٹے کی قربانی کافدیہ\nیہ ذبح عظیم ایک سینگ دارمینڈھا تھا جسے فرشتوں نے عین موقع پر لا کر حاضر کر دیا اور کہا تھا کہ بیٹے کی جگہ اسے قربان کر دو۔ یہی جانثار بیٹے کا فدیہ تھا جسے اللہ نے بھیجا تھا۔ اس لحاظ سے یہ عظیم قربانی تھی اور اس کے عظیم ہونے کی دوسری وجہ یہ بھی تھی کہ قیامت کے لیے اللہ تعالیٰ نےیہ سنت جاری کر دی کہ اسی تاریخ کو دنیا بھر کے اہل ایمان جانور قربان کریں۔ اور وفاداری اور جانثاری کے اس عظیم واقعہ کی یاد تازہ کرتے رہیں۔"],[6169,"§ذبیح اللہ سیدنا اسماعیل تھے یا سیدنا اسحاق علیہما السلام\nبعض لوگوں کا خیال ہے کہ ذبیح اللہ سیدنا اسماعیل علیہ السلام نہیں بلکہ سیدنا اسحاق علیہ السلام تھے۔ ان کا نظریہ درج ذیل وجوہ کی رُو سے درست معلوم نہیں ہوتا۔\n(1)اسی سورہ میں پہلے سیدنا ابراہیم علیہ السلام کے اس بیٹے کا ذکر آیا جو فی الواقع ذبیح اللہ تھے اور اس کے بعد سیدنا اسحاق علیہ السلام کا ذکر اسی سورہ کی آیت نمبر (112)میں آرہا ہے۔\n(2)جب سیدنا اسماعیل علیہ السلام کی بشارت دی گئی تو اس کے ساتھ حلیم کی صفت مذکور ہے۔ اور اس کا تعلق قربانی سے ہے۔ اور جب سیدنا اسحاق علیہ السلام کی بشارت دی گئی تو اس کے ساتھ صفت علیم ذکر کی گئی (15: 53،51:28)اور اس صفت کا قربانی سے کچھ تعلق نہیں۔ نیز جب سیدنا اسحاق علیہ السلام کی بشارت دی گئی تو ساتھ ہی یہ بتا دیا گیا کہ اسحاق علیہ السلام کے بعد ان کا بیٹا یعقوب بھی پیدا ہوگا۔ (11:71)اور ظاہر ہے جس بیٹے کے پوتے کی بھی بذریعہ وحی بشارت دی جا چکی ہو اس کے متعلق نوجوانی میں ہی قربانی کی وحی آنا محال ہے۔ کیونکہ پوتے کی بشارت پہلے دی جا چکی تھی۔\n(3)تورات میں یہ تصریح موجود ہے کہ سیدنا ابراہیم علیہ السلام کو اپنے اکلوتے اور محبوب بیٹے کو ذبح کرنے کا حکم دیا گیا تھا اور یہ بھی مسلم ہے کہ سیدنا اسماعیل علیہ السلام، سیدنا اسحاق علیہ السلام سے عمر میں بڑے تھے پھر سیدنا اسحاق علیہ السلام سیدنا اسماعیل علیہ السلام کی موجودگی میں اکلوتے کیسے ہو سکتے ہیں ؟\n(4)قربانی کی یاد گار اور اس سے متعلقہ رسوم بنی اسرائیل میں بطور وراثت مسلسل منتقل ہوتی چلی آئی ہیں حتی کہ دور نبوی میں بھی موجود تھیں۔ یہ بات بھی اس بات کی قوی دلیل ہے کہ ذبیح اللہ سیدنا اسماعیل تھے نہ کہ سیدنا اسحاق علیہ السلام۔"],[6170,"§احسان کا وسیع مفہوم\nقربانی اور اس سے متعلقہ رسوم مثلاً سعی صفا و مروہ وغیرہ کا تعلق مکہ سے ہے۔ اور یہ سیدنا اسماعیل علیہ السلام کا وطن تھا۔ سیدنا اسحاق علیہ السلام کا اصل وطن ملک شام تھا۔\nمُحْسِنِیْنَ کا ترجمہ اردو میں ایک دو لفظوں میں ادا کرنا بہت مشکل ہے۔ لہٰذا عموماً اس کا ترجمہ نیکی کرنے والے یانیکوکار کر دیاجاتا ہے۔إحْسَانٌ کا مطلب دراصل کسی کام کو بہتر سے بہتر طریق پر سر انجام دینا ہے۔ جیساکہ حدیث جبریل علیہ السلام سے واضح ہوتا ہے کہ جب سیدنا جبریل علیہ السلام نے آپ صلی اللہ علیہ وسلم سے یہ سوال کیا کہ إحْسَانٌ کیا چیز ہے۔تو اس کے جواب میں آپ صلی اللہ علیہ وسلم نے فرمایا:’’تو اللہ کی عبادت ایسے کرے جیسے تواسے دیکھ رہا ہے اور اگر یہ نہ ہو سکے تو کم ازکم اتنا تو سمجھے کہ وہ تجھے دیکھ رہا ہے ‘‘ (متفق علیہ) اور احسان میں کم ازکم تین باتوں کا ہونا ضروری ہے :(1)جو کام کیاجائے پوری خلوص نیت سے اور رضائے الٰہی کے لیے کیا جائے۔ (2)حکم کی تعمیل محض اطاعت کے جذبہ سے نہ ہو بلکہ اس میں مطاع کی محبت کا جذبہ بھی شامل ہو۔ اور (3)کام کے آداب وارکان کو اس طریقہ پر سر انجام دیاجائے جو بہتر سے بہتر ہو سکتے ہیں۔\nاور سیدنا ابراہیم علیہ السلام نے چونکہ ہر کام احسان کے ساتھ کیا تھا۔ لہٰذا اللہ نے دنیا میں انہیں دو طرح سے بدلہ دیا ایک یہ کہ رہتی دنیا تک ان پر سلامتی کی دعائیں کی جایا کریں۔ جیسا کہ ہم ہر نماز میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ سیدناابراہیم علیہ السلام اور ان کی آل پر بھی درود سلام کی دعا کرتے ہیں اور دوسرے یہ کہ اکثر مذاہب والے انہیں اپنا روحانی پیشوا تسلیم کرتے ہیں۔ ان سے نسبت جوڑنے میں فخر محسوس کرتے ہیں اور ان کا ذکر اچھے الفاظ میں ہی کرتے ہیں۔\nمعلوم ہواکہ پہلی خوشخبری کا تعلق سیدنا اسماعیل علیہ السلام سے ہی ہے۔ اور قصہ ذبح کا تعلق انہی سے ہے۔ اس کے بعد دوسری بار سیدنا ابراہیم علیہ السلام کو سیدنا اسحاق علیہ السلام کی خوشخبری دی گئی۔\nذُرّیّتِہِمَا میں تنبیہ کی ضمیر سیدنا ابراہیم علیہ السلام اور سیدنا اسماعیل علیہ السلام کی طرف بھی راجع ہو سکتی ہے اور سیدنا اسماعیل علیہ السلام اور سیدنا اسحاق علیہ السلام کی طرف بھی۔ جن سے دو بڑی قومیں پیدا ہوئیں۔ ایک بنی اسماعیل اور دوسرے بنی اسرائیل۔ بنو اسماعیل میں صرف نبی آخر الزمان مبعوث ہوئے جبکہ بنی اسرائیل میں بے شمار انبیاء پیدا ہوئے اور اچھے اور بُرے لوگ ان دونوں قوموں میں موجود رہے۔\nہر انسان کے منہ (چہرے) پر دو جبینیں (دائیں اور بائیں) ہوتی ہیں اور درمیان میں پیشانی (حَبْھَةٌ) اس لیے ﴿لِلْجَبِیْنِ﴾ کا زیادہ صحیح ترجمہ کروٹ پر ہے یعنی اس طرح کروٹ پر لٹا لیا، جس طرح جانور کو ذبح کرتے وقت قبلہ رخ کروٹ پر لٹایا جاتا ہے۔ ’’پیشانی یا منہ کے بل لٹانے کا‘‘ ترجمہ اس لیے کیا جاتا ہے کہ مشہور ہے سیّدنا اسماعیل علیہ السلام نے وصیت کی کہ انہیں اس طرح لٹایا جائے کہ چہرہ سامنے نہ رہے جس سے پیار و شفقت کا جذبہ امر الٰہی پر غالب آنے کا امکان نہ رہے۔ یعنی ان دونوں کی اولاد کو بہت پھیلایا اور انبیاء و رسل کی زیادہ تعداد انہی کی نسل سے ہوئی۔ سیّدنا اسحاق علیہ السلام کے بیٹے یعقوب ہوئے، جن کے بارہ بیٹوں سے بنی اسرائیل کے بارہ قبیلے بنے اور ان سے بنی اسرائیل کی قوم بڑھی اور پھیلی اور اکثر انبیاء ان ہی میں سے ہوئے۔ سیّدنا ابراہیم علیہ السلام کے دوسرے بیٹے اسماعیل سے عربوں کی نسل چلی اور ان میں آخری پیغمبر سیّدنا محمد رسول اللہ صلی اللہ علیہ وسلم ہوئے۔\nوَ قَالَ اِنِّيْ ذَاهِبٌ اِلٰى رَبِّيْ سَيَهْدِيْنِ: جب اللہ تعالیٰ نے ابراہیم علیہ السلام کو کفار کے مکر سے تحفظ عطا کیا اور مشتعل آگ میں زندہ رکھا تو انھوں نے خود کو وہاں سے نکالناچاہا اور وہاں جاناچاہا جہاں جانے کا ان کے پروردگار انھیں حکم دیں گے، چنانچہ بعض مفسرین کی رائے کے مطابق ابراہیم علیہ السلام پہلے وہ شخص ہیں جنہوں نے اپنی بیوی سارا کے ساتھ ملک شام کی جانب سفر کیا اور دعا کی اے میرے پروردگار مجھے صالح بیٹا عطا کر جو میری تنہائی میں میرا مونس اور غمخوار ہو مقصو د یہ تھا کہ اب جب کہ میں اپنی قوم اور قبیلہ سے الگ ہوگیا ہوں تو ان لوگو کے قائم مقام مجھے صالح اطاعت گزار اولاد عطا فرما تو ہم نے ان کی دعا کو قبولیت عطا کی اور ہم نے انھیں ایک لڑکے کے تَوَلَّد پذیر ہونے کی بشارت عطا کی جو بڑا ہو کر بھی حلم و تواضع کے وصف کے ساتھ موصوف ہوگا گویا کہ تین بشارتوں سے نوازا گیا کہ آپ کے گھرلڑکا پیدا ہوگا وہ سن بلوغت تک پہنچے گا مزیدبرآں وہ حلم وبردباری کے وصف کے ساتھ موصوف ہوگا جب کہ کسی بچے کے بارے میں اس کے بچپن کے دور میں نہیں معلوم کیا جاسکتا کہ اس میں حلم کا وصف پایاجاتا ہے یا نہیں اور اسماعیل علیہ السلام کے حلم کے مقابلہ میں کون ایسافرد ہے جوان کے حلم کا مقابلہ کرسکے جب کہ ان کے باپ نے ان پر اپنے خواب کو پیش کیا کہ میں نے خواب میں دیکھا ہے کہ میں تجھے ذبح کررہاہوں تو اسماعیل علیہ السلام نے بلاتردّد اور بلاتوقف کے کہا اے میرے ابا، آپ کو جس کام کے کرنے کا حکم دیا گیا ہے اسے کرگزریں اگر اللہ تعالیٰ نے چاہاتو آپ مجھے صبراختیار کرنے والوں سے پائیں گے معلوم ہوا کہ ذبیح اسماعیل علیہ السلام ہیں جن کی بشارت دی گئی تھی جب کہ اللہ تعالیٰ نے ذبح کے واقعہ کی تکمیل کے بعد فرمایا اور ہم نے ابراہیم کو اسحٰق پیغمبر کی بشارت عطا کی ان کا شمار صالحین سے ہے۔\nفَلَمَّا بَلَغَ مَعَهُ السَّعْيَ : جب اسماعیل علیہ السلام سن بلوغت کو پہنچے اور ان کا شباب بہارآفریں تھا وہ عمر کے اس حصے میں تھے جس میں لڑکے کے لیے ممکن ہوتا ہے کہ وہ اپنے باپ کے ساتھ اس کے مشاغل اور کاموں میں اس کے ساتھ تعاون کرے اس انداز کے ساتھ رواں دواں رہنے کی عمر تیرہ سال کی عمر ہے تو ابراہیم علیہ السلام نے اپنے بیٹے اسماعیل علیہ السلام کو بتایا اے میرے بیٹے مجھے خواب میں حکم دیا گیا کہ میں تجھے ذبح کروں چونکہ انبیاء علیہ السلام کے خواب وحی ہوتے ہیں اور پیغمبروں کے پاس اللہ کی جانب سے وحی بحالت بیداری اور سوتے بھی ہوتی ہے، اس لیے کہ انبیاء علیہم السلام کی آنکھیں نیند کے عالم میں نیند کرتی ہیں جب کہ ان کے دل بیدار ہوتے ہیں ﴿فَانْظُرْ مَا ذَا تَرٰى ﴾ آپ کی اس کے بارے میں کیا رائے ہے؟۔"]])